INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tfhj9', 'tfhj9', '2000 anos depois: o renascimento de Israel', NULL, '["Alexandre Lissovsky"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste nosso atribulado e turbulento século XX a criação do Estado de Israel é sem dúvida um acontecimento marcante. Com isso concretizou-se um sonho, um ideal, uma aspiração quase bimilenar. Foi precedido, porém, por um período – poderíamos chamá-lo de preparatório – longo e difícil, repleto de obstáculos, desilusões e sacrifícios. [trecho retirado da introdução do livro]', '["founding of the State of Israel","Zionism","Jewish national revival","20th century","Jewish history"]', '10.7476/9788579820038', '9788579820038', 'https://books.scielo.org/id/tfhj9', 'https://books.scielo.org/id/tfhj9/pdf/lissovsky-9788579820038.pdf', NULL, 'https://books.scielo.org/id/tfhj9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tfn8r', 'tfn8r', 'Teoria literária: abordagens históricas e tendências contemporâneas', 'abordagens históricas e tendências contemporâneas', '["Bonnici, Thomas","Zolin, Lúcia Osana"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Literatura em discussão. Esta parece ser a marca fundamental deste livro que reúne um grupo de especialistas em Letras, predominantemente de Maringá (PR), para introduzir, explicar, sugerir, criticar e, sobretudo, questionar pontos de interesse centrais no estudo da literatura. Partindo da pergunta primeira – O que é literatura? – e apresentando, a seguir, os “operadores” de leitura da narrativa, da poesia e do drama, já num terceiro momento, o mais longo deles, o livro detém-se em oito métodos de crítica literária – do Formalismo Russo à Crítica Genética, passando, por exemplo, pela Crítica Feminista e Psicanalítica, entre outras – num percurso que traduz a história dos modos de ler, mas, concomitantemente, o desenho de um fio da história das ideias culturas do século passado. Assim sendo, tem também como objeto de reflexão o conjunto de preocupações desta era que se chamou, a certa altura, de Pós-modernismo, em que os Estudo Culturais levaram à reconsideração das minorias étnicas e sexuais, bem como à intensificação das relações interdisciplinares, permitindo que se intensificasse o estudo das relações da literatura com a pintura e o cinema. Pois são estes os tópicos que ocupam os capítulos seguintes. Para executar esta proposta, aparentemente simples, mas minada de complexidade, os autores procuram manter certa homogeneidade de procedimentos, tarefa difícil, aliás, de ser conseguida, pela diversidade dos tópicos e dos problemas que cada tópico suscita. Conseguem, no entanto, assegurar uma razoável coerência interna no modo de exposição, que prima pela informação, de uma perspectiva didática, aliada à prática constante de um revisionismo crítico, procurando, a partir dessa coligação, atender à possibilidade de se favorecer a abertura reflexiva para novos horizontes de análise e interpretação. Dessa forma tentam evitar esquematismos rigorosos, que reduzem mais que dilatam as perspectivas de leitura, e conseguem favorecer as posturas individuais de abordagem, num fértil painel de diferentes modos de se comportar diante do objeto em questão. Se há ausências, há, por outro lado, realce a aspectos da crítica mais recente (das posturas feministas, por exemplo), que merecem mesmo ser incorporadas ao repertório das preocupações atuais. Esta acidentada viagem pela teoria literária do século passado cumpre assim sua principal meta, ao propiciar ao leitor, iniciante ou não, embasamento de caráter informativo e reflexivo que lhe permite ver ou rever criticamente as marcas mais contundentes da sua própria contemporaneidade. Reunir para discutir. Esta proposta bem sucedida do livro, que conseguiu reunir colegas para discutir a literatura e passar tal discussão a nós, leitores, é também a metáfora do trabalho ao mesmo tempo solitário e coletivo da docência e da pesquisa. Que o livro, ao refletir essa imagem da confraternização na crítica, leve cada um a refletir também sobre sua própria imagem: a de leitor que, se, de início, é um ser solitário, deve também, por princípio, manter-se atento ao debate, e, sempre que possível, aberto à reunião de novos parceiros em torno do livro.', '["literary theory","definition of literature","literary criticism methodology","Russian Formalism","genetic criticism","feminist criticism","psychoanalytic literary criticism","postmodernism","cultural studies","painting and literature","film and literature","reading practices"]', '10.7476/9786587626178', '9788576287568', 'https://books.scielo.org/id/tfn8r', NULL, NULL, 'https://books.scielo.org/id/tfn8r/cover/cover_thumbnail.jpeg', 459, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tfst3', 'tfst3', 'El peritoneo: descripción de un nuevo síndrome, falla peritoneal', NULL, '["Riveros Dueñas, Rafael E.","Isaza Restrepo, Andrés","Sefair Cristancho, Carlos"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'El peritoneo: descripción de un nuevo síndrome es el resultado de múltiples cuestionamientos surgidos durante la formación como médicos y cirujanos de los autores, referente a la función del peritoneo en el sentido orgánico específicamente en su aplicación práctica, sin perder de vista el beneficio para los pacientes y de sus familiares.', '["peritoneum","peritoneal membrane function","peritoneal surgery","surgical training"]', '10.7476/9789587385335', '9789587385182', 'https://books.scielo.org/id/tfst3', NULL, NULL, 'https://books.scielo.org/id/tfst3/cover/cover_thumbnail.jpeg', 106, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tg384', 'tg384', 'Gêneros e práticas culturais: desafios históricos e saberes interdisciplinares', NULL, '["Charliton José dos Santos Machado","Idalina Maria Freitas Lima Santiago","Maria Lúcia da Silva Nunes"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é resultado dos textos apresentados nas conferências e mesas redondas do I Seminário Nacional Gênero e Práticas Culturais, tendo como tema central: desafios históricos e saberes interdisciplinares, ocorrido em João Pessoa, entre os dias 4 a 6 de setembro de 2007. O evento organizou-se em 14 eixos temáticos que orientaram os grupos de trabalhos, duas conferências e seis mesas redondas, com a participação de aproximadamente 800 pessoas dos vários estados do Brasil e a apresentação de 280 comunicações orais distribuídas pelos diversos Gts. (trecho retirado do texto "Gênero e práticas culturais: desafios históricos e saberes interdisciplinares" do livro)', '["gender","cultural practices","interdisciplinary knowledge","history of gender studies","gender and culture"]', '10.7476/9788578791193', '9788578791193', 'https://books.scielo.org/id/tg384', 'https://books.scielo.org/id/tg384/pdf/machado-9788578791193.pdf', NULL, 'https://books.scielo.org/id/tg384/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tg43c', 'tg43c', 'Imagens do pai no cinema: clínica da cultura contemporânea', NULL, '["João Angelo Fantini"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro o psicanalista João Angelo Fantini discute questões como a violência, a transgressão e os sintomas encontrados na clínica atual, tendo como pano de fundo as formas como a figura do pai é encenada em diversas produções cinematográficas nesta passagem e início de século, especialmente aquelas que obtiveram grande público, como Matrix, Clube da Luta, Beleza Americana, Central do Brasil, De olhos bem fechados, entre outras. Partindo de Freud e Lacan, o autor realiza uma clínica da cultura, interligando imagens e conceitos em um percurso que aborda desde as origens históricas do lugar do pai na cultura até as questões contemporâneas do ciberespaço, abrindo novas perspectivas para entender os dilemas da constituição do sujeito em um mundo regido pelo império imagético. Destinada aos interessados em cinema, mídias e na cultura em geral, esta obra foi escrita não apenas para os iniciados em psicanálise, mas para todos os leitores que não podem prescindir de um estudo aberto sobre as sociedades do nosso tempo.', '["father figure","contemporary culture","violence","transgression","clinical symptoms","psychoanalysis of culture","Sigmund Freud","Jacques Lacan","subjectivation","digital culture","The Matrix","Central do Brasil"]', '10.7476/9788576003656', '9788576003656', 'https://books.scielo.org/id/tg43c', 'https://books.scielo.org/id/tg43c/pdf/fantini-9788576003656.pdf', NULL, 'https://books.scielo.org/id/tg43c/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tgy3m', 'tgy3m', 'Mitologia grega e bíblica: narrativas de transgressão', NULL, '["Éverton Nery Carneiro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Livro é fruto da pesquisa de doutorado do autor e trata de analisar as narrativas mitológicas gregas e bíblicas por um ponto de vista das transgressões. Foco em Dionísio e Jesus.', '["Greek mythology","biblical narrative","transgression","Dionysus","Jesus Christ","comparative mythology","narrative analysis"]', '10.7476/9786588211137', '9788578873509', 'https://books.scielo.org/id/tgy3m', 'https://books.scielo.org/id/tgy3m/pdf/carneiro-9786588211137.pdf', 'https://books.scielo.org/id/tgy3m/epub/carneiro-9786588211137.epub', 'https://books.scielo.org/id/tgy3m/cover/cover_thumbnail.jpeg', 401, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-th', 'th', 'Principais mosquitos de importância sanitária no Brasil', NULL, '["Rotraut A. G. B. Cônsoli","Ricardo Lourenço‐de‐Oliveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'SANITÁRIA NO BRASIL Principais Mosquitos de Importância Sanitária no Brasil possui informações concisas e atualizadas sobre os mosquitos vetores de doenças no Brasil.Aqui são fornecidos dados sobre a morfologia e a biologia das fases evolutivas de adulto, ovo, larva e pupa, sendo abordados aspectos referentes à sua nutrição, reprodução, comportamento e ecologia.Para a identificação de adultos e larvas são oferecidas chaves ilustradas abrangendo os Anofelinos e principais Culicíneos já encontrados no país.São apresentados textos específicos contendo informações sobre as principais espécies dos gêneros Anopheles, Aedes, Psorophora, Haemagogus e Culex, dentre outros.Com referência às medidas de controle, são abordados os métodos químicos, a questão da resistência aos inseticidas, bem como as perspectivas dos métodos', '["mosquitoes","disease vectors","Anopheles","Aedes","Psorophora","Haemagogus","Culex","mosquito morphology","mosquito life cycle","mosquito ecology","mosquito behavior","insecticide resistance"]', '10.7476/9788575412909', '9788575412909', 'https://books.scielo.org/id/th', 'https://books.scielo.org/id/th/pdf/consoli-9788575412909.pdf', NULL, 'https://books.scielo.org/id/th/cover/cover_thumbnail.jpeg', NULL, 863, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-thjdb', 'thjdb', 'Janelas indiscretas: ensaios de crítica biográfica', NULL, '["Eneida María de Souza"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro articula as relações teórico-ficcionais entre obra e vida em torno de temas comuns, como morte, doença, amor, ódio, suicídio e traição. Uma vez firmado o pacto ficcional, a vida do escritor reverte-se necessariamente em grafia, e a biografia se traduz em literatura. A crítica biográfica se pauta pela liberdade de montar perfis literários dos escritores e de imaginar encontros entre eles, uma forma de elucidar propostas poéticas, questões teóricas e contextuais. Por essa operação criativa, concebe-se tanto a vida quanto a ficção como domínios da representação e do artifício.', '["biographical criticism","life and fiction","death","illness","love","hatred","suicide","betrayal","literary profile","representation","artifice"]', '10.7476/9788542303032', '9788570418913', 'https://books.scielo.org/id/thjdb', NULL, NULL, 'https://books.scielo.org/id/thjdb/cover/cover_thumbnail.jpeg', 261, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-thwry', 'thwry', 'Conceptos introductorios al estudio de la información documental', NULL, '["José Antônio Moreiro González"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como o próprio título sugere, trata-se de uma obra que visa fundamentar teorias para os campos da Ciência da Informação - Bibilioteconomia e Documentação. O autor José Antônio Moreiro Gomez, um dos mestres da Universidad Carlos III em Madrid, capital espanhola, parte do princípio de que estes campos não podem se explicar, exclusivamente, através do caráter técnico-prático necessitando, assim, de conceitos introdutórios para um funcionamento mais adequado. Assim sendo, a obra tem como finalidade iniciar estudantes e estudiosos na compreensão da natureza da informação e seu processamento, assim como das disciplinas que tratam deste tema.', '["documentary information","information science","library and information science","documentation","nature of information","information processing"]', '10.7476/9788523211691', '9788523211691', 'https://books.scielo.org/id/thwry', 'https://books.scielo.org/id/thwry/pdf/gonzalez-9788523211691.pdf', NULL, 'https://books.scielo.org/id/thwry/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tj3ns', 'tj3ns', 'Alegrias engarrafadas: os alcoóis e a embriaguez na cidade de São Paulo no final do século XIX e começo do XX', NULL, '["Daisy de Camargo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro faz uma exuberante reconstituição da boemia paulistana entre os anos de 1860 e 1920, quando São Paulo teve a sua primeira fase de crescimento explosivo e a população saltou de pouco mais de 30 mil habitantes para algo em torno de 200 mil, graças à chegada em massa de imigrantes, principalmente italianos desencantados com a lavoura, e de estudantes de outros estados do país, a maioria deles para estudar na Faculdade de Direito do Largo São Francisco. Inspirado pelo trabalho do pensador alemão Walter Benjamin (1892-1940), que avaliou os gostos e costumes da Paris da Belle Époque, a autora retrata como eram as tabernas da época e como se comportavam os seus frequentadores, reconstituindo, assim, as relações sociais e pessoais que permeavam o consumo de álcool na São Paulo daquela época. Também faz um minucioso mapeamento da produção e do consumo de bebidas alcoólicas na cidade durante o período. A pesquisa ainda desvela, como pano de fundo, os gestos e sensibilidades do cotidiano da cidade nesse momento anterior à industrialização, captando costumes e modos de vida e pondo à mostra toda uma cultura gestual, material e historicamente construída, que logo acabaria por se transformar inteiramente.', '["alcohol consumption","drunkenness","taverns","Bohemia","São Paulo","late 19th century","early 20th century","Italian immigrants","students","Walter Benjamin","everyday life","social customs"]', '10.7476/9786557144954', '9786557144954', 'https://books.scielo.org/id/tj3ns', 'https://books.scielo.org/id/tj3ns/pdf/camargo-9786557144954.pdf', NULL, 'https://books.scielo.org/id/tj3ns/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tjyb3', 'tjyb3', 'Mas, afinal, para quê, então, filosofia? Uma leitura do Górgias de Platão', NULL, '["Fausto dos Santos Amaral Filho"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Antes de tudo é preciso dizer que a presente obra – “Mas, afinal, para quê, então, Filosofia: uma leitura do Górgias de Platão” – parte de uma concepção hermenêutica que leva em consideração o estilo literário através do qual Platão nos legou os seus escritos: o diálogo socrático. Obra de literatura e ficção que se assemelha a uma peça teatral. E que, assim sendo, nos impõe uma hermenêutica específica, da qual resulta, em primeiro plano, a necessidade de compreendê-la a partir da sua integralidade orgânica. Assim, tomando a obra como um todo, perseguindo a disposição dos personagens, vemos no transcorrer do texto uma discussão que, ao delimitar a filosofia em contraposição à retórica, acaba por revelar a pergunta fundamental pelo valor da vida ou, ainda melhor, acaba por questionar o modelo de vida que realmente teria valor. Seguindo a linearidade do diálogo, mostram-se os argumentos de Sócrates com seus dialogantes: Polo, Górgias e Cálicles. Mais especificamente, como Sócrates vai impondo a contradição a cada um dos participantes do diálogo, superando, assim, o modelo de vida proposto por eles. Dessa maneira, a obra, tendo o diálogo de Platão como referência, questiona qual seria o modo de vida mais adequado para se viver.', '["Plato","Gorgias","Socratic dialogue","Socrates","value of life","lifestyle","Callicles","Polemarchus","Socratic irony","contradiction"]', '10.7476/9788564905887', '9788564905887', 'https://books.scielo.org/id/tjyb3', 'https://books.scielo.org/id/tjyb3/pdf/amaral-9788564905887.pdf', NULL, 'https://books.scielo.org/id/tjyb3/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tk2j9', 'tk2j9', 'Internet y pobreza', NULL, '["Bernardo Sorj","Luís Eduardo Guedes"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Este trabajo i ntenta avanzar en la elaboración de políticas públicas a partir del análisis empírico de la dinámica de inclusión/exclusión digital en los sectores más pobres de la población, teniendo como base una amplia investigación cuantitativa y cualitativa en los barrios de bajos ingresos del municipio de Rio de Janeiro.La encuesta fue realizada en dos etapas, en el segundo semestre de 2003 en Rio de Janeiro.Cada una de estas etapas contó con 1.510 entrevistas, represent ando un universo de cerca de un millón doscientos mil individuos.La investigación fue complementada por la realización de reuniones con ocho grupos motivacionales con muestras de las diferentes grupos de edad y de género.3 La discusión sobre inclus ión digital como instrumento de lucha contra la pobreza y la desigualdad social está entrando en una nueva fase, fundada en evidencias empíricas.Estos estud ios permitirán ir más allá de las generalizaciones que dominar on el debate, que osciló entre aquellos que vendían la inclusión digital como una panacea para los males de l os países en des arrollo y los que la denunciaban como retórica vacía o al servicio de intereses comercia les de los países del primer mundo.En ambos casos eran mo vilizados ejemplos anecdóticos de éxito o fracaso sin representatividad y retirados del contexto social más amplio.', '["digital inclusion","digital exclusion","poverty","social inequality","public policy","low-income communities","Rio de Janeiro","internet access","developing countries"]', '10.7476/9788599662496', '9788599662496', 'https://books.scielo.org/id/tk2j9', 'https://books.scielo.org/id/tk2j9/pdf/sorj-9788599662496.pdf', NULL, 'https://books.scielo.org/id/tk2j9/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tkx8q', 'tkx8q', 'Teoria ator-rede e estudos de comunicação', NULL, '["André Lemos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro busca, principalmente, apresentar a Teoria Ator-Rede (TAR): uma corrente teórica ainda pouco explorada e conhecida na área de comunicação no Brasil, que leva em consideração processos de associação em rede através de mediações entre atores humanos e não humanos. Além disso, a obra é resultado de um experimento acadêmico envolvendo a aplicação da TAR aos estudos de comunicação, o que gerou a produção de textos que tratam de diversos aspectos da cultura e da comunicação contemporânea, tais como a fotografia, o cinema, as séries televisivas, os jornais, os movimentos políticos e as redes sociais.', '["actor-network theory","communication studies","human and non-human actors","mediation (cultural/media theory)","contemporary culture","photography","cinema","television series","newspapers","political movements","social networks"]', '10.7476/9788523220068', '9788523215248', 'https://books.scielo.org/id/tkx8q', NULL, NULL, 'https://books.scielo.org/id/tkx8q/cover/cover_thumbnail.jpeg', 205, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tkysm', 'tkysm', 'Rio de Janeiro: uma abordagem dialógica sobre o território fluminense', NULL, '["Penalva, Angela","Arícia Fernandes Correia","Gláucio José Marafon","Maria Josefina Gabriel Sant’Anna"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'cidade do Rio de Janeiro no primeiro quadrimestre de 2017 . . . . . . . . .', '["Rio de Janeiro","dialogical approach","urban territory","cities"]', '10.7476/9788575115169', '9788575115169', 'https://books.scielo.org/id/tkysm', 'https://books.scielo.org/id/tkysm/pdf/penalva-9788575115169.pdf', NULL, 'https://books.scielo.org/id/tkysm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tmbsy', 'tmbsy', 'O X de Malcolm e a questão racial norte-americana', NULL, '["Vladimir Miguel Rodrigues"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra aborda duas formas de representação da história de Malcolm Little (1925–1965) ou Al Hajj Malik Al-Shabazz, conhecido como Malcolm X. O autor compara duas biografias do ativista – o livro Autobiografia de Malcolm X, de 1965, do escritor e jornalista Alex Haley, e Malcolm X, filme de 1992 dirigido por Spike Lee –, apontando as aproximações e distanciamentos entre as produções literária e cinematográfica. Segundo o autor, ambas as biografias, criadas em um intervalo de quase 30 anos, construíram um Malcolm X como personagem heróico, o que resultaria da omissão por parte dos autores de passagens da vida do ativista e também acerca das influências ideológicas e dos diferentes momentos históricos em que as obras foram produzidas. Um dos protagonistas na luta contra a discriminação e o racismo em relação aos afrodescendentes nos Estados Unidos, Malcom X, convertido ao islamismo, percorreu uma trajetória política entre o radicalismo e a moderação. Em sua busca pela igualdade de direitos na sociedade norte-americana, enfrentou forte reação de conservadores defensores da supremacia branca e sofreu resistência, ainda, de grupos de líderes afrodescendentes rivais. Assim como Martin Luther King Jr., Malcolm X morreu assassinado, e deixou um legado, cujo último resultado foi a eleição do primeiro presidente negro dos Estados Unidos.', '["Malcolm X","Alex Haley","Spike Lee","historical representation","African American history","racism","racial discrimination","Black nationalism","political Islam","civil rights movement","white supremacy","Martin Luther King Jr."]', '10.7476/9786557144916', '9786557144916', 'https://books.scielo.org/id/tmbsy', 'https://books.scielo.org/id/tmbsy/pdf/rodrigues-9786557144916.pdf', NULL, 'https://books.scielo.org/id/tmbsy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tmdpt', 'tmdpt', 'Ecologia política: da desconstrução do capital à territorialização da vida', NULL, '["Enrique Leff"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As concepções capitalistas de progresso com crescimento sem limites da economia conduziram o planeta a uma crise ambiental sem precedentes. A ecologia política visa desconstruir essa racionalidade insustentável e impulsionar ações sociais para a construção de um futuro sustentável, reorientando o desenvolvimento das forças produtivas, recriando as formas de sociabilidade e reconfigurando as relações de poder. Esse pensamento tem ressonâncias no campo da produção e do conhecimento, da política e das práticas educativas. O ambientalismo radical confronta o poder hegemônico unificador do mercado como destino inelutável da humanidade e valoriza a diversidade cultural, os saberes tradicionais e os direitos humanos, fundando um pensamento emancipatório e uma ética política para renovar o sentido da vida e defender a preservação da natureza.', '["political ecology","critique of capitalism","environmental crisis","sustainable development","radical environmentalism","market power","sociability","power relations","traditional knowledge","human rights","emancipatory thought","political ethics"]', '10.7476/9788526815414', '9786586253627', 'https://books.scielo.org/id/tmdpt', NULL, NULL, 'https://books.scielo.org/id/tmdpt/cover/cover_thumbnail.jpeg', 503, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tmz6r', 'tmz6r', 'A universidade temporã: o ensino superior, da colônia à Era Vargas', NULL, '["Luiz Antônio Cuñha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Luiz Antônio Cunha estuda a origem e o desenvolvimento do ensino superior no Brasil, desde os "cursos de artes", abertos pelos jesuítas no século XVI, até a institucionalização do regime universitário, na era Vargas. Concebendo a universidade como um modo de organização do ensino superior, o foco da obra recai sobre a função desempenhada por esse grau de ensino na inculcação do saber dominante em cada momento.', '["higher education history","universities","colonial Brazil","Vargas era","Jesuit schools","university institutionalization","history of education in Brazil"]', '10.7476/9788539304578', '9788571397750', 'https://books.scielo.org/id/tmz6r', NULL, NULL, 'https://books.scielo.org/id/tmz6r/cover/cover_thumbnail.jpeg', 312, 79, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tn4y9', 'tn4y9', 'Água e democracia na América Latina', NULL, '["José Esteban Castro"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'This book addresses different aspects of the topic of water politics in Latin America published in Portuguese and Spanish, from the perspective of a sociology-grounded political ecology.', '["water politics","democracy","Latin America","political ecology","water governance"]', '10.7476/9788578794866', '9788578794866', 'https://books.scielo.org/id/tn4y9', 'https://books.scielo.org/id/tn4y9/pdf/castro-9788578794866.pdf', NULL, 'https://books.scielo.org/id/tn4y9/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tnbwh', 'tnbwh', 'Pesquisa em saúde coletiva: fronteiras, objetos e métodos', NULL, '["Virgínia Alonso Hortale","Carlos Otávio Fiúza Moreira","Regina Bodstein","Célia Leitão Ramos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Oferece a estudantes, docentes, pesquisadores e profissionais da área um panorama abrangente dos principais debates contemporâneos em saúde coletiva. Os caminhos da pesquisa, questões conceituais, a procura de validade metodológica, a polêmica entre diferentes disciplinas e o confronto entre diversos paradigmas, teorias e abordagens estão entre os tópicos discutidos. Também busca responder às necessidades das diversas fases de pesquisa, da elaboração do projeto à apresentação dos resultados.', '["research methodology","methodological validity","research paradigms","interdisciplinary debate","research design","research project development","research dissemination"]', '10.7476/9788575413470', '9788575412008', 'https://books.scielo.org/id/tnbwh', NULL, NULL, 'https://books.scielo.org/id/tnbwh/cover/cover_thumbnail.jpeg', 238, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tndbc', 'tndbc', 'Fundamentos da Paleoparasitologia', NULL, '["Luiz Fernando Romanholo Ferreira","Karl Jan Reinhard","Adauto Araújo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Iniciativa inédita no mundo, o livro compila o conhecimento disponível sobre o assunto e apresenta o estado da arte em paleoparasitologia – termo cunhado há cerca de 30 anos por um brasileiro, o pesquisador da Fiocruz Luiz Fernando Ferreira, pioneiro dessa ciência voltada para o estudo dos parasitos no passado. Multidisciplinar por essência, a paleoparasitologia reúne contribuições de cientistas sociais, biólogos, historiadores, arqueólogos, farmacêuticos, médicos e tantos outros profissionais, sejam da área biomédica ou das humanidades. Com aplicações variadas, como nos estudos evolutivos ou das migrações, seus resultados, muitas vezes, dependem da associação entre os achados de laboratório e os vestígios culturais. A obra está dividida em quatro partes - Os Parasitos, Hospedeiros Humanos e o Ambiente; Vestígios de Parasitos Preservados em Diversos Materiais, Técnicas de Microscopia e Diagnóstico Molecular; O Encontro de Parasitos em Material Antigo: uma visão paleogeográfica; e Estudos Especiais e Perspectivas. Assinado por autores de vários países, como Argentina, Estados Unidos, Alemanha e França, o livro tem capítulos dedicados às descobertas da paleoparasitologia em todos os continentes.', '["paleoparasitology","parasites","human hosts","paleogeography","microscopy techniques","molecular diagnosis","parasite migration","evolutionary studies","cultural relics"]', '10.7476/9786557082997', '9788575412053', 'https://books.scielo.org/id/tndbc', 'https://books.scielo.org/id/tndbc/pdf/ferreira-9786557082997.pdf', NULL, 'https://books.scielo.org/id/tndbc/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tnfh3', 'tnfh3', 'Vivências de educação popular na atenção primária à saúde: a realidade e a utopia', NULL, '["Maria Amélia Medeiros Mano","Ernande Valentin do Prado"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', '[RETIRADO/WITHDRAWN] Educar-se ao educar, eis o princípio pedagógico assumido neste livro, verdadeiro caleidoscópio da situação e esperanças da maioria do povo brasileiro. O que se aprende depende de como se aprende: daí a relevância da experiência aqui sistematizada sob a forma de múltiplas narrativas, expressão dos saberes de diversos profissionais da saúde. Uma obra construída na caminhada dos participantes da Rede de Educação Popular e Saúde, convite à reflexão e meio para renovar o aprendizado.', '["popular education","primary care","health professionals'' knowledge","educational narratives","learning by teaching","health education"]', '10.7476/9788576003595', '9788576003595', 'https://books.scielo.org/id/tnfh3', NULL, NULL, 'https://books.scielo.org/id/tnfh3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tp2xy', 'tp2xy', 'Integridade ambiental da represa de Jurumirim: ictiofauna e relações ecológicas', NULL, '["Reinaldo José da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Esta obra identifica a composição da ictiofauna da Represa de Jurumirim, reconhecendo os diferentes padrões reprodutivos de seus peixes, incluindo das espécies migradoras. Analisa também a dieta das espécies e a comunidade de parasitas associada aos peixes dessa área, compreendida pelo Braço do Ribeirão dos Veados e as zonas de desembocaduras dos rios Paranapanema e Taquari.', '["Jurumirim Reservoir","ichthyofauna","migratory fish","fish diet","fish parasites","parasite communities","environmental integrity","Paranapanema River","Taquari River","ecological interactions"]', '10.7476/9788568334782', '9788568334782', 'https://books.scielo.org/id/tp2xy', 'https://books.scielo.org/id/tp2xy/pdf/silva-9788568334782.pdf', NULL, 'https://books.scielo.org/id/tp2xy/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tpc4n', 'tpc4n', 'Geografia e Literatura: ensaios sobre geograficidade, poética e imaginação', NULL, '["Eduardo Marandola Jr","Lúcia Helena Batista Gratão"]', 'EDUEL', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Há muito que a literatura tem colaborado com outras áreas do conhecimento, isso por sugerir ideias, propósitos e conexões sociais inseridas em contextos que trazem evidências de tempos e espaços imaginários. Os desafiadores artigos que compõem este livro resultam do esforço de alguns geógrafos que se debruçaram na leitura de obras literárias buscando estabelecer encontros e aproximações. Autores como Ítalo Calvino, Federico Garcia Lorca, Joseph Conrad, Júlio Verne, Guimarães Rosa, João Gilberto Noll, Cora Coralina e Mário de Andrade entre outros também importantes, têm suas obras investigadas por este grupo de ensaístas que apontam infinitas e instigantes possibilidades de leituras.', '["geography and literature","geographicity","poetics","imagination","literary works","Italo Calvino","Federico García Lorca","Joseph Conrad","Jules Verne","Guimarães Rosa","João Gilberto Noll","Cora Coralina"]', '10.7476/9788572166737', '9788572166737', 'https://books.scielo.org/id/tpc4n', NULL, NULL, 'https://books.scielo.org/id/tpc4n/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tpckz', 'tpckz', 'Famílias inter-raciais: tensões entre cor e amor', NULL, '["Lia Vainer Schucman"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O livro é um modelo exemplar de pesquisa que relaciona processos de constituição da subjetividade e estrutura social. Se o amor é uma construção social, o racismo também é. A fim de demonstrar essa hipótese, Lia Schucman se “eleva” aos indivíduos que integram as famílias entrevistadas, dando-lhes voz para que contem suas histórias, o que evidencia como a conexão afetiva, apesar de suas particularidades, é perpassada pelo racismo.', '["interracial families","racism","social construction of love","subjectivity","social structure","affective connection","family narratives"]', '10.7476/9788523219963', '9788523219963', 'https://books.scielo.org/id/tpckz', NULL, NULL, 'https://books.scielo.org/id/tpckz/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tpfgc', 'tpfgc', 'Introdução à pesquisa em Psicologia', 'aspectos éticos, teóricos e práticos', '["José Fernando Andrade Costa","Gleice De Oliveira Cordeiro"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Nesta obra instrutiva e de agradável leitura, o leitor ou a leitora poderá compreender as etapas da elaboração de uma pesquisa científica, atentar aos cuidados éticos em pesquisas com seres humanos, conhecer diferentes desenhos de pesquisa, a modalidade de escrita ensaio, o atravessamento do marcador racial na pesquisa em psicologia e o relato de discentes sobre o processo de construção de um projeto de pesquisa. "Introdução à Pesquisa em Psicologia: Aspectos Éticos, Teóricos e Práticos" é um livro que se destina prioritariamente a pesquisadores(as) iniciantes, mas também pode ser útil para docentes de metodologia científica, orientadores(as) e quem mais necessitar de um guia didático para a construção de uma pesquisa acadêmica.', '["research methodology","research ethics","human research ethics","research project writing","essay writing","research project development","psychology students"]', '10.7476/9788555921674', '9786589524625', 'https://books.scielo.org/id/tpfgc', NULL, NULL, 'https://books.scielo.org/id/tpfgc/cover/cover_thumbnail.jpeg', 228, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tpg4t', 'tpg4t', 'A constituição da assistência social como um campo de política pública no Brasil', NULL, '["Gustavo Conde Margarites"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-08-26', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Obra essencial para os interessados nas políticas de assistência social, na análise e na sociologia das políticas públicas e na história das instituições estatais brasileiras. A abordagem teórica inovadora do livro é ancorada na teoria dos campos de ação estratégica (TCAE). Professor do Instituto Federal do Rio Grande do Sul, o sociólogo Gustavo Conde Margarites investiga as decisões e mecanismos que embasaram a trajetória de constituição da assistência social como campo de política pública, demonstrando como a formação da área derivou, principalmente, de interações no campo da previdência social, envolvendo, posteriormente, o campo da saúde. Resultado de chamada pública para autores pela Editora Fiocruz em 2019, o título expõe a relevância da institucionalização da assistência social no bojo do sistema de proteção social do país.', '["social assistance","public policy","strategic action fields","social protection system","social security","health policy","institutionalization"]', '10.7476/9786557080191', '9786557080061', 'https://books.scielo.org/id/tpg4t', NULL, NULL, 'https://books.scielo.org/id/tpg4t/cover/cover_thumbnail.jpeg', 236, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tpyj4', 'tpyj4', 'Carlos Chagas, um cientista do Brasil = Carlos Chagas, scientist of Brazil', NULL, '["Simone Petraglia Kropf","Aline Lopes de Lacerda"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'importncia dos aspectos socioambientais, uma vez que o convvio do vetor com os seres humanos est relacionado ao desmatamento e precariedade das condies habitacionais.', '["Carlos Chagas","history of science","Chagas disease","Triatominae","socio-environmental factors","deforestation","housing conditions"]', '10.7476/9786557080009', '9786557080009', 'https://books.scielo.org/id/tpyj4', 'https://books.scielo.org/id/tpyj4/pdf/kropf-9786557080009.pdf', NULL, 'https://books.scielo.org/id/tpyj4/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tqvcj', 'tqvcj', 'Da casa à praça pública: a espetacularização das festas juninas no espaço urbano', NULL, '["Jânio Roque Barros de Castro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Fruto de uma pesquisa de doutorado defendida na Faculdade de Arquitetura e Urbanismo da Universidade Federal da Bahia (UFBA), esta publicação apresenta o viés mercadológico das festas privadas, de “camisa”, que, por vezes, é contrabalançado pelo espaço festivo – ainda que residual – dos terreiros frontais das casas ou das trilhas rurais, ao tempo que as festas nos espaços públicos, como em praças, são também espaços de expressão para manifestações culturais de caráter local e regional.', '["urban public space","public squares","festive space","terreiros","urban festivals","Bahia"]', '10.7476/9788523211721', '9788523211721', 'https://books.scielo.org/id/tqvcj', 'https://books.scielo.org/id/tqvcj/pdf/castro-9788523211721.pdf', NULL, 'https://books.scielo.org/id/tqvcj/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tqwwz', 'tqwwz', 'De que lado você samba? Raça, política e ciência na Bahia do pós-abolição', NULL, '["Gabriela dos Reis Sampaio","Wlamyra Ribeiro de Albuquerque"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro trata das dinâmicas do racismo na cidade da Bahia – a mais negra do país – nas primeiras décadas depois da Abolição. Ao percorrer diferentes territórios físicos e culturais da capital baiana, focaliza aspectos de sua vida cotidiana (festas, religiosidades e sociabilidades urbanas) e personagens centrais desse momento da cidade. Nesse período, trabalhadores braçais, médicos, cientistas, lideranças religiosas e jornalistas, negros e brancos, elaboravam e disputavam suas crenças, projetos e expectativas para a jovem República que se instituía, reeditando exclusões baseadas em critérios sociorraciais. A obra oferece, assim, uma análise dos confrontos políticos experimentados naqueles anos, marcados pelas mudanças na estrutura de poder e pela ênfase na ciência, especialmente a medicina, como forma de legitimar a exclusão racial e social.', '["racism","post-abolition Brazil","Bahia","racial exclusion","samba","urban religiosity","urban sociability","racial politics","medicine","scientific racism","political exclusion"]', '10.7476/9786586253801', '9786586253801', 'https://books.scielo.org/id/tqwwz', NULL, NULL, 'https://books.scielo.org/id/tqwwz/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tr7y8', 'tr7y8', 'Público e privado na política de assistência à saúde no Brasil: atores, processos e trajetórias', NULL, '["Telma Maria Gonçalves Menicucci"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'versalização, equanimidade, integralidade do sistema, participação, é impossível que um setor importante da assistência à saúde fique sujeito às leis do mercado.', '["public-private health care","health policy","health system actors","health care privatization","health care participation","health system integration","Brazil"]', '10.7476/9788575413562', '9788575413562', 'https://books.scielo.org/id/tr7y8', 'https://books.scielo.org/id/tr7y8/pdf/menicucci-9788575413562.pdf', NULL, 'https://books.scielo.org/id/tr7y8/cover/cover_thumbnail.jpeg', NULL, 49, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-trzc8', 'trzc8', 'Comunicação e educação: dinâmicas midiáticas e cenários escolares', NULL, '["Adilson Odair Citelli"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-07-15', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A entrada das tecnologias na escola é tema de análise e reflexão deste sétimo volume da série Comunicação e Educação. A pesquisa aqui relatada, produzida pelo Grupo de Pesquisa Mediações Educomunicativas (MECOM), da ECA-USP-CNPq, mostra que a presença do celular, dos computadores, da internet é algo objetivo no cotidiano da maioria dos professores e professoras, alunos e alunas. Isto requisita da cultura, digamos, tradicional da escola, uma nova forma de relacionamento com as técnicas e estratégias para incorporá-las aos andamentos didático-pedagógicos. Não cabe pensar as tecnologias de modo instrumental e sim como mediadoras da aprendizagem. Esperamos que os dados e reflexões aqui ensejados tragam contributo visando a repensar a educação básica formal, tendo em mira os desafios e possibilidades oferecidos pelos processos comunicacionais.', '["educational technology","mobile phones in schools","computers in schools","internet use in schools","school culture","didactic-pedagogical strategies"]', '10.7476/9786586213379', '9786586213379', 'https://books.scielo.org/id/trzc8', 'https://books.scielo.org/id/trzc8/pdf/citelli-9786586213379.pdf', NULL, 'https://books.scielo.org/id/trzc8/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ts6xj', 'ts6xj', 'As bambas do samba: mulher e poder na roda', NULL, '["Marilda Santanna"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra destaca e reconhece a importância da figura feminina na estruturação do samba como símbolo de identidade nacional e como instrumento de empoderamento. O livro mostra ̶ através de artigos e reflexões sobre espaço da mulher como protagonista na construção do samba, um dos símbolos de resistência e negociações da população negra no Brasil , a forma como as mulheres no samba ousaram enfrentando o patriarcado, o afastamento de suas posições no processo constitutivo do gênero musical e o apagamento do seu protagonismo dentro do movimento.', '["samba","gender and music","patriarchy","women''s empowerment","Black women","national identity","resistance","gender representation in music"]', '10.7476/9788523217242', '9788523215477', 'https://books.scielo.org/id/ts6xj', NULL, NULL, 'https://books.scielo.org/id/ts6xj/cover/cover_thumbnail.jpeg', 227, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ts84z', 'ts84z', 'Assistência farmacêutica e acesso a medicamentos', NULL, '["Maria Auxiliadora Oliveira","Jorge Antônio Zepeda Bermudez","Cláudia Garcia Serpa Osorio-de-Castro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra pretende discutir os medicamentos, a promoção de seu acesso, as políticas de medicamentos e um novo campo conceitual que se convencionou denominar ‘assistência farmacêutica’. São abordados conceitos e práticas da assistência farmacêutica, patentes, estratégias de marketing, doenças negligenciadas e a Política Nacional de Medicamentos.', '["pharmaceutical care","access to medicines","drug policy","patents","pharmaceutical marketing strategy","neglected diseases","National Medicines Policy","health policy"]', '10.7476/9788575413890', '9788575411315', 'https://books.scielo.org/id/ts84z', 'https://books.scielo.org/id/ts84z/pdf/oliveira-9788575413890.pdf', NULL, 'https://books.scielo.org/id/ts84z/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tskp8', 'tskp8', 'Work in Brazil: essays in historical and economic sociology', NULL, '["Adalberto Moreira Cardoso"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Institutional frameworks, political action, social and political identities, class relations, social inertia and path dependence are the main aspects inquired in this book. Taken together, the chapters present a coherent and systematic portrait of Brazil, or a plausible point of view about the dynamics of our sociability which may interest the foreign reader. Collective bargaining, labour inspection, the labour and capital organizations are all elements of the Getulio Vargas legacies that, albeit with adaptations over time, still impinge upon our present. For that reason, it is impossible to understand what we are without looking back and trying and reconstruct the trajectories of the current institutions, social and political actors, and even the economy. As a consequence, most of the chapters adopt a historical sociological perspective, in dialogue between the contemporary context and the country’s vivid historiography.', '["labor history","Brazil","Getúlio Vargas","collective bargaining","labor inspection","labor organization","capital organization","class relations","social inertia","path dependence","political action","institutional framework"]', '10.7476/9788575114551', '9788575114551', 'https://books.scielo.org/id/tskp8', 'https://books.scielo.org/id/tskp8/pdf/cardoso-9788575114551.pdf', NULL, 'https://books.scielo.org/id/tskp8/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tt522', 'tt522', 'Mercado de armas de fogo no Brasil: construção social de um mercado contestado', NULL, '["Mateus Tobias Vieira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra analisa a sociogênese da indústria de armas de fogo pequenas e leves no Brasil, entendendo como este mercado emerge e se consolida, sempre atuando em simbiose com o Estado. Ainda, busca compreender os diferentes momentos do mercado interno de armas de fogo e como se dinamizam as contestações morais que, em alguns momentos, foram capazes de propor inclusive o banimento do mercado nacional. A pesquisa ainda a influência exercida pelo Estado brasileiro na fabricação de convenções cognitivas sobre o tema de armas de fogo no Brasil contemporâneo servindo-se dos estudos de Pierre Bourdieu sobre o Estado e do conceito de convenção social, de Mary Douglas. Para tanto, selecionamos alguns contenciosos empíricos particularmente marcantes, entendendo não só o impacto de cada mudança, mas o modo como se operaram.', '["state-market relations","social construction of markets","Pierre Bourdieu","Mary Douglas","sociology of the state","Brazil"]', '10.7476/9786559543762', '9786559543762', 'https://books.scielo.org/id/tt522', 'https://books.scielo.org/id/tt522/pdf/vieira-9786559543762.pdf', NULL, 'https://books.scielo.org/id/tt522/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tthng', 'tthng', 'Estrutura tarifária da transmissão de energia elétrica no Brasil', NULL, '["Alice Helena França de Azevedo","Mattos, Lenilson Veiga"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', '[RETIRADO/WITHDRAWN] Esta obra analisa o tema tarifas de uso do sistema de transmissão (Tust) no setor elétrico brasileiro. A partir de um breve histórico sobre o modelo do setor desde a década de 1990, apresenta o marco regulatório da indústria de energia elétrica e a legislação da Agência Nacional de Energia Elétrica (Aneel) referente ao assunto.', '["electricity transmission tariffs","electricity regulation","electricity market liberalization","Brazilian electricity sector"]', '10.7476/9788582930441', '9788582930441', 'https://books.scielo.org/id/tthng', NULL, NULL, 'https://books.scielo.org/id/tthng/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ttvzc', 'ttvzc', 'Relações multiespécies em rede: feminismos, animalismos e veganismo', NULL, '["Patrícia Lessa","Dolores Galindo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro surge a partir de um simpósio temático, realizado na Universidade Federal de Santa Catarina, que a Dra. Aline Bonetti coordenou com a Dra. Patrícia Lessa, e das conexões com o trabalho que a Dra. Dolores Galindo e Dra. Sandra Azeredo vinham realizando na ministração de cursos sobre a obra de Donna Haraway em universidades brasileiras. No simpósio temático, surpreendeu o interesse pelo tema animalista e vegano sob um prisma feminista. A sala permaneceu lotada durante os dois dias de encontro e fomos presenteada/o/s com a visita da Margareth Rago que trouxe questões libertárias para pensarmos as relações com a/o/s animais não humano/a/s. Foram dias de debates no trabalho de Patrícia Giseli; ao final do ST, ela performou “Poeira do cotidiano”, em diálogo com texto da poeta Elisa Luciano. A apresentação do livro por Carol Adams é comovente e mostra a crescente importância das teorias e dos ativismos animalistas e veganos no Brasil, sendo ela uma das referências mais citadas nos trabalhos aqui reunidos. O texto de Donna Haraway, traduzido por Sandra Azeredo, enriquece o debate sobre as relações étnico-raciais na composição de mundos multiespécies, atual e inquietante. O reconhecimento comum da necessidade de publicarmos as traduções dos livros de Donna Haraway para língua portuguesa, que realizamos para nossos cursos, data de 2012, quando nós duas, Patrícia e Dolores, tivemos o feliz encontro que culminou no trabalho atual e estreitamos parceria com Ângela Donini. Para a capa do livro, contamos com a criação de Elisa Riemer, artista feminista brasileira, radicada em Maringá e com uma foto da exposição “A natureza da vida” cedida pela artista Fernanda Magalhães. Esperamos que a proposta de discussão, heterogênea e múltipla, apresentada neste volume, reverbere, no solo dos ativismos e das teorias feministas, a urgência de pensarmos sobre nossas artes da existência em um mundo que está longe de ter/ser exclusividade humana.', '["feminism","animalism","veganism","multispecies relations","Donna Haraway","animal advocacy","feminist theory","non-human animals","Brazilian feminism"]', '10.7476/9788576287469', '9788576287155', 'https://books.scielo.org/id/ttvzc', NULL, NULL, 'https://books.scielo.org/id/ttvzc/cover/cover_thumbnail.jpeg', 305, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ttxv2', 'ttxv2', 'Habilidades sociais e competência social para uma vida melhor', NULL, '["Zilda A. P. Del Prette","Almir Del Prette"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Este livro tem um caráter teórico-prático. Por um lado, introduz o leitor nos conceitos pertinentes aos comportamentos interpessoais. Por outro lado, oferece a oportunidade de exercitar-se em tarefas interpessoais. O conteúdo teórico proposto está convenientemente ajustado às atividades a serem desempenhadas pelo leitor, porém permite, ainda, uma visão explicativa das principais habilidades sociais requeridas para um bom ajustamento nos diferentes setores de convivência entre as pessoas. Trata-se de uma introdução ao tema, aqui tratado na perspectiva do campo teórico-prático das habilidades sociais e da competência social. Para um desempenho socialmente competente, é importante dispor de habilidades sociais, mas também de conhecimento, autoconhecimento, automonitoria e valores de convivência.', '["social skills","social competence","interpersonal behavior","interpersonal skills training","social adaptation","self-awareness","self-monitoring","coexistence values"]', '10.7476/9786580216161', '9786580216161', 'https://books.scielo.org/id/ttxv2', NULL, NULL, 'https://books.scielo.org/id/ttxv2/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tv', 'tv', 'Recursos críticos: história da cooperação técnica Opas-Brasil em recursos humanos para a saúde (1975-1988)', NULL, '["Fernando A. Pires-Alves","Carlos Henrique Assunção Paiva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fundação Oswaldo Cruz. Casa de Oswaldo Cruz. Departamento de Arquivo e Documentação. Rio de Janeiro, RJ, Brasil.', '["technical cooperation","Pan American Health Organization","Brazil","health human resources","healthcare workers"]', '10.7476/9788575412923', '9788575412923', 'https://books.scielo.org/id/tv', 'https://books.scielo.org/id/tv/pdf/pires-9788575412923.pdf', NULL, 'https://books.scielo.org/id/tv/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tvn7w', 'tvn7w', 'As drogas, as pessoas e as cidades: consumo do espaço e efeitos sociais em cidades latinas – Aproximações entre São Paulo, Bogotá e Medellín', NULL, '["Thiago Godoi Calil"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este livro percorre uma série de pontos que se interligam e pendulam entre teorias e narrativas na interface entre o neoliberalismo, as drogas e a produção das cidades na América Latina. Para Hilderman Cardona Rodas, professor da Universidad de Medellín (Colômbia), trata-se de um “excelente trabalho em termos de revisão documental, trabalho de campo e compromisso intersubjetivo do autor em sua argumentação. Um magnífico arcabouço epistemológico para rastrear os cenários públicos de uso de drogas e a produção social de risco nas cidades pesquisadas. Os desenhos enriquecem o conteúdo e a expressão da obra, oferecendo suporte de valor estético às experiências do autor”. Segundo Gabriela Marques Di Giulio, professora da Faculdade de Saúde Pública da Universidade de São Paulo (USP), o livro “expõe panoramas robustos sobre os contextos estudados e suas especificidades, com provocações e reflexões sobre a urgência de uma mudança nos paradigmas de produção de nossas cidades, trazendo a dimensão do cuidado, e reforçando a relevância do processo de escuta da população local e de sua participação mais ativa no desenho urbano e na implantação de políticas”.', '["drug use","urban production","neoliberalism","Latin American cities","São Paulo","Bogotá","Medellín","public space","urban planning","drug policy","care"]', '10.7476/9786557143001', '9786557143001', 'https://books.scielo.org/id/tvn7w', 'https://books.scielo.org/id/tvn7w/pdf/calil-9786557143001.pdf', NULL, 'https://books.scielo.org/id/tvn7w/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tw4bm', 'tw4bm', 'Os sertões', NULL, '["Euclydes da Cunha"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Intentamos esboçar, palidamente embora, ante o olhar de futuros historiadores, os traços atuais mais expressivos das sub-raças sertanejas do Brasil.', '["sertão","sertanejos","regional identity"]', '10.7476/9788579820076', '9788579820076', 'https://books.scielo.org/id/tw4bm', 'https://books.scielo.org/id/tw4bm/pdf/cunha-9788579820076.pdf', 'https://books.scielo.org/id/tw4bm/epub/cunha-9788579820076.epub', 'https://books.scielo.org/id/tw4bm/cover/cover_thumbnail.jpeg', 516, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-twdqw', 'twdqw', 'Labirintos de Borges e Saramago: espaço, palavra e identidade', NULL, '["Cleomar Pinheiro Sotta"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este estudo crítico defende que é possível aproximar a produção narrativa de Jorge Luis Borges e José Saramago tendo como guia a imagem do labirinto, selecionando três grandes perspectivas em que ela se desdobra. A primeira delas é a espacial. Ambos os escritores tendem a descrever os ambientes por onde circulam os personagens, traçando uma analogia com as definições e características labirínticas acumuladas ao longo do tempo. Em segundo lugar está a evocação do labirinto na própria escrita, na forma de organizar os textos, na pontuação e, principalmente, no tom ensaístico-filosófico e nas notas digressivas intercaladas ao enredo. Por último, a busca pela identidade também se associa a vias labirínticas, na medida em que se compõe como um trajeto cheio de incertezas, objetivando chegar ao centro, isto é, ao encontro de um eu consigo mesmo e com um outro.', '["Jorge Luis Borges","José Saramago","labyrinth","narrative space","literary identity","self and other","philosophical essays","digression","punctuation","text structure","comparative literature"]', '10.7476/9786559542536', '9786559542536', 'https://books.scielo.org/id/twdqw', 'https://books.scielo.org/id/twdqw/pdf/sotta-9786559542536.pdf', NULL, 'https://books.scielo.org/id/twdqw/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-twff2', 'twff2', 'Residuos de la violencia. Producción cultural colombiana, 1990-2010', NULL, '["Andrea Fanta Castro"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra analiza los productos culturales contemporáneos del choque entre la globalización y la violencia a través de la literatura, del cine, de la arquitectura y de la escultura. Específicamente estudia las subjetividades que derivan de este contexto: los cuerpos residuales, es decir, remanentes de la generalizada violencia social, política, y económica inherentes a las sociedades consumo. El análisis está centrado específicamente en los textos La virgen de los sicarios de Fernando Vallejo, Rosario Tijeras de Jorge Franco y en sus adaptaciones cinematográficas. También examina las novelas Satanás y Scorpio City de Mario Mendoza, Perder es cuestión de método y Vida feliz de un joven llamado Esteban de Santiago Gamboa, El olvido que seremos de Héctor Abad Faciolince y Todo pasa pronto de Juan David Correa. A través del trabajo plástico de Doris Salcedo el texto examina como los cuerpos residuales están presentes como ausencia en la escultura contemporánea y esto, en última instancia, señala su condición marginal. Además, explora transformaciones urbanas recientes en Bogotá, particularmente en estructuras arquitectónicas como el Palacio de Justicia y el Parque Tercer Milenio. En este corpus diverso se analiza el contexto político e histórico en el cual los cuerpos residuales devienen parte del proceso de reciclaje de desechos. Este trabajo propone una lectura de la producción cultural reciente totalmente novedosa tanto en su forma como en el contenido, en tanto que rompe con las visiones tradicionales y propone una nueva comprensión no solo de la violencia sino de las prácticas culturales contemporáneas colombianas.', '["Colombian literature","Colombian cinema","violence","globalization","residual bodies","Fernando Vallejo","La virgen de los sicarios","Jorge Franco","Rosario Tijeras","Mario Mendoza","Santiago Gamboa","Héctor Abad Faciolince"]', '10.7476/9789587385458', '9789587385441', 'https://books.scielo.org/id/twff2', NULL, NULL, 'https://books.scielo.org/id/twff2/cover/cover_thumbnail.jpeg', 166, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-twgn7', 'twgn7', 'Judaísmo para o século XXI: o rabino e o sociólogo', NULL, '["Nilton Bonder","Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'other', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Da amizade e dos diálogos informais entre um rabino e um sociólogo surgem instigantes argumentos sobre questões existenciais e de identidade através de suas raízes judaicas. Falar do futuro sob ambos os pontos de vista, religioso e laico, é uma forma de comentar sobre este novo século de incertezas e transformações, e apostar que religião e democracia podem e devem convergir. O que será o judaísmo do século XXI? Mais do que uma pergunta específica, esta é uma síntese de todas as perguntas marcadas pelo sentimento de que se aproxima o fim de um mundo como nós o conhecemos.', '["Judaism","Jewish identity","religion and democracy","rabbinic thought"]', '10.7476/9788579820403', '9788579820403', 'https://books.scielo.org/id/twgn7', 'https://static.scielo.org/scielobooks/twgn7/pdf/bonder-9788579820403.pdf', NULL, 'https://books.scielo.org/id/twgn7/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-twj9s', 'twj9s', 'Informação, saúde e redes sociais: diálogos de conhecimentos nas comunidades da Maré', NULL, '["Regina María Marteleto","Eduardo Navarro Stotz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Olhando a Significação: do paradigma do acesso ao da apropriação de informação Voltar o olhar para os processos sociais de significação é tocar em problema histórico e cultural chave.Se os tempos e os espaços mudam, mudam também os significados, os modos e os atores que os produzem.Das rodas ao redor do fogo à navegação nos oceanos informacionais da internet, são distantes e distintos tanto os conteúdos e valores culturais quanto os caminhos de sua construção.Daí a necessidade de atualização permanente dos debates, do esforço contínuo de compreensão dos modos como as diferentes formações sociais constroem e reconstroem seus patrimônios simbólicos, condição de sua existência tanto material quanto imaterial.Extremamente sensíveis aos fluxos temporais e ao fulgor das tensões, das paixões e dos gestos, os significados movimentam-se permanentemente, alheios às pretensões e promessas de fixação que podem ser entrevistas em formulações como a que diz que "as palavras voam, a escrita fica".Se, efetivamente, a escrita permanece, as significações, ao contrário, se esvaecem e se reconstituem permanentemente, em um fluxo intermitente e aberto que ultrapassa a fisicalidade dos traços que lhes dão guarida e visibilidade.É no tempo e no espaço do porvir histórico que os significados se inscrevem e realizam, não no presente eterno da pura, mas desencarnada, materialidade dos sinais.Lembro Lygia Bojunga Nunes: os livros espreitam e esperam na estante.Em silêncio, resignados.Assim, se a escrita fica, como outras formas de 15 Apresentação Apresentação Os trabalhos que aqui se apresentam são resultantes de projetos de pesquisa conduzidos de forma interinstitucional, interdisciplinar e compartilhada por duas equipes de pesquisadores: o grupo de pesquisa em ''Antropologia da Informação'' -ligado ao Instituto Brasileiro de Informação em Ciência e Tecnologia, (Ibict/MCT) em convênio com a Escola de Comunicação da Universidade Federal do Rio de Janeiro (ECO/UFRJ), e, mais tarde, à Escola de Ciência da Informação da Universidade Federal de Minas Gerais (ECI/UFMG) -e o grupo de pesquisa ''Educação, Saúde e Cidadania'', vinculado ao Núcleo de Estudos Locais em Saúde (Elos), instância técnico-científica e interdepartamental da Escola Nacional de Saúde Pública da Fundação Oswaldo Cruz (Ensp/Fiocruz).Os textos dizem respeito à informação e saúde e centram suas questões, em primeiro momento, nos atores institucionais, para perguntar de que modo exercem o papel de distanciamento e neutralidade, em geral exigido ao produtor do conhecimento científico, para optar por uma outra atitude, a do afastamento e da ''neutralidade ativa'', por ser esta mais favorável a uma posição de escuta, propiciadora ao aparecimento de outras vozes.Para tanto, entende-se ser indispensável aos atores institucionais do conhecimento seu engajamento na qualidade de pesquisadores, usando o duplo atributo de analistas e de intérpretes.A pesquisa na área de saúde pública, como também na de ciências da informação, ensina que, ao adotarem uma posição de neutralidade ativa, os pesquisadores se situam, na perspectiva de certos segmentos da sociedade O capítulo 9, "Luiza, Gabriela ou Joana: narrativas femininas na Maré", de Elaine Savi e Maíra Araújo, é um relato baseado na experiência de um grupo de mulheres que se reúne semanalmente para falar dos problemas que enfrentam: violência cotidiana, problemas familiares, desemprego, sintomas físicos e psíquicos e outros.É uma das expressões do ''encontro'' como tática para lidar com problemas sentidos: as autoras tratam de um sofrimento difuso, referindo-se a um estado de adoecimento das pessoas, decorrente das condições de pobreza e do contexto violento em que vivem.No limite do sofrimento, a necessidade de desabafar é premente, e a convivência entre essas mulheres estabelece vínculos de afeto, permitindo a reconstrução da subjetividade e, portanto, da identidade.Mesmo que nenhuma classificação possa ser considerada certa ou errada, completa ou perene, podemos crer que este volume reúne, em certa medida, elementos constituidores, produzidos de forma compartilhada, daquilo que é necessário para a compreensão do conhecer como campo de estudos e práticas interdisciplinares, interinstitucionais.A obra é o relato de um trajeto de apropriação e como conseqüência é também reflexão a respeito de diferenciados processos políticos, pedagógicos e epistemológicos de construção e disputa de sentidos nas sociedades em rede dos tempos atuais, chamadas também de sociedades do conhecimento, da informação, da comunicação, em um contexto de desigualdade social, pobreza e fragilização da democracia.Aproveitamos para dirigir palavras de agradecimentos às instituições de apoio e de interlocução acadêmica e prática que possibilitaram a realização deste livro.Ao Conselho Nacional de Desenvolvimento Científico e Tecnológico (Cnpq), que patrocinou as pesquisas nas quais se baseiam os textos aqui reunidos.Aos bolsistas e alunos de graduação e pós-graduação do Ibict/UFRJ, ECI/UFMG e Ensp/Fiocruz, que participaram ativamente em todas as fases de produção das pesquisas e de seus textos.Agradecemos especialmente as comunidades da Maré, na cidade do Rio de Janeiro, pelas suas vozes combativas e seus cabedais criativos.Sem a articulação e interação alcançadas, o conhecimento dos pesquisadores seria distante e incompleto.Em outras palavras, não teria serventia social e emancipatória.', '["health information","social networks","dialogue of knowledges","favelas","meaning-making","access to information","internet use","health information seeking","social media","cultural heritage","symbolic heritage","Rio de Janeiro favelas"]', '10.7476/9788575413319', '9788575413319', 'https://books.scielo.org/id/twj9s', 'https://books.scielo.org/id/twj9s/pdf/marteleto-9788575413319.pdf', NULL, 'https://books.scielo.org/id/twj9s/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-txcs6', 'txcs6', 'A recepção do Darwinismo no Brasil', NULL, '["Domingues, Heloisa Maria Bertol","Sá, Magali Romero","Thomas F. Glick"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os artigos reunidos iniciam um debate que aprofunda a história sobre a recepção da teoria de Darwin que repercutiu nos mais diversos campos científicos, orientando-os, desde a segunda metade do século XIX e no século XX. Particularmente, preocupa-se em retratar como o Brasil viveu o debate em torno do tema, apesar das controvérsias que estimularam a discussão nos meios intelectuais. A partir das controvérsias e das discussões do darwinismo, os trabalhos desta coletânea tentam abordar qual a contribuição da teoria darwinista para a criação de argumentos ideológicos nos mais diversos campos do saber, sendo muito comum a confusão entre darwinismo e evolucionismo, o que minimizou a oposição a Darwin, levando a classificar opositores da teoria da seleção das espécies, de darwinistas.', '["Darwinism","history of evolutionary theory","evolutionism","natural selection","scientific controversy","19th-century science","20th-century science","Brazil"]', '10.7476/9788575414965', '9788575414965', 'https://books.scielo.org/id/txcs6', 'https://books.scielo.org/id/txcs6/pdf/domingues-9788575414965.pdf', NULL, 'https://books.scielo.org/id/txcs6/cover/cover_thumbnail.jpeg', NULL, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-txd2g', 'txd2g', 'Leia o livro, veja o filme, compre o disco: a formação do cinema juvenil brasileiro', NULL, '["Zuleika de Paula Bueno"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'LEIA O LIVRO, VEJA O FILME, COMPRE O DISCO: A formação do cinema juvenil brasileiro aborda a produção cinematográfica direcionada ao público jovem no Brasil num determinado período histórico, no caso, o final da década de 1950 e o início dos anos 1990. O que se entende aqui por cinema juvenil é o resultado de uma determinada configuração de processos produtivos, estruturas narrativas, formas de sociabilidade e práticas de consumo existentes no cinema brasileiro que coloca o jovem no centro do debate cultural.', '["youth film","Brazilian cinema","film production","young audiences","film consumption","cultural sociability","narrative structure","1950s","1990s"]', '10.7476/9788576286981', '9788576286639', 'https://books.scielo.org/id/txd2g', NULL, NULL, 'https://books.scielo.org/id/txd2g/cover/cover_thumbnail.jpeg', 244, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-txr82', 'txr82', 'A ascensão letal da anticiência: advertência de um cientista', 'advertência de um cientista', '["Peter Jay Hotez"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O médico e pesquisador norte-americano Peter J. Hotez, a partir da sua experiência pessoal, analisa como o movimento antivacina e a extrema direita transformaram o negacionismo científico em uma ameaça global à saúde pública e à democracia. A obra dialoga com o cenário brasileiro, em que discursos anticiência também ganharam força nos últimos anos, e reforça a importância da ciência como base da vida em sociedade.', '["anti-science","anti-vaccine movement","science denialism","far right","public health","democracy","role of science in society","Brazil"]', '10.7476/9786557083017', '9786557082089', 'https://books.scielo.org/id/txr82', NULL, NULL, 'https://books.scielo.org/id/txr82/cover/cover_thumbnail.jpeg', 253, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-txvcd', 'txvcd', 'A síndrome metabólica e suas implicações clínicas', NULL, '["Edilene Maria Queiroz Araújo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A síndrome metabólica é uma desordem complexa de base genética e origem multifatorial. O livro, que traz resultado de várias pesquisas de pós-graduação, trata desse sério problema de saúde que atinge muitas pessoas e é essencial para profissionais de saúde de todas as áreas, mas principalmente nutrição e medicina.', '["metabolic syndrome","genetic basis","multifactorial etiology","clinical implications","nutrition","medicine"]', '10.7476/9786588211113', '9788578873615', 'https://books.scielo.org/id/txvcd', 'https://books.scielo.org/id/txvcd/pdf/araujo-9786588211113.pdf', 'https://books.scielo.org/id/txvcd/epub/araujo-9786588211113.epub', 'https://books.scielo.org/id/txvcd/cover/cover_thumbnail.jpeg', 340, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ty266', 'ty266', 'Saúde bucal no Brasil: muito além do céu da boca', NULL, '["Paulo Capel Narvai","Paulo Frazão"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O livro trata do contexto do sistema e das políticas de saúde bucal no Brasil. Os autores compreendem a saúde bucal em suas várias dimensões, transitando do biológico ao social e ao psicológico e analisando suas implicações políticas. Eles reuniram e analisaram documentos de várias origens e finalidades, e declarações relativas aos processos que levaram à criação de uma política nacional de saúde bucal. O livro enfatiza os principais aspectos do quadro epidemiológico, a evolução histórica das ações desenvolvidas no setor, as proposições que surgiram na esfera pública e o Programa Brasil Sorridente, entre outos temas. No final, o leitor encontrará considerações sobre o futuro da saúde bucal e da prática odontológica.', '["oral health","oral health policy","oral health systems","Brazil","epidemiology of oral diseases","public health policy","future of dentistry"]', '10.7476/9788575413630', '9788575413630', 'https://books.scielo.org/id/ty266', 'https://books.scielo.org/id/ty266/pdf/narvai-9788575413630.pdf', NULL, 'https://books.scielo.org/id/ty266/cover/cover_thumbnail.jpeg', NULL, 40, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tyt6z', 'tyt6z', 'As bambas do samba: mulher e poder na roda', NULL, '["Marilda Santanna"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra destaca e reconhece a importância da figura feminina na estruturação do samba como símbolo de identidade nacional e como instrumento de empoderamento. O livro mostra ̶ através de artigos e reflexões sobre espaço da mulher como protagonista na construção do samba, um dos símbolos de resistência e negociações da população negra no Brasil , a forma como as mulheres no samba ousaram enfrentando o patriarcado, o afastamento de suas posições no processo constitutivo do gênero musical e o apagamento do seu protagonismo dentro do movimento.', '["samba","gender and music","patriarchy","women''s empowerment","Black women","national identity","resistance","gender representation in music"]', '10.7476/9786556301754', '9788523219253', 'https://books.scielo.org/id/tyt6z', NULL, NULL, 'https://books.scielo.org/id/tyt6z/cover/cover_thumbnail.jpeg', 231, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tzshb', 'tzshb', 'Mercado e instituições: uma abordagem econômica aplicada para as reformas previdenciária e trabalhista no Brasil', NULL, '["Mauro Borges Lemos","Lívio Andrade Wanderley","Hamilton de Moura Ferreira Júnior"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'A obra aborda por que o Estado e o mercado das sociedades contemporâneas são resultados históricos de instituições socialmente e economicamente construídas. Esse enfoque é usado para analisar as duas reformas sociais mais relevantes do Brasil deste segundo decênio do século XXI. O uso da abordagem institucionalista para analisar essas reformas sociais é inédito no Brasil. O público-alvo é a comunidade de ciências sociais, especialmente estudantes e jovens no início de suas carreiras profissionais em Economia.', '["institutional economics","institutionalism","social market","social reform","pension reform","labor reform","state formation","social security","Brazil"]', '10.7476/9786556305035', '9786556305035', 'https://books.scielo.org/id/tzshb', 'https://books.scielo.org/id/tzshb/pdf/lemos-9786556305035.pdf', NULL, 'https://books.scielo.org/id/tzshb/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tztwk', 'tztwk', 'Legitimidades da loucura: sofrimento, luta, criatividade e pertença', NULL, '["Mônica de Oliveira Nunes","Tiago Pires Marques"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro tem por objetivo identificar, analisar e até construir modos de produção de legitimidades das diferenças que as sociedades ou os sujeitos, apropriando-se politicamente de atributos valorados negativamente, colocam no campo da loucura. Pretende também analisar aquilo que impede ou dificulta essas produções de legitimidade, tal como observado na prática em diversas situações de vida, em âmbitos institucionais ou até mesmo em contextos de pesquisa e das suas estratégias narrativas. Buscou-se, então, reunir algumas contribuições atuais que adensam e diversificam aspectos socioculturais e políticos que se relacionam com a produção social de condições mais ou menos favoráveis à construção dessas novas formas de legitimidade para a loucura ou da emergência de outros lugares sociais para serem ocupados pelas pessoas com sofrimento mental.', '["psychological suffering","creativity","sense of belonging","social construction of madness","mental health","social inclusion of people with mental illness","narrative technique"]', '10.7476/9788523220242', '9788523217716', 'https://books.scielo.org/id/tztwk', NULL, NULL, 'https://books.scielo.org/id/tztwk/cover/cover_thumbnail.jpeg', 444, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tzvzr', 'tzvzr', 'Segurança do paciente: conhecendo os riscos nas organizações de saúde', NULL, '["Paulo Sousa","Walter Vieira Mendes Junior"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Promover, proteger e recuperar a saúde é o que se espera dos serviços de saúde. Por isso, provoca espanto quando se fala que o processo de cuidado em saúde pode causar incidentes com danos. Alguns perigos são inerentes a esse processo – por exemplo, os efeitos colaterais conhecidos de determinados medicamentos. Outros podem ser consequências de erros, que acontecem em qualquer ramo de atividade, inclusive na saúde. Para fazer frente à frequência e à magnitude desses problemas, deve-se disseminar a cultura da segurança nos serviços de saúde, com o objetivo de melhorar a qualidade e os resultados desses serviços. Importantes contribuições nesse sentido podem ser encontradas nestes dois volumes. Os livros são desdobramento de um curso internacional de especialização em qualidade em saúde e segurança do paciente, oferecido na modalidade a distância (EAD) no âmbito de uma parceria entre a Escola Nacional de Saúde Pública da Fundação Oswaldo Cruz e a Escola Nacional de Saúde Pública da Universidade Nova de Lisboa. Especialistas brasileiros e portugueses produziram materiais didáticos para o curso, pois se verificou uma escassez de publicações sobre essas temáticas, sobretudo em língua portuguesa. Contudo, os materiais ganharam vida própria, independente do curso. Estruturadas de modo a suprir as reais necessidades de formação de médicos, enfermeiros, farmacêuticos, profissionais das tecnologias da saúde e gestores, as coletâneas têm por base conhecimentos e evidências que refletem o atual estado da arte em segurança do paciente. Os leitores – não só do Brasil e de Portugal, mas de toda a Comunidade dos Países de Língua Portuguesa (CPLP) – encontrarão subsídios para que, no dia a dia, mudanças na prática dos cuidados resultem em serviços mais seguros em todos os pontos da atenção à saúde.', '["patient safety","healthcare risk","medical errors","safety culture","quality of care","adverse events","patient safety education"]', '10.7476/9788575416419', '9788575416419', 'https://books.scielo.org/id/tzvzr', 'https://books.scielo.org/id/tzvzr/pdf/sousa-9788575416419.pdf', NULL, 'https://books.scielo.org/id/tzvzr/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-tzwkv', 'tzwkv', 'As leis de Orlando', 'gêneros e/m tradução/desconstrução', '["José Pedro de Carvalho Neto"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As Leis de Orlando são uma obra que desconstrói a tradução e os gêneros (textuais e sexuais), desafiando os seus limites. Na primeira parte deste trabalho, a tradução é entendida não como uma mera cópia, mas sim como uma transformação constante; e o gênero (biográfico, sexual) também segue essa trilha. Na segunda parte, textos e sexos se misturam quando Orlando, de Virginia Woolf, é comparado às traduções brasileiras de Cecília Meireles e Tomaz Tadeu. Desvende as fronteiras entre biografia/ficção, relato/narrativa, eu/nós, masculino/feminino, original/tradução, filosofia/literatura. Este é um livro que desafia e convida à reflexão até a última linha.', '["Orlando: A Biography","Virginia Woolf","translation","textual genres","sexual genre","biography and fiction","narrative","Brazilian Portuguese translation","Cecília Meireles","original and translation","masculinity and femininity","self and collective"]', '10.7476/9788574556000', '9788574555799', 'https://books.scielo.org/id/tzwkv', NULL, NULL, 'https://books.scielo.org/id/tzwkv/cover/cover_thumbnail.jpeg', 299, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v23g7', 'v23g7', 'Radiografia de uma aula em engenharia', NULL, '["Luis Roberto de Camargo Ribeiro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Radiografia de uma aula em Engenharia traz uma análise de uma aula no ensino de engenharia, revelando aspectos institucionais e culturais que contribuem para seu formato - por exemplo, a relativa autonomia docente, a prevalência de currículos lineares, a existência de uma cultura positivista, entre outros - comuns a muitos contextos educacionais no ensino desta e outras áreas do conhecimento. O autor também sugere como aspectos individuais do professor podem influenciar suas escolhas didáticas, frequentemente limitadas pela ausência de formação pedagógica (prévia ou em serviço) - uma característica docente comum no ensino superior no país. À guisa de ilustração, este livro ainda traz uma alternativa - o PBL (Aprendizagem Baseada em Problemas) - às metodologias de ensino fundamentadas no modelo de transmissão e recepção de conhecimentos fixos e acabados, comumente utilizadas nas aulas de engenharia e no ensino superior em geral.', '["engineering education","classroom analysis","teacher autonomy","positivism","teacher pedagogical training","problem-based learning","higher education teaching methods"]', '10.7476/9788576003618', '9788576003618', 'https://books.scielo.org/id/v23g7', NULL, NULL, 'https://books.scielo.org/id/v23g7/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v254g', 'v254g', 'Diálogos com Fellini', NULL, '["Cássia Lopes","Paulo Henrique Alcântara"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Contemporâneo de nomes importantes para o cinema italiano, como Pier Paolo Pasolini, Luchino Visconti, Vitório de Sicca e Ettore Scola, Fellini imprimiu sua assinatura particular cravada em personagens que revelam facetas extravagantes e melancólicas. Consagrado em 1960, com seu estilo inconfundível e as marcas de sua poética fixadas no público, Fellini credenciou seu nome em diversas obras, como Fellini Satyricon (1969) e O Casanova de Fellini (1976). A partir disso, este livro reúne 11 artigos que refletem sobre alguns desses filmes, expressões da rica trajetória do criador. O grupo de pesquisa Dramatis direciona a obra para a poética felliniana, de onde se captura a força das imagens, das histórias e dos signos impressos na tela.', '["Federico Fellini","Italian cinema","film poetics","Pier Paolo Pasolini","Luchino Visconti","Ettore Scola","film characters","cinematic imagery"]', '10.7476/9786556301792', '9786556301792', 'https://books.scielo.org/id/v254g', 'https://books.scielo.org/id/v254g/pdf/lopes-9786556301792.pdf', NULL, 'https://books.scielo.org/id/v254g/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v2jx5', 'v2jx5', 'Elogio aos errantes', NULL, '["Paola Berenstein Jacques"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Elogio aos errantes propõe-se a abordar a experiência urbana da alteridade. Entendendo a cidade como locus da experiência e se contrapondo aos discursos que demonstram a incapacidade de fazer e transmitir experiências na cidade contemporânea, a autora discute as possibilidades de um urbanismo mais incorporado.', '["urban experience","otherness","the city","contemporary urbanism","wandering"]', '10.7476/9788523208707', '9788523217389', 'https://books.scielo.org/id/v2jx5', NULL, NULL, 'https://books.scielo.org/id/v2jx5/cover/cover_thumbnail.jpeg', 331, 115, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v2mhp', 'v2mhp', 'Pedagogías del desaprender. Una mirada política a la educación desde la afrodescendencia', NULL, '["León Castro, Edizon"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2023, '2023-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Asumimos las Pedagogías del desaprender como esas praxis que nos ayudan a despojarnos de formas e ideologías de dominación y disciplinamiento que se reproducen en el sistema educativo. Estas formas de opresión están marcadas por el racismo estructural y cotidiano, negando la posibilidad de consolidar otras formas de educación arraigadas en genealogías epistémicas y filosofías educativas presentes en las comunidades de nuestros pueblos afrodescendientes. Este libro es una compilación de reflexiones serias y comprometidas en los diferentes niveles de la educación, que incluyen a la educación superior y la educación no institucional con una perspectiva interseccional racial y de género. Un análisis crítico de los procesos y reflexiones que surgen desde diferentes lugares de la diáspora afrodescendiente en las Américas, específicamente en el ámbito de la educación.', '["Afro-descendant education","structural racism","everyday racism","philosophy of education","intersectionality","race and gender","higher education","decolonial pedagogy"]', '10.7476/9789942099402', '9789942099273', 'https://books.scielo.org/id/v2mhp', NULL, NULL, 'https://books.scielo.org/id/v2mhp/cover/cover_thumbnail.jpeg', 213, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v2xb3', 'v2xb3', '"As ‘nagôs’ estão na rua com prazer e alegria": uma cartografia afro-baiana de Belmonte (Bahia)', NULL, '["Dandara dos Santos Silva"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é resultado de processo de pesquisa realizada junto ao Programa de Mestrado em Ensino e Relações Étnico-Raciais da Universidade Federal do Sul da Bahia. A autora trabalha com a hipótese de que as “Nagôs” de Belmonte/BA têm muito que ensinar aos processos de escolarização das relações étnico-raciais e sobre os modos de saber/fazer do povo negro. Por meio da metodologia cartográfica, ela investigou o espaço da rua, do bloco, das danças, dos cantos e do “Bloco das Nagôs Africanas” como espaço de ensino e aprendizagem. Nesse sentido, uma das dimensões instigantes trazidas pela obra é a noção de experiência como formativa/educativa. Ao longo do livro, a autora prescruta como a experiência e a qualidade do “Bloco das Nagô” não remetem à usual ideia de informação, de situações/coisas que acontecem exteriores ao sujeito. Em uma palavra, nesta pesquisa experiência não é experimento. Experiência é subjetiva, singular a cada pessoa. A cartografia afro-baiana construída pela autora faz ressoar a tese apontada por Walter Benjamin em seu ensaio Experiência e pobreza (1933) quando discorre sobre o retraimento da experiência no sentido de fazer circular os saberes dos mais velhos para as novas gerações. Para o autor, a fragilização da experiência traz como uma das consequências o aniquilamento das relações com a cultura ancestral e o patrimônio cultural. O presente livro demonstra que “os passos das Nagô de Belmonte/BA vêm de longe…”, devendo ser remetido à experiência da herança ancestral presente na diáspora africana e no movimento intelectual negro.', '["Afro-Brazilian culture","street performance","samba schools","cultural heritage","ancestral heritage","Walter Benjamin","African diaspora","ethnic-racial relations","cultural cartography","intergenerational knowledge transmission"]', '10.7476/9788574555492', '9788574555492', 'https://books.scielo.org/id/v2xb3', 'https://books.scielo.org/id/v2xb3/pdf/silva-9788574555492.pdf', NULL, 'https://books.scielo.org/id/v2xb3/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v3d7g', 'v3d7g', 'Atenção integrada às doenças prevalentes na infância: implantação e avaliação no Brasil', NULL, '["Antônio José Lêdo Alves da Cunha","Yehuda Benguigui","Maria Anice Sabóia Fontenele e Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro traz uma série de textos de profissionais da área da saúde materno-infantil. Oferece um panorama da atenção integrada às doenças prevalentes na infância, estratégia reconhecida pelo Ministério da Saúde.', '["integrated care","childhood diseases","maternal and child health","health policy implementation","program evaluation","primary care"]', '10.7476/9788575416044', '9788575416044', 'https://books.scielo.org/id/v3d7g', 'https://books.scielo.org/id/v3d7g/pdf/cunha-9788575416044.pdf', NULL, 'https://books.scielo.org/id/v3d7g/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v49c8', 'v49c8', 'Autonarrativas, autoetnografia e reflexões sobre subjetividade e saúde', NULL, '["Mônica (Molije) Lima"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Autonarrativas, Autoetnografias e reflexões sobre subjetividade e saúde reúne relatos sensíveis e reflexões teóricas sobre os atravessamentos entre experiência, cuidado, subjetividade e adoecimento. Dividida entre autonarrativas de mulheres que viveram o câncer de mama – como pacientes ou cuidadoras – e textos analíticos produzidos por pesquisadoras de diferentes áreas da Psicologia, a obra constrói um diálogo potente entre experiência pessoal e produção acadêmica. Partindo de desenhos e escritas autobiográficas elaborados durante o processo terapêutico da organizadora, o livro articula perspectivas como psicanálise, gestalt-terapia, psicologia social construcionista e relações raciais, propondo uma abordagem acessível, sensível e interdisciplinar sobre saúde e subjetividade. Mais do que um livro acadêmico, a coletânea se apresenta como espaço de escuta, elaboração e compartilhamento de experiências humanas marcadas pelo cuidado e pela resistência.', '["breast cancer","cancer caregivers","subjectivity","health","autobiographical narrative","psychoanalysis","Gestalt therapy","social constructionism","race relations","care","illness","resistance"]', '10.7476/9786556309934', '9786556309446', 'https://books.scielo.org/id/v49c8', 'https://books.scielo.org/id/v49c8/pdf/lima-9786556309934.pdf', NULL, 'https://books.scielo.org/id/v49c8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v4cnf', 'v4cnf', 'Movimentos sociais e institucionalização: políticas sociais, raça e gênero no Brasil pós-transição', NULL, '["Adrian Bueno Gurza Lavalle","Euzenéia Carlos","Monika Dowbor","José Szwako"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'CATALOGAÇÃO NA FONTE UERJ/REDE SIRIUS/NPROTEC M935Movimentos sociais e institucionalização : políticas sociais, raça e gênero no Brasil pós-transição / Adrian Gurza Lavalle ... ApresentaçãoEste livro colhe os resultados de uma longa interlocução, de mais de dez anos, entre os pesquisadores do Núcleo de Pesquisa Democracia e Ação Coletiva (NDAC).Nesse sentido, trata-se propriamente de um livro coletivo e não de uma coletânea, pois exprime uma agenda construída coletivamente para entender as relações de mútua constituição entre sociedade civil e Estado, em que movimentos sociais são atores centrais.Exprime igualmente o amadurecimento de ferramentas analíticas que, em ação neste volume, foram pacientemente buriladas ao longo do tempo mediante o trabalho duplo da crítica de seus rendimentos na pesquisa empírica e da avaliação contínua das perspectivas analíticas que animam o conhecimento acumulado e seus avanços de fronteira.Criado em 2006 e composto inicialmente por um grupo de jovens pesquisadores em diversos estágios na carreira sob a orientação do professor Adrian Gurza Lavalle -pesquisadores, por força do tempo e da competência, hoje doutores e professores em diversas universidades e instituições de pesquisa -, o NDAC realizou e continua a realizar pesquisas sobre padrões de interação Estado/sociedade em registros diversos: novas formas de representação política, instituições participativas, controle social e accountability, interfaces entre instituições políticas e atores sociais, redes de organizações civis e sua transversalidade com atores estatais, e construção política das organizações civis.Entre esses registros, aquele dedicado a pensar as capacidades dos atores sociais como uma construção política definida por processos de interação Prefácio Nas décadas de 1990 e 2000, o Brasil apareceu no cenário internacional como foco de experimentação criativa na produção de políticas públicas que envolviam movimentos sociais no interior do processo decisório.Nos anos 1990, eram os orçamentos participativos e outras iniciativas locais, bem como a criação de sistemas de políticas públicas com participação em nível nacional, tais como o Sistema Único de Saúde.Nos anos 2000, especialmente a partir de 2003 com o advento do governo federal do Partido dos Trabalhadores, essa experimentação subiu de escala com o fortalecimento de conselhos e conferências, e uma diversidade de outros tipos de arranjos participativos que envolveram movimentos sociais não somente na formulação das políticas, mas também na sua implementação.Ao lado dessa experimentação na prática, surgiu uma literatura acadêmica que também experimentou, contribuindo de maneira original para os estudos de movimentos sociais, democracia e sociedade civil.Num primeiro momento, isso envolveu reacender o antigo debate sobre democracia participativa, agora em torno de experiências reais muito mais amplas em termos numéricos do que havia acontecido no passado em outros lugares do mundo (com a exceção, talvez, da experiência do estado indiano de Kerala, que também envolveu milhões de pessoas).Uma literatura inicialmente ufanista e militante foi rapidamente complementada por pesquisas empíricas bem fundamentadas que revelavam as complexidades e limitações das iniciativas participativas.Ao mes-Prefácio da sociedade e do Estado, no entanto, não proliferou, talvez em função do crescimento, nos anos 1990, do debate em torno do neoliberalismo.Mais recentemente, Evans e Mann participaram do debate em torno do conceito de "capacidade estatal", questionando a associação entre capacidade e impermeabilidade do Estado.Os autores do presente volume encontram nesse debate várias pistas para a proposta da mútua constituição.Um dos conceitos centrais apresentados no livro -os "encaixes" que institucionalizam o acesso de atores sociais ao Estado -é adaptado a partir de uma obra de Skocpol, escrita nos anos 1990 em parte para defender a perspectiva "centrada no Estado", então sob ataque.A autora desafiava a proposta "centrada na sociedade" de autores como Putnam, que atribuía o desempenho estatal unicamente ao que poderíamos chamar de capacidade societária.Skocpol argumentou que as associações são profundamente influenciadas pelas políticas e práticas governamentais.Talvez por isso, ela não traz instrumentos conceituais suficientes para entender como a sociedade participa na constituição dos "encaixes".O presente livro contribui de maneira significativa para preencher esta lacuna e assim empurrar a abordagem neoinstitucionalista de autores como Skocpol um pouco mais para além da dicotomia entre perspectivas centradas na sociedade e no Estado.Inspirados na discussão sobre a mútua constituição de Estado e da sociedade presente na literatura sobre o corporativismo societal, os autores abordam os mecanismos de construção de domínios de agência, por meio dos quais em décadas recentes uma heterogeneidade de organizações não corporativistas adquiriu acesso institucionalizado ao Estado.Como nos sistemas corporativistas, a criação desses "domínios de agência" transforma não somente a estrutura estatal, mas também as práticas sociais.Ao oferecer categorias analíticas para definir os diferentes modos pelos quais "encaixes institucionais" operam na intermediação de interesses, os autores adicionam preciosos conceitos à nossa caixa ainda bastante vazia de ferramentas teóricas para enxergar e explicar a complexa relação entre movimentos e instituições.', '["social movements","institutionalization","social policy","race","gender","state-society relations","civil society","participatory budgeting","participatory institutions","social control","accountability","political representation"]', '10.7476/9788575114797', '9788575114797', 'https://books.scielo.org/id/v4cnf', 'https://books.scielo.org/id/v4cnf/pdf/lavalle-9788575114797.pdf', NULL, 'https://books.scielo.org/id/v4cnf/cover/cover_thumbnail.jpeg', NULL, 41, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v4ddr', 'v4ddr', 'Geoturismo e interpretação ambiental', NULL, '["Jasmine Cardozo Moreira"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Earth and Planetary Sciences', 'Dividido em três partes, este livro enfoca o turismo em áreas naurais, destacando o geoturismo, abrange aspectos ligados à geoconservação em áreas protegidas e os Geoparques e por fim aborda a educação e interpretação ambiental, incluindo diversos exemplos de atividades geoeducativas, interpretativas e turísticas.', '["geotourism","environmental interpretation","geoconservation","protected areas","geoparks","geoscience education","nature-based tourism"]', '10.7476/9788577982134', '9788577982134', 'https://books.scielo.org/id/v4ddr', 'https://books.scielo.org/id/v4ddr/pdf/moreira-9788577982134.pdf', NULL, 'https://books.scielo.org/id/v4ddr/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v4fx5', 'v4fx5', 'Estado, sociedade e formação profissional em saúde: contradições e desafios em 20 anos de SUS', NULL, '["Gustavo Corrêa Matta","Júlio César França Lima"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'ApresentaçãoEste livro foi elaborado especialmente como parte das comemorações dos vinte anos de inscrição do Sistema Único de Saúde (SUS) na Constituição brasileira de 1988.Seu objetivo é atualizar o debate em torno da Reforma Sanitária brasileira, buscando contribuir para a formulação de políticas de educação profi ssional em saúde consoantes com uma perspectiva emancipatória de educação dos trabalhadores, especialmente dos técnicos da saúde.No processo de construção do SUS, a temática da formação dos trabalhadores técnicos da saúde tornou-se uma preocupação crescente, alvo de ações públicas em face da escassez e má distribuição entre os estados brasileiros, mas principalmente por causa do grande contingente de trabalhadores com precária ou nenhuma formação profi ssional.O intenso processo de municipalização dos serviços de saúde que se inicia com as Ações Integradas de Saúde (AISs), em 1983, se aprofunda com a criação do Sistema Único e Descentralizado de Saúde (Suds), em 1987, e se consolida nos anos 1990 coloca, para as forças políticas que se reúnem em torno do projeto da Reforma Sanitária, novos desafi os no que diz respeito ao perfi l do trabalhador necessário para viabilizar a premissa estabelecida constitucionalmente de que a saúde é um direito de todos e dever do Estado, baseada nos princípios de universalidade, eqüidade e integralidade.No contexto de uma democracia restrita e socialmente regressiva que se verifi ca no país ao longo da década de 1990, na qual tiveram peso importante o discurso neoliberal de um único caminho para a superação da crise dos anos 1980 e o sentimento difuso de ''emergência econômica'' , estes vinte anos são marcados também por disputas de projetos na sociedade no que diz respeito, particularmente a estas duas práticas sociais -saúde e educação.Para aprofundar e atualizar esse debate, neste livro, na forma de coletânea, procura-se identifi car as mudanças e contradições que se operam no interior do Estado, na sociedade civil brasileira e no âmbito dessas práticas sociais ao longo deste período.Estão reunidas aqui idéias de dez especialistas de expressão nacional e internacional, organizadas em torno de cinco eixos temáticos -Estado, Políticas Sociais e Saúde; Saúde e Sociedade; Democracia, Participação e Gestão em Saúde; Trabalho e Trabalho em Saúde; e Relação Trabalho e Educação na Saúde; buscamos, O autor ilustra suas refl exões resgatando a historicidade, por exemplo, da política de aleitamento materno, da constituição da saúde pública no Brasil, entre outros aspectos, recorrendo sempre à dimensão dos encontros entre pessoas portadoras de conhecimentos específi cos, apontando para a referida dualidade.No seio mesmo das relações de cuidado permeadas pela medicalização, pela racionalidade médica e pela acumulação de capital no setor Saúde, é possível para o autor (ao considerar que é o sofrimento manifesto que deve orientar o trabalho em saúde) reorientar no cotidiano as práticas de cuidado em direção a relações emancipatórias.Com isso, reafi rma seu compromisso com uma luta que "envolve a adoção de uma perspectiva ético-política como orientadora do trabalho em saúde e do ensino das profi ssões de saúde".Em "A política educacional brasileira na ''sociedade do conhecimento''", Lúcia Neves, ao discutir o fenômeno educativo na dupla perspectiva da educação política e da educação escolar, apresenta algumas explicações para a rápida consolidação e estabilização da hegemonia do projeto mundial burguês de sociedade e de sociabilidade no atual contexto brasileiro, procurando entender, nesse processo, a natureza das reformas de educação escolar que se iniciaram em nosso país no fi nal do século XX.Na perspectiva de educação política, salienta algumas características de uma nova pedagogia da hegemonia para o século XXI e de um novo intelectual urbano, organizador do consentimento ativo do conjunto da população brasileira, bem como algumas estratégias utilizadas para a formação de um novo homem coletivo.Na perspectiva da educação escolar, apresenta algumas características do projeto de massifi cação escolar em sua interface com a política de ciência e tecnologia, particularmente nos países de capitalismo dependente.Consubstanciada em estratégias de legitimação social do capital pós-Consenso de Washington, a nova pedagogia da hegemonia vem permitindo a viabilização de um processo de mudança no padrão de politização das sociedades contemporâneas e contribuindo para viabilizar a metamorfose do Estado de bem-estar para a sociedade do bem-estar, que tem na formatação de um Estado gerencial e de uma nova sociedade civil ativa, sem antagonismos de classes, seus pilares fundamentais.Com base nas refl exões de Gramsci, a autora ressalta a importância da formação de intelectuais urbanos de novo tipo na implementação dessa nova pedagogia da hegemonia, destacando dois ingredientes: 1) o incremento de sua ''capacitação técnica'' , com vistas a contribuir com o aumento da produtividade e a competitividade capitalista no atual estágio do seu desenvolvimento e, concomitantemente, REFERÊNCIAS', '["health professions education","Unified Health System (SUS)","health care reform","municipalization of health services","health technicians","emancipatory education","right to health","neoliberalism","health policy","state-society relations","Brazil","Brazilian Constitution of 1988"]', '10.7476/9788575415054', '9788575415054', 'https://books.scielo.org/id/v4fx5', 'https://books.scielo.org/id/v4fx5/pdf/matta-9788575415054.pdf', NULL, 'https://books.scielo.org/id/v4fx5/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v4wgy', 'v4wgy', 'Classes de palavras na perspectiva da Gramática Discursivo-Funcional: o papel da nominalização no continuum categorial', NULL, '["Roberto Gomes Camacho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Roberto Gomes Camacho enfrenta um problema clássico do Funcionalismo: a questão da categorização linguística, focalizada no modelo em sua natureza contínua, não opositi­va, não negativa. Surgiu daqui a teoria dos protótipos, já bem conhecida no Brasil. Considerando o lado complexo, no sentido de “interligado”, o autor toma como parâmetro as diferenças entre o nome e o verbo, situando a meio caminho o importan­te processo da nominalização, “postulada como constituindo um termo complexo entre os dois outros opostos, tomados como membros prototípicos”. Para comprovar essa postulação, o autor argumenta que as expressões nominalizadas partilham propriedades nominais e verbais, comprovadas, neste caso, pela manutenção da estrutura argumental encontrada no verbo. Com este trabalho, Roberto Gomes Camacho atinge sua plena maturidade intelectual, duramente conquistada ao longo de uma carreira acadêmica exemplar.', '["nominalization","parts of speech","Discursive-Functional Grammar","linguistic categorization","prototype theory","argument structure","functional linguistics","Brazilian Portuguese"]', '10.7476/9786557145197', '9786557145197', 'https://books.scielo.org/id/v4wgy', 'https://books.scielo.org/id/v4wgy/pdf/camacho-9786557145197.pdf', NULL, 'https://books.scielo.org/id/v4wgy/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v52yh', 'v52yh', 'Construcción y significación del territorio. Comunidad El Codito, 2011', NULL, '["Juan David Guevara Salamanca","Miguel Hernández García","Mónica Alexandra Mendoza Molina"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'fundamental ha sido el relato sobre el constructo de comunidad.El presente texto, compuesto por tres partes, es uno de los resultados de un trabajo de investigación participativa, realizado por la Universidad del Rosario, a través de su Instituto Rosarista de Acción Social (Seres) y del Equipo Interdisciplinario de Estudios en Desarrollo Local, 1 en El Codito de la ciudad de Bogotá.Desde el año 2007, se vienen adelantando acciones en este lugar, como parte de la política de responsabilidad social adelantada por la Universidad, que procuran la consolidación de redes de apoyo comunitarias, el empoderamiento de diferentes grupos poblacionales y la implementación de estrategias para el desarrollo local.En su primer capítulo, los textos de este capítulo se adentran en la identificación de los elementos históricos que moldearon el sector de El Codito.El segundo capítulo indaga sobre el constructo de comunidad y su relación con este territorio.El tercer capítulo pretende exponer elementos actuales que se presentan en el sector desde una mirada crítica, actual y globalizada, que obedece a una revisión externa de un pasante internacional que aporta para entablar diálogos más allá de las fronteras nacionales.Estos textos no buscan responder de manera sistemática o concatenada a una pregunta orientadora del libro.Son textos autónomos e independientes que respetan los estilos de los autores y actores inmersos en la contrucción de los textos.El enlace fundamental del texto se encuentra en la relación existente entre comunidad y territorio para el caso de El Codito; lo último se refuerza con el énfasis en permitir que la voz silenciada de los primeros habitantes del sector sea escuchada, por eso los textos fueron elaborados a partir de la voz y referencias de los adultos mayores y de los primeros pobladores de los principales barrios.', '["community building","territory","Bogotá","local development","community empowerment","social responsibility","community support networks","historical context","older adults","marginalized voices","participatory research"]', '10.7476/9789587842067', '9789587842067', 'https://books.scielo.org/id/v52yh', 'https://books.scielo.org/id/v52yh/pdf/guevara-9789587842067.pdf', NULL, 'https://books.scielo.org/id/v52yh/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v5tc8', 'v5tc8', 'IV Congreso de educación Salesiana: desafíos juveniles para una transformación social', NULL, '["Cárdenas Tapia, P. Juan","Llanos Erazo, Daniel"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'En mayo de 2013, la Universidad Politécnica Salesiana (UPS) del Ecuador celebró el I Congreso de Educación Salesiana, en la ciudad de Cuenca. Siete años después y ahora de manera virtual, se llevó a cabo su cuarta edición con el tema: “El proyecto educativo: desafíos juveniles para una transformación social”. El presente volumen recoge 43 trabajos presentados en este IV Congreso: cinco conferencias magistrales y 38 artículos académicos. Los artículos están divididos en cuatro ejes temáticos: “Educación y procesos de participación social”, “Ciudadanías infanto-juveniles”, “Transformaciones pedagógicas y transformación social en un contexto de crisis global” y “Sistema preventivo y educación”. De ellos, siete se publican en portugués y los restantes es español. Asimismo, se cuenta con la participación autores de Ecuador, América Latina y Europa. Se espera que estos textos arrojen luces a los involucrados en el proceso educativo, desde la perspectiva de los jóvenes como sujetos de la educación y en el contexto de las limitaciones que impuso la pandemia por COVID-19.', '["Salesian education","youth","social change","educational project","social participation","youth citizenship","pedagogical transformation","prevention system","COVID-19 pandemic","global crisis"]', '10.7476/9789978106785', '9789978106785', 'https://books.scielo.org/id/v5tc8', 'https://books.scielo.org/id/v5tc8/pdf/cardenas-9789978106785.pdf', NULL, 'https://books.scielo.org/id/v5tc8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v5tv3', 'v5tv3', 'A violência oculta do trabalho: as lesões por esforços repetitivos', NULL, '["Herval Pina Ribeiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Após retrospectiva sobre a violência que acompanha as relações conflituosas entre capital e trabalho nos diversos ciclos da Revolução Industrial, inclusive no Brasil, em que uma das formas é o modo de adoecer e prematuramente morrer dos trabalhadores, o autor sinaliza o papel do Estado e da medicina do trabalho como instâncias normalizadoras e de intervenção na área, com base nas teorias ''positivas'' do nexo causal e ocupacional. A seguir, analisa a violência oculta do trabalho em uma atividade exemplar, a bancária, investigando quando e porque emergem as LER, descrevendo todo o percurso desse adoecimento coletivo e do trabalho com base em 346 depoimentos escritos por trabalhadores de um banco estatal.', '["repetitive strain injury","workplace violence","work-related musculoskeletal disorders","banking sector","state intervention in labor","occupational medicine","causal nexus","labor-capital relations","Industrial Revolution","workers'' testimonies"]', '10.7476/9788575412824', '9788575412824', 'https://books.scielo.org/id/v5tv3', 'https://books.scielo.org/id/v5tv3/pdf/ribeiro-9788575412824.pdf', NULL, 'https://books.scielo.org/id/v5tv3/cover/cover_thumbnail.jpeg', NULL, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v5vq9', 'v5vq9', 'Hilda Hilst e o seu pendulear', NULL, '["Nilze Maria de Azeredo Reguera"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nilze Maria de Azeredo Reguera tenta decifrar criticamente uma das obras mais densas e radicais da escritora paulista Hilda Hilst, os cinco textos em prosa reunidos no livro Fluxo-floema, publicado pela primeira vez em 1970. A autora parte do princípio de que o livro delineia um movimento de oscilação da artista, que tanto colocaria em cena quanto a problematizaria a tradição modernista de que ela foi herdeira, por meio de um questionamento implacável das utopias e do lugar que supostamente caberia ao artista ocupar no final do século 20, em um contexto de opressão. A leitura de cada um dos cinco textos de Fluxo-floema é feita a partir da observação atenta dos procedimentos técnicos empregados por Hilst, sobretudo o de alegorização, em uma abordagem que vai paulatinamente desmontando e reorganizando os textos, nos quais a linguagem é levada ao paroxismo da expressão inclusive a fim de celebrar ritualmente a multiplicidade espiritual e sensorial do ser humano. A pesquisadora também procura situar os cinco textos dentro do conjunto da produção hilstiana, já que Fluxo-floema é um livro que dialogaria com várias outras obras da escritora. Dessa forma, Reguera obtém significados inusitados e atuais tanto do livro em questão quanto de outros trabalhos de Hilst.', '["Hilda Hilst","Brazilian women writers","allegory","utopia","oppression"]', '10.7476/9786557145128', '9786557145128', 'https://books.scielo.org/id/v5vq9', 'https://books.scielo.org/id/v5vq9/pdf/reguera-9786557145128.pdf', NULL, 'https://books.scielo.org/id/v5vq9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v6fmm', 'v6fmm', 'O ardil totalitário: imaginário político no Brasil dos anos de 1930', NULL, '["Eliana de Freitas Dutra"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro não é uma história convencional da política brasileira e também não se limita à “história das mentalidades”. Para definir sua forma, seria necessário colocá-lo no rol das “descidas ao inferno” ao modo de Jean Starobinski. Trata-se de identificar as máscaras totalitárias, repelir o seu falso sorriso, dirigindo os olhos para o outro lado da retórica que hipnotiza os intelectuais, as massas, os líderes. Finda a leitura, podemos encarar o nosso tempo sem medo. Se uma fantasmagoria tão sinistra, como o pensamento totalitário, não conseguiu destruir a arte política, se depois da tormenta veio um interregno democrático no mundo, ainda resta esperança para nós e para nossos filhos. Neste livro lateja semelhante certeza, o que lhe confere a dignidade e a eminência de um essencial trabalho do espírito.', '["totalitarianism","political imaginary","political thought","democracy"]', '10.7476/9786558581000', '9788570419644', 'https://books.scielo.org/id/v6fmm', NULL, NULL, 'https://books.scielo.org/id/v6fmm/cover/cover_thumbnail.jpeg', 359, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v6q62', 'v6q62', 'Própolis e imunidade: comprovações científicas', NULL, '["José Maurício Sforcin"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Este trabalho aborda a composição quimíca da própolis, sua origem botânica, o efeito da sazonalidade sobre sua composição, propriedades biológicas e os efeitos colaterais após sua administração, além dos resultados de projetos no tocante à atividade antimicrobiana da própolis e os resultados obtidos nas ações imunomoduladora e antitumoral da própolis, apresentando seus possíveis mecanismos de ação. O trabalhos destina-se tanto a comunidade médica quanto ao público leigo.', '["propolis","chemical composition","botanical origin","seasonal variation","biological characteristics","adverse effects","antimicrobial activity","immunomodulation","anticancer activity","mechanism of action"]', '10.7476/9788539304455', '9788571399259', 'https://books.scielo.org/id/v6q62', NULL, NULL, 'https://books.scielo.org/id/v6q62/cover/cover_thumbnail.jpeg', 67, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v6rkd', 'v6rkd', 'Antropologia e nutrição: um diálogo possível', NULL, '["Ana Maria Canesqui","Rosa Wanda Diez Garcia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro traz reflexões unindo questões sociais, da saúde e da nutrição. Na primeira parte, apresenta uma ampla revisão bibliográfica sobre a área da antropologia e da nutrição. Na segunda parte, abordam-se os paradoxos e repercussões das transformações sociais e da internacionalização da economia na cultura alimentar. A terceira parte dedica-se à alimentação tal como ela se configura hoje nos diferentes espaços, privados e públicos, dos contextos urbanos e diante das transformações sociais ocorridas no país nos últimos 35 anos.', '["food culture","social change","economic globalization","food and health","urban food"]', '10.7476/9788575413876', '9788575413876', 'https://books.scielo.org/id/v6rkd', 'https://books.scielo.org/id/v6rkd/pdf/canesqui-9788575413876.pdf', NULL, 'https://books.scielo.org/id/v6rkd/cover/cover_thumbnail.jpeg', NULL, 64, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v7kxp', 'v7kxp', 'Deserdados sociais: condições de vida e saúde dos presos do estado do Rio de Janeiro', NULL, '["Maria Cecília de Souza Minayo","Patrícia Constantino"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra evoca uma discussão sobre as desigualdades, as iniquidades e a violência social entranhadas na realidade brasileira e expressas na situação de encarceramento. A questão da saúde é analisada em conjunto com o contexto social dos presos e as condições ambientais do encarceramento. Por meio de entrevistas, pesquisas, avaliações e observações, os autores buscam compreender o funcionamento do sistema prisional do Rio de Janeiro. A coletânea apresenta as condições sociais e de saúde dos presos e discute de que forma o ambiente das unidades prisionais impacta a saúde e a qualidade de vida dos detentos. Mostra, ainda, que o antes, o durante e o depois da prisão estão entrelaçados. Há “uma linha de continuidade entre o fora e o dentro da prisão, tanto nas condições sociais como no que afeta direta e indiretamente a saúde física e mental dos detentos, de seus familiares e até de seu entorno comunitário além de se evidenciarem ações que poderiam contribuir para que a vida no cárcere não fosse apenas castigo, dor e perpetuação da exclusão social”, afirma a socióloga Julita Lemgruber, responsável pelo Centro de Estudos de Segurança e Cidadania da Universidade Candido Mendes. “A leitura deste livro passa a ser obrigatória para todos os que atuam no sistema, militam em direitos humanos e apostam na construção da democracia brasileira”, completa, no texto da quarta capa do livro. O objetivo é que promotores, integrantes da Defensoria Pública, gestores e demais profissionais envolvidos com o sistema prisional encontrem neste livro conhecimentos que contribuam para sua atuação.', '["prisoners'' health","prison conditions","social inequality","social exclusion","social violence","penitentiary system","quality of life in prison","prison environment","social determinants of health","human rights in prisons"]', '10.7476/9788575415313', '9788575414651', 'https://books.scielo.org/id/v7kxp', NULL, NULL, 'https://books.scielo.org/id/v7kxp/cover/cover_thumbnail.jpeg', 252, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v7mzs', 'v7mzs', 'Liberata: a lei da ambigüidade - as ações de liberdade da corte de apelação do Rio de Janeiro no século XIX', NULL, '["Keila Grinberg"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Liberata foi personagem da vida real. Escrava, depois liberta, mãe enquanto escrava e mãe já liberada, enfim defunta, tudo na primeira metade do século XIX. Neste livro, Liberata é quase ficção, ou antes, autora de ficção. Ela propõe o enigma de sua vida, tal como registrado nos documentos centenários sob guarda do Arquivo Nacional no Rio de Janeiro, e ela mesma guia o investigador pelos labirintos de interpretação e evidências que permitirão decifrar o próprio enigma.', '["Liberata","abolition of slavery","freedmen","women''s freedom","19th-century Brazil","archival sources","slavery in Brazil","women''s history"]', '10.7476/9788599662762', '9788599662762', 'https://books.scielo.org/id/v7mzs', 'https://books.scielo.org/id/v7mzs/pdf/grinberg-9788599662762.pdf', NULL, 'https://books.scielo.org/id/v7mzs/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v7ywf', 'v7ywf', 'Mercado e Utopia', NULL, '["Fábio Wanderley Reis"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este volume contém textos escritos ao longo de muitos anos. O reclamo usual nessas circunstâncias é o de que os textos esparsos que se reúnem apresentam, na verdade, unidade e coerência. Longe de refugar esse reclamo, sustento-o com força no caso presente. [trecho retirado do prefácio do livro]', '["markets","utopia","political economy"]', '10.7476/9788599662793', '9788599662793', 'https://books.scielo.org/id/v7ywf', 'https://books.scielo.org/id/v7ywf/pdf/reis-9788599662793.pdf', NULL, 'https://books.scielo.org/id/v7ywf/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v8j5c', 'v8j5c', 'Configuración de la noción de discapacidad en un contexto de vulnerabilidad en Bogotá. Análisis interdisciplinar', NULL, '["Paola Balanta Cobo","Rosario Estrada Hernández","Francene Rodríguez Díaz","Nadia Rodríguez Jiménez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'la transformación propuesta por el modelo social, años noventa en adelante ................', '["disability","vulnerability","social model of disability","social change","Bogotá"]', '10.7476/9789587384758', '9789587384758', 'https://books.scielo.org/id/v8j5c', 'https://books.scielo.org/id/v8j5c/pdf/balanta-9789587384758.pdf', NULL, 'https://books.scielo.org/id/v8j5c/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v8k8p', 'v8k8p', 'Morte e progresso', NULL, '["Francisco Foot Hardman"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O difundido retrato da suposta cordialidade brasileira, ilustrada pelos cenários carnavalescos ou pelo futebol, sistematicamente oculta a violência, latente ou explícita, do preconceito, da exclusão e da repressão sociais. A eficiência com que as elites ocultam essa face brutal de nossa sociedade exige um trabalho de rastreamento, de descobrimento de pistas que revelem o autoritarismo subjacente e forneçam uma interpretação mais justa. Os ensaios que compreendem este livro têm por objetivo justamente levar a cabo essa tarefa ao criticar a imagem e auto-imagem da República.', '["Brazilian Republic","social exclusion","prejudice","social repression","authoritarianism","elites","national image","social inequality"]', '10.7476/9788539302734', '9788571391963', 'https://books.scielo.org/id/v8k8p', NULL, NULL, 'https://books.scielo.org/id/v8k8p/cover/cover_thumbnail.jpeg', 143, 33, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v9', 'v9', 'Vigilância alimentar e nutricional: limitações e interfaces com a rede de saúde', NULL, '["Inês Rugani Ribeiro de Castro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Contribuição para o campo ainda pouco definido da vigilância alimentar e nutricional e do Sistema que pretende integrá-la no País (o Sisvan). De elevado alcance pragmático, a obra questiona o papel do setor saúde - particularmente em relação ao perfil de nutrição da população brasileira - e fornece elementos de decisões para os formuladores de políticas, planejadores e executores de programas e atividades de alimentação e nutrição. Abrange os seguintes assuntos: história do Sisvan e da nutrição brasileira - aí incluída a transição epidemiológica; perfil de morbimortalidade e a situação de crianças, gestantes e adultos; vigilância epidemiológica; programas de atenção à saúde integral da criança, do adolescente e da mulher.', '["food and nutrition surveillance","SISVAN","health system integration","disease surveillance","epidemiological transition","morbidity and mortality","child health","adolescent health","maternal health","nutrition policy"]', '10.7476/9788575412947', '9788575412947', 'https://books.scielo.org/id/v9', 'https://books.scielo.org/id/v9/pdf/castro-9788575412947.pdf', NULL, 'https://books.scielo.org/id/v9/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-v93yh', 'v93yh', 'A ciência como profissão: médicos, bacharéis e cientistas no Brasil (1895-1935)', NULL, '["Dominichi Miranda de Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro aborda o processo de especialização da atividade intelectual no Brasil durante as três primeiras décadas do século XIX, ao mesmo tempo em que analisa a emergência do ´cientista´ nesse processo, no qual já se anunciava o divórcio entre as ´humanidades´e as ´ciências duras´.', '["science as a profession","history of science","physicians","bachelors","scientists","professionalization of science","Brazil"]', '10.7476/9788575413081', '9788575413081', 'https://books.scielo.org/id/v93yh', 'https://books.scielo.org/id/v93yh/pdf/sa-9788575413081.pdf', NULL, 'https://books.scielo.org/id/v93yh/cover/cover_thumbnail.jpeg', NULL, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vb6vz', 'vb6vz', 'Retos y tendencias del derecho electoral', NULL, '["Rocío Mercedes Araújo Oñate"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La institucionalización de la participación ciudadana y de mecanismos de participación del pueblo en el ejercicio de su soberanía es la apuesta que hizo Colombia en la década de 1980. Motiva esta decisión política la falta de legitimación democrática de las instituciones, los representantes y los gobernantes, así como una necesidad de inclusión de los ciudadanos en las decisiones políticas y administrativas que los afectan. Por esta razón, las Facultades de Jurisprudencia y de Ciencia Política y Gobierno, en asocio con la Registraduría Nacional del Estado Civil, se han propuesto realizar una reflexión académica de primer nivel y que corresponde a la especial coyuntura política, para poder sopesar los elementos democráticos, políticos, electorales y administrativos que juegan un especial rol en el desarrollo de nuestras instituciones democráticas.', '["electoral law","citizen participation","popular sovereignty","democratic legitimacy","political inclusion","electoral institutions"]', '10.7476/9789587384895', '9789587384888', 'https://books.scielo.org/id/vb6vz', NULL, NULL, 'https://books.scielo.org/id/vb6vz/cover/cover_thumbnail.jpeg', 516, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vb8vm', 'vb8vm', 'Salvador em crise: desafios urbanos contemporâneos', 'desafios urbanos contemporâneos', '["João Pena","Hortensia Pinho","Ordep Serra","Débora Nunes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Salvador em crise: desafios urbanos contemporâneos reúne análises críticas e plurais sobre os principais desafios urbanos da capital baiana em um momento decisivo para a revisão do Plano Diretor de Desenvolvimento Urbano (PDDU). Com textos de 20 autores e autoras, a obra aborda temas fundamentais como habitação, planejamento de bairros, questões ambientais e patrimônio, além de debates urgentes sobre memória da escravidão, direito à paisagem, sexualidade e direito à cidade. Ao refletir também sobre os impactos da pandemia de covid-19 no espaço urbano, o livro propõe uma discussão pública ampla e comprometida com a construção de uma Salvador mais justa, democrática e inclusiva.', '["Salvador, Bahia","urban problems","urban planning","housing","neighborhood planning","environmental problems","cultural heritage","memory of slavery","right to landscape","sexuality","right to the city","COVID-19 pandemic impact"]', '10.7476/9786556309217', '9786556309217', 'https://books.scielo.org/id/vb8vm', 'https://books.scielo.org/id/vb8vm/pdf/pena-9786556309743.pdf', NULL, 'https://books.scielo.org/id/vb8vm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vbv2h', 'vbv2h', '¡Ush, éstas nenas hablan como manes! Una aproximación etnográfica a las relaciones de género en la escena del rock transgresivo en Bogotá', NULL, '["Torre Jaimes, Andrea de la"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2012, NULL, 'es', 'book', 'humanities', 'Humanidades y Artes', NULL, 'La obra tiene como objetivo principal comprender cómo se naturaliza y se racionaliza una relación de actividad masculina y de pasividad femenina sin imponerse de manera violenta en una escena local de rock en Bogotá. La investigación reúne las nociones de juventud, género y música rock con el fin de pensar las relaciones de género a través de la atribución de roles y cualidades a los individuos, la existencia de jerarquías, la ocupación física del espacio y la representación de lo masculino y lo femenino en los discursos y prácticas individuales. Con un enfoque etnográfico, la metodología consistió en entrevistas a profundidad, observaciones participantes y análisis de discurso de letras de canciones. La obra final mezcla todas las fuentes primarias en un texto agradable a la lectura, sencillo en sus términos, que causa curiosidad por el lenguaje, las fotografías y la organización misma del documento. Se divide en cuatro capítulos principales más las conclusiones, división que presenta así la investigación: una introducción provocativa que da los primeros cuestionamientos, un primer capítulo teórico con la metodología y el problema de investigación, un segundo capítulo que presenta a la escena musical de Bogotá y a los protagonistas de la etnografía. El tercer capítulo analiza letras de canciones, el cuarto capítulo describe etnográficamente la escena y las conclusiones reúnen todo el documento y plantean la tensión entre la teoría y la investigación misma. La obra está dirigida especialmente a estudiantes y profesionales del área de las ciencias humanas pero también a un público interesado en la investigación social y en la música como un escenario de discusión.', '[]', '10.7476/9789585005303', '9789587382518', 'https://books.scielo.org/id/vbv2h', 'https://books.scielo.org/id/vbv2h/pdf/torre-9789585005303.pdf', 'https://books.scielo.org/id/vbv2h/epub/torre-9789585005303.epub', 'https://books.scielo.org/id/vbv2h/cover/cover_thumbnail.jpeg', 156, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vcxtr', 'vcxtr', 'Bricolagem alimentar nos estilos naturais', NULL, '["Maria Cláudia da Veiga Soares Carvalho"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Partindo de uma perspectiva socioantropológica baseada em Lévi-Strauss e outros teóricos, a autora observa adeptos de estilos de alimentação natural como a vegana e o alimento vivo. Com isso, constrói uma análise interpretativa sobre os sentidos e significados no campo da nutrição, contribuindo para o campo da saúde coletiva. Ao pesquisar o significado dos alimentos na sociedade, propõe uma reflexão sobre a cultura alimentar no Ocidente.', '["natural diet","veganism","raw food diet","food culture","meaning of food","nutrition","collective health","Lévi-Strauss","Western food culture"]', '10.7476/9786588808078', '9786588808078', 'https://books.scielo.org/id/vcxtr', 'https://books.scielo.org/id/vcxtr/pdf/carvalho-9786588808078.pdf', NULL, 'https://books.scielo.org/id/vcxtr/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vdywc', 'vdywc', 'Labirinto de espelhos formação da auto-estima na infância e adolescência', NULL, '["Simone Gonçalves de Assis","Joviana Quintes Avanci"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Lidar com os anseios e questionamentos da adolescência não parece ser uma tarefa das mais fáceis, mas Labirintos de Espelhos - fomação da auto-estima na infância e na adolescência, consegue tratar do assunto de maneira mais acessível, sem, contudo, abandonar o caráter científico de uma pesquisa. As autoras, através dos depoimentos de diversos adolescentes, revelam que problemas como violência, relacionamento familiar e rendimento escolar, podem estar ligados a uma peça fundamental na formação destes jovens: a auto-estima. Nesta obra, o problema da auto-estima não constitui um fato isolado, mas sim uma questão que deve ser tratada como problema social e precisa ser encarada pela sociedade com a devida seriedade que há neste livro.', '["self-esteem","adolescence","childhood","youth violence","family relationships","academic performance","social problems","youth development"]', '10.7476/9788575413333', '9788575413333', 'https://books.scielo.org/id/vdywc', 'https://books.scielo.org/id/vdywc/pdf/assis-9788575413333.pdf', NULL, 'https://books.scielo.org/id/vdywc/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vf582', 'vf582', 'O campo da saúde coletiva: gênese, transformações e articulações com a reforma sanitária brasileira', NULL, '["Lígia Maria Vieira-da-Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra da professora e pesquisadora Ligia Maria Vieira-da-Silva propõe reflexões aprofundadas sobre a trajetória histórica da área de Saúde Coletiva no Brasil. O título é uma coedição da Editora Fiocruz e da EDUFBA, editora da Universidade Federal da Bahia, instituição na qual a autora integra o corpo docente permanente do Programa de Pós-Graduação em Saúde Coletiva. Em um momento crítico e repleto de desafios para a produção científica do país, o livro amplia debates “acerca das interfaces entre produção do conhecimento científico e tecnológico em saúde, ativismo e construção de políticas públicas ao longo da segunda metade do século XX no Brasil e todas suas projeções presentes e futuras”, como afirma o pesquisador titular da Escola Nacional de Saúde Pública Sergio Arouca (ENSP/Fiocruz), Carlos Everaldo Alvares Coimbra Junior. Em conjunto com outros renomados pesquisadores da área no Brasil, a autora examina as profundas relações entre a Saúde Coletiva e a Reforma Sanitária Brasileira. É um livro, segundo a pesquisadora, que aponta – ao longo do percurso histórico abordado – transformações, rupturas, continuidades, identidades e diferenças. Com artigos nos capítulos 5 e 6, os professores Jairnilson Silva Paim, Sandra Garrido de Barros, Jamacy Costa Souza e Gerluce Alves Pontes da Silva participam como coautores de uma obra que já nasce fundamental para a consolidação dos estudos relacionados ao complexo campo da Saúde Coletiva.', '["history of public health","Brazilian health reform","history of public health in Brazil","health activism","public health policy"]', '10.7476/9786557080740', '9788575416198', 'https://books.scielo.org/id/vf582', NULL, NULL, 'https://books.scielo.org/id/vf582/cover/cover_thumbnail.jpeg', 271, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vf58z', 'vf58z', 'Democracia e justiça na América Latina: para onde vamos?', NULL, '["Lígia Mori Madeira","Marjorie Marona","Andrés Del Río"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Aborda a judicialização de questões que envolvem políticas públicas, conflitos políticos e valores morais e políticos fundamentais, como um dos fenômenos mais significativos das democracias que atravessaram o século XX em direção ao século XXI. Sob o viés dos estudos da ciência política, os autores apresentam uma variedade de perspectivas sociojurídicas e empíricas sobre temas cruciais. São objetos de análise o papel dos tribunais e a ampla gama de instituições que fazem parte do sistema de justiça, como promotores e defensores públicos, além de outros atores, dispositivos e movimentos que atuam nesse contexto em que se articulam as decisões legais. A leitura instiga uma reflexão sobre o papel da justiça e das instituições judiciárias na América Latina, perante os desafios econômicos, sociais e políticos ou diante de contextos nocivos a direitos e práticas democráticas.', '["judicialization","Latin American democracy","justice","courts","public prosecutor","public defenders","judicial institutions","public policy","political conflict","law and society","democratic backsliding","protection of rights"]', '10.7476/9786587949550', '9786587949550', 'https://books.scielo.org/id/vf58z', 'https://books.scielo.org/id/vf58z/pdf/madeira-9786587949550.pdf', NULL, 'https://books.scielo.org/id/vf58z/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vfg6x', 'vfg6x', 'Escravidão e liberdade no agreste da Bahia: Inhambupe e Alagoinhas século XIX', NULL, '["Almeida, Kátia Lorena Novais"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Durante muito tempo a história de Inhambupe e Alagoinhas foi conhecida pela narrativa dos memorialistas, a qual não incorporava a presença de africanos e afrodescendentes. Este livro, fruto de pesquisas em arquivos históricos, traz elementos que valorizam a história dos africanos e seus descendentes, buscando compreender a dinâmica da sociedade escravista que ali se formou.', '["slavery","Alagoinhas","Afro-Brazilian history","African descendants","slave society","19th century","historical memory","memorialists"]', '10.7476/9786588211977', '9786588211663', 'https://books.scielo.org/id/vfg6x', 'https://books.scielo.org/id/vfg6x/pdf/almeida-9786588211977.pdf', 'https://books.scielo.org/id/vfg6x/epub/almeida-9786588211977.epub', 'https://books.scielo.org/id/vfg6x/cover/cover_thumbnail.jpeg', 216, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
