INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vgr7y', 'vgr7y', 'Planejamento em Enfermagem: aplicação do processo de enfermagem na prática administrativa', NULL, '["Ricardo Matos Santana","Ângela Tamiko Sato Tahara"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Este livro descreve os principais conceitos teóricos, instrumentos metodológicos e trajetória histórica do planejamento em Saúde em seus diferentes enfoques. A sua aplicação na gestão de Enfermagem é apresentada através da sistematização do planejamento estratégico utilizado na Saúde, especificamente a Trilogia Matusiana com a estrutura metodológica do processo de Enfermagem.', '["nursing care planning","nursing process","health planning","nursing management","health management"]', '10.7476/9788574555294', '9788574555294', 'https://books.scielo.org/id/vgr7y', 'https://books.scielo.org/id/vgr7y/pdf/santana-9788574555294.pdf', NULL, 'https://books.scielo.org/id/vgr7y/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vhnkh', 'vhnkh', 'Samambaias e licófitas no Brasil: biologia e taxonomia', 'biologia e taxonomia', '["Santos, Marcelo Guerra","Santiago, Augusto César Pessôa","Lana da Silva Sylvestre"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Finalistas Prêmio Jabuti Acadêmico. Idealizado e organizado pelo Núcleo de Pteridologia da Sociedade Botânica do Brasil, este livro aborda aspectos da biologia e da taxonomia das samambaias e licófitas a partir de estudos realizados na flora brasileira. A publicação utiliza a linguagem de textos acadêmicos e é ricamente ilustrada com exemplos da diversidade de samambaias e licófitas tropicais.', '["ferns","lycophytes","fern taxonomy","tropical flora","Brazilian flora","pteridology"]', '10.7476/9788575115848', '9788575115831', 'https://books.scielo.org/id/vhnkh', 'https://books.scielo.org/id/vhnkh/pdf/santos-9788575115848.pdf', NULL, 'https://books.scielo.org/id/vhnkh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vhpcy', 'vhpcy', 'Eternidade do instante: gifs, loopings, imagem técnica atemporal', NULL, '["Wayner Tristão Gonçalves"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Quais são os dispositivos atuais de representação e suas linguagens, como transformam nossa percepção? Questões como essas são discutidas neste livro que aborda a aceleração e a repetição como marcas dos dias atuais. A obra destaca o gif como forma de representação dessa aceleração/repetição em constante looping, sobretudo no mundo virtual.', '["GIF","looping","acceleration","repetition","technical images","perception","virtual worlds","digital representation"]', '10.7476/9786586213850', '9786586213799', 'https://books.scielo.org/id/vhpcy', NULL, NULL, 'https://books.scielo.org/id/vhpcy/cover/cover_thumbnail.jpeg', 201, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vjcdj', 'vjcdj', 'Filhas do mundo: infração juvenil feminina no Rio de Janeiro', NULL, '["Simone Gonçalves de Assis","Patrícia Constantino"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Quer compreender o que há de específico no universo das jovens infratoras internadas em instituições para cumprimento de medidas socioeducativas no Rio de Janeiro. Os motivos que levam as jovens ao crime são discutidos, confrontando algumas teorias com o trabalho empírico que alia observação de campo, análise de desenhos, diários pessoais e entrevistas com as jovens, bem como análise de seus prontuários e de entrevistas com as mães e com os(as) técnicos(as) da escola onde estão recolhidas. Filhas do Mundo será grande valia a todos que buscam saídas para a superação da violência nas mais variadas formas de manifestação.', '["female juvenile offenders","juvenile delinquency","socio-educational measures","juvenile detention","causes of crime","violence","Rio de Janeiro"]', '10.7476/9788575413234', '9788575413234', 'https://books.scielo.org/id/vjcdj', 'https://books.scielo.org/id/vjcdj/pdf/assis-9788575413234.pdf', NULL, 'https://books.scielo.org/id/vjcdj/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vjg5t', 'vjg5t', 'La diáspora latinoamericana a España, 1997-2007. Incógnitas y realidades', NULL, '["David L. Roll"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A partir de 1492, millares de españoles llegaron a habitar lo que hoy es América Latina, tras surcar el Atlántico en azarosas embarcaciones. Quinientos años después, entre 1997 y 2007, en dirección contraria y en cómodos vuelos, cientos de miles de sus descendientes recorrieron el camino opuesto para conquistar con su fuerza laboral y su singular cultura multiétnica la vieja España. ¿Por qué se fueron tantos de los nuestros en esta primera diáspora latinoamericana del tercer milenio? ¿Regresarán cuando la crisis europea se vuelva insoportable? ¿Y qué significará en un mundo globalizado, en términos de bienestar y codesarrollo, esta movilización de ciudadanos, sobre todo andinos, hacia la Europa hispanohablante? A estas preguntas sobre un fenómeno migratorio de gran magnitud ¬¬que pasó, en gran medida, desapercibido en el contexto de las políticas públicas y del mundo académico intentan dar respuesta en este libro David Roll y algunos miembros del Grupo de Investigación de la Universidad Nacional, UNmigraciones, con la colaboración de prestigiosos escritores e investigadores del Centro de Estudios Políticos e Internacionales, de la Universidad del Rosario (CEPI).', '["Latin American diaspora","return migration","Andean migrants","labor migration","migration policy","globalization"]', '10.7476/9789587384161', '9789587384154', 'https://books.scielo.org/id/vjg5t', NULL, NULL, 'https://books.scielo.org/id/vjg5t/cover/cover_thumbnail.jpeg', 215, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vjhfp', 'vjhfp', 'Atenção Psicossocial além da Reforma Psiquiátrica: contribuições a uma Clínica Crítica dos processos de subjetivação na Saúde Coletiva', NULL, '["Carlos Zacarias de Sena Júnior"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra reúne uma série de ensaios produzidos a partir da preocupação do autor em colaborar com o desenvolvimento de diferentes aspectos da Atenção psicossocial. Para ele, a Atenção psicossocial é o “conjunto de ações realizadas no campo da saúde mental, geralmente denominadas tratamento, cuidado, promoção e mesmo atenção” A definição do paradigma de Atenção psicossocial é o objeto dos ensaios e lhes dá unidade, embora cada texto possa ser lido independentemente. Para o autor, o termo “psicossocial”, que tradicionalmente se referia apenas a aspectos psíquicos e sociais secundários à prática psiquiátrica, passou a aspirar o status de conceito, determinando um novo campo da práxis, a partir do momento em que a crítica mais radical à atividade psiquiátrica contribui para sua transformação. Nas últimas décadas, desde que o Ministério da Saúde estabeleceu a Atenção psicossocial como política pública nacional, delimitou-se um campo de saberes baseados em um ideário ético-político que veio a substituir a psiquiatria centrada nas práticas hospitalares e médicas. E, embora hoje o antigo modo de exercício da psiquiatria se encontre subordinado ideologicamente, continua sendo percebido nas práticas cotidianas. De acordo com o autor, “este conjunto de ensaios, com as preocupações teóricas, técnicas e éticas que os atravessam, pretende ser uma contribuição para melhorar nossas caixas de ressonância para a receptividade das demandas dos indivíduos que nos procuram nas instituições substitutivas do manicômio e do hospital psiquiátrico”.', '["Brazilian Communist Party (PCB)","anti-fascism","bourgeois revolution","Luiz Carlos Prestes","political strategy","Brazilian communism","World War II"]', '10.7476/9786556305042', '9786556305042', 'https://books.scielo.org/id/vjhfp', 'https://books.scielo.org/id/vjhfp/pdf/sena-9786556305042.pdf', NULL, 'https://books.scielo.org/id/vjhfp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vjsgn', 'vjsgn', 'Jorge Zalamea, enlace de mundos: quehacer literario y cosmopolitismo (1905-1969)', NULL, '["Andrés López Bermúdez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Inscrita en el marco de la historia social de la literatura, esta investigación contextualiza la obra literaria del escritor bogotano Jorge Zalamea en su trayectoria vital (1905-1969). Parte de la premisa de que texto y autor constituyen una unidad inseparable, por lo que el ciclo vital del literato puede aportar a la comprensión de su producción intelectual. Puntualiza las posturas del personaje estudiado frente a tópicos como la función social del escritor y la profesionalización del oficio, su lugar dentro de un tejido de relaciones y contextos, sus vinculaciones con instituciones sociales y literarias, su percepción sobre la responsabilidad intelectual, y su integración a círculos de pensamiento y poder influyentes sobre la configuración de la sociedad de su tiempo. Relaciona entonces -desde una perspectiva sociológica la situación de un escritor específico con estructuras, clases o grupos sociales, en aras de la formulación de explicaciones y análisis.', '["Colombian literature","cosmopolitanism","professionalization of writing","intellectual responsibility","literary institutions","20th-century literature"]', '10.7476/9789587385663', '9789587385656', 'https://books.scielo.org/id/vjsgn', NULL, NULL, 'https://books.scielo.org/id/vjsgn/cover/cover_thumbnail.jpeg', 584, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vjtsp', 'vjtsp', 'Mãe/mulher atrás das grades: a realidade imposta pelo cárcere à família monoparental feminina', NULL, '["Amanda Daniele Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A árdua tarefa de viver a maternidade atrás das grades é o cerne da presente obra. Mediante o desrespeito às inúmeras formas de se constituir família, premente é o debate sobre os modos de sobrevivência das famílias monoparentais femininas cuja principal responsável encontra-se privada de liberdade. Através da experiência vivida pelas reclusas da Cadeia Pública Feminina de Franca/SP, identificamos quem são estas mulheres, como vivem e onde e com quem estão seus filhos, evidenciando, assim, a sobrecarga de responsabilidades imposta às mães devido à irrefutável desigualdade de gênero. Com isto, visamos dar visibilidade às mulheres cujas grades da prisão cindam sua convivência familiar.', '["incarcerated mothers","women prisoners","single-parent families","female-headed households","motherhood","prisons","gender inequality","family life","women''s prisons"]', '10.7476/9788579837036', '9788579837036', 'https://books.scielo.org/id/vjtsp', 'https://books.scielo.org/id/vjtsp/pdf/silva-9788579837036.pdf', NULL, 'https://books.scielo.org/id/vjtsp/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vk5yj', 'vk5yj', 'Educação escolar entre as grades', NULL, '["Elenice Maria Cammarosano Onofre"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Educação escolar entre as grades é uma coletânea de textos de pesquisadores da área da educação escolar nas prisões. Partindo do princípio fundamental de educação como essência transformadora, apresenta a escola como possibilidade, embora a cultura prisional se caracterize pela repressão, ordem e disciplina. Os estudos apresentados permitem o repensar de possíveis caminhos para as escolas das prisões, na medida em que estas se constituem em mediadoras entre saberes, culturas e realidade, oferecendo possibilidades que, ao mesmo tempo, libertem e unam os excluídos que vivem no interior das unidades prisionais.', '["prison education","school education","prison culture","educational transformation","social exclusion","prisoners","prison schools","knowledge and culture"]', '10.7476/9788576003687', '9788576003687', 'https://books.scielo.org/id/vk5yj', 'https://books.scielo.org/id/vk5yj/pdf/onofre-9788576003687.pdf', NULL, 'https://books.scielo.org/id/vk5yj/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vk6xk', 'vk6xk', 'A nova onda Baiana: cinema na Bahia (1958-1962)', NULL, '["Maria do Socorro Carvalho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro "A Nova Onda Baiana" faz uma análise do desenvolvimento artístico aflorado entre 1958 e 1962 em Salvador que acabou por colocar a capital baiana do eixo da produção cinematográfica nacional e colaborar para o surgimento de um dos principais núcleos formadores do então emergente Cinema Novo. Esta interessante obra traz não apenas um mero registro deste boom cinematográfico, mas uma análise perfuratriz de alguns filmes realizados neste período, através de uma combinação rara neste tipo de publicação: fino tratamento literário, profunda pesquisa e extremamente agradável de se ler.', '["Cinema Novo","Salvador, Bahia","film analysis","Brazilian film history"]', '10.7476/9788523212421', '9788523202811', 'https://books.scielo.org/id/vk6xk', NULL, NULL, 'https://books.scielo.org/id/vk6xk/cover/cover_thumbnail.jpeg', 218, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vkqwk', 'vkqwk', 'Universidade e estratégia: a região como ambiente organizacional: trajetória de expansão da Universidade Estadual de Feira de Santana', 'a região como ambiente organizacional: trajetória de expansão da Universidade Estadual de Feira de Santana', '["Carlos Eduardo Cardoso de Oliveira"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Na Bahia, o ensino universitário estadual com a dimensão regional começa em Feira de Santana. A criação pela comunidade feirense, seguida da necessária participação governamenal, possibilitou que tivéssemos uma primeira Universidade Estadual. Pioneirismo e regionalidade. Dessa maneira, coube a Feira de Santana a primazia em atender à população urbana e regional com a interiorização do ensino superior universitário. É um privilégio que todos nós temos de nos orgulhar A UEFS é, desde o seu começo, uma universidade pública, gratuita e de qualidade.', '["Universidade Estadual de Feira de Santana","higher education expansion","regional strategy","regional universities","organizational context","regionalization of higher education","public universities","university history","Feira de Santana","Bahia"]', '10.7476/9788555921681', '9788555920646', 'https://books.scielo.org/id/vkqwk', NULL, NULL, 'https://books.scielo.org/id/vkqwk/cover/cover_thumbnail.jpeg', 422, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vkr56', 'vkr56', 'Travessias de Cecília: a caminho da educação matemática no Ceeja Padre Moretti (Rondônia)', NULL, '["Edna Maria Cordeiro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Initially, this research intended only realize the scenario of Mathematics Education in the Centro Estadual de Educação de Jovens e Adultos (CEEJA) Padre Moretti, the historical path from 1977 to 2012, but the go thru the perspective of the New Cultural History as thought by Chartier (1990), the survey was expanded from data obtained on the performance of that center, the story of Rondônia and the family of Cecilia character of this text. Consequently, were also discussed formative processes of character and other teachers in Rondônia. The data emerging from the creation of documents such as laws, resolutions and ordinances (legal framework) referencing EJA courses in Rondônia; designs found in the archives of CEEJA; located in old newspapers library Francisco Meirelles, and memories of Cecilia and ten respondents (graduates and professors). Interpretations we had from the collected data gave rise to the polyphonic text and dialogical perspective of Bakhtin (2011). The concept of culture, from Geertz (2008) enabled the construction of history, that is, Cecilia crossings in search of an understanding about the plot of this text that moves between difficulties and opportunities of characters text and Education in the state of Rondônia. With regard to history of Rondônia, was perceived diversity of opportunities work up and the population of financial improvements, however were always present many difficulties, such as lack of infrastructure, education and health, and political performances uncommitted to the general population. In the history of Education Youth and Adults (EJA) in Rondônia and CEEJA moments were identified oscillations between extending the decline in attendance and performances and the number of students of the institution. When analyzing the data on Mathematics, the most frequently observed difficulties in the learning process were: lack of prior knowledge of students to accompany a curriculum geared toward...', '["mathematics education","youth and adult education","Rondônia","history of education","new cultural history","Chartier","Bakhtin","dialogism","Clifford Geertz","cultural concepts","teacher professional development","student prior knowledge"]', '10.7476/9788579836695', '9788579836695', 'https://books.scielo.org/id/vkr56', 'https://books.scielo.org/id/vkr56/pdf/cordeiro-9788579836695.pdf', NULL, 'https://books.scielo.org/id/vkr56/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vkts5', 'vkts5', 'A aula como produção de conhecimentos: interlocuções com a sociologia da infância', NULL, '["Faria, Ana Lúcia Goulart de","Batista, Eduardo Pereira","Siller, Rosali Rauta"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A experiência proposta neste livro se baseia na concepção freireana de educação. Paulo Freire nos ensina que educar é “um fazer permanente que se refaz constantemente na ação”. Educar exige de nós rigorosidade metódica e pesquisa; exige respeito e criticidade para com os saberes das/os discentes; exige coerência e convicção para corporificar as palavras que enunciamos na ação de educar; exige correr risco, expor-se ao desconhecido e interrogar o novo; exige o reconhecimento da diferença como fundamento para a construção de nossas identidades culturais. As exigências para uma prática docente emancipadora são as mesmas para que uma formação emancipadora seja possível. Portanto, a aula como produção de conhecimentos é potencialmente um espaço para que a emancipação humana seja possível.', '["childhood studies","Paulo Freire","emancipatory education","human emancipation","critical pedagogy"]', '10.7476/9788526816541', '9788526815810', 'https://books.scielo.org/id/vkts5', NULL, NULL, 'https://books.scielo.org/id/vkts5/cover/cover_thumbnail.jpeg', 301, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vm3mb', 'vm3mb', 'Dicionário feminino da infâmia: acolhimento e diagnóstico de mulheres em situação de violência', NULL, '["Elizabeth Ma. Fleury-Teixeira","Stela N. Meneghel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra traz um rico panorama dos conceitos recorrentes na pauta feminista e das mulheres e vai além, apresentando temas e significados em sua dimensão histórica, política e social. Estão explicados fenômenos que envolvem os vários aspectos, tipos e cenários das violências e também formas de resistência, além de informações sobre análises científicas que ampararam a criação de procedimentos, normas, abordagens e técnicas que hoje estão regulamentados e em funcionamento em diversos setores públicos de forma regular e/ou ainda embrionária. Além disso, houve uma preocupação importante: passar aos leitores as mais importantes noções sobre conceitos de liberdade, direitos humanos, justiça, aspectos da educação masculina que levam à prática da violência e outros temas. O ‘Dicionário’ é o resultado de um trabalho que reuniu muitas vozes: mais de cem colaboradores, pesquisadores e/ou profissionais de universidades, agências governamentais, serviços públicos de saúde, seguridade social, segurança pública, jurídico-policiais e organizações não governamentais trabalharam coletivamente na escolha de verbetes significativos e na elaboração dos mesmos.', '["violence against women","intimate partner violence","feminist concepts","violence prevention","resistance to violence","masculinity and violence","human rights","justice","freedom","gender-based violence"]', '10.7476/9788575415511', '9788575415511', 'https://books.scielo.org/id/vm3mb', 'https://books.scielo.org/id/vm3mb/pdf/fleury-9788575415511.pdf', NULL, 'https://books.scielo.org/id/vm3mb/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vmnhq', 'vmnhq', 'Qual prevenção? Aids, sexualidade e gênero em uma favela carioca', NULL, '["Simone Monteiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A partir da temática da proteção, Simone Monteiro relativiza o enfoque epidemiológico de risco, mostrando o modo como os jovens da comunidade de Vigário Geral encaram a sexualidade e suas implicações. Desconstruindo a idéia recorrente no imaginário social de que a questão da prevenção é amplamente difundida na sociedade brasileira, a autora nos apresenta reflexões, com base em depoimentos decorrentes de uma pesquisa aprofundada, que permitem um questionamento crítico sobre o verdadeiro alcance das políticas preventivas em saúde.', '["HIV prevention","sexuality","gender","youth","favelas","preventive health policy","social imaginary","Rio de Janeiro"]', '10.7476/9788575415214', '9788575415214', 'https://books.scielo.org/id/vmnhq', 'https://books.scielo.org/id/vmnhq/pdf/monteiro-9788575415214.pdf', NULL, 'https://books.scielo.org/id/vmnhq/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vncgt', 'vncgt', 'Teorias linguísticas: orientações para a pesquisa', NULL, '["Cid Ivan da Costa Carvalho","Barbosa, José Roberto Alves"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Teorias Linguísticas: orientações para a pesquisa é resultante do diálogo entre vários pesquisadores do Programa de Pós-Graduação em Ciências da Linguagem (PPCL). A proposta deste livro é apresentar um guia para o conhecimento das principais áreas de pesquisa nos estudos da linguagem. Inicialmente, o Prof. Dr. Gilson Chicon Alves discorre sobre o Estruturalismo, destacando suas contribuições para os estudos das línguas, como sistema passível de descrição. Depois, o Prof. Dr. Cid Ivan da Costa Carvalho dá sequência ao percurso, ao desenvolver a empreitada gerativista de explicar a língua como faculdade humana. Em seguida, os Prof.s Dr. José Roberto Alves Barbosa e Dr. Wellington Vieira Mendes contribuem com o enfoque funcional nos estudos da língua, articulando os aspectos formais e funcionais da língua e atentando para suas metafunções. Logo após, o Prof. Dr. Pedro Adrião da Silva Júnior discute a revirada pragmática, bem como seus desdobramentos, com vistas a um modelo de língua(gem) que concebe os usos linguísticos em seus contextos. Por último, a Profa. Dra. Lúcia Helena Medeiros da Cunha Tavares articula a língua e suas relações de poder, com destaque para o discurso como prática social, marcado pelas subjetividades e disputas identitárias fincadas na história. Essas perspectivas teóricas – como mapas e modelos – não foram escolhidas aleatoriamente, mas por serem bastante recorrentes nas disciplinas de teorias linguísticas que estão presentes nos cursos de graduação, mestrado e doutorado em Letras e Linguística; e, além disso, por serem trabalhadas no contexto do PPCL.', '["linguistic theory","structuralism","functional linguistics","pragmatics","metafunction","language and power","discourse as social practice","identity and subjectivity"]', '10.7476/9786587108629', '9786587108629', 'https://books.scielo.org/id/vncgt', 'https://books.scielo.org/id/vncgt/pdf/carvalho-9786587108629.pdf', NULL, 'https://books.scielo.org/id/vncgt/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vp4jt', 'vp4jt', 'Da senzala ao palco: canções escravas e racismo nas Américas, 1870-1930', NULL, '["Martha Abreu"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro analisa o sucesso – nos teatros, nas partituras e na indústria fonográfica – das criações musicais de descendentes de africanos escravizados no Brasil e nos Estados Unidos, entre o final do século XIX e o início do XX. O diálogo entre essas produções revela a densidade dos trânsitos culturais no mundo atlântico e o protagonismo de músicos negros, como Eduardo das Neves e Bert Williams. Sua entrada nos circuitos musicais e artísticos, em meio à construção de estereótipos racistas, constitui exemplo do modo como esses artistas, com talento, ironia e humor, desafiaram e subverteram a inferiorização que lhes era imposta, tornando-se famosos no mercado musical do período. A obra disponibiliza 201 imagens, 47 fonogramas e 5 vídeos, permitindo ver e escutar ao mesmo tempo em que se realiza a leitura do texto.', '["slave songs","racism","racial stereotypes","Bert Williams","music industry","phonographic industry","cultural transplants","Atlantic world","Brazilian music","American music"]', '10.7476/9788526813960', '9788526813960', 'https://books.scielo.org/id/vp4jt', NULL, NULL, 'https://books.scielo.org/id/vp4jt/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vpjzm', 'vpjzm', 'Coletânea Covid-19 e agendas de pesquisa nas ciências sociais', NULL, '["Fernando de Castro Fontainha","Milani, Carlos R. S."]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Propõe ampliar a percepção do impacto do novo Coronavírus na história recente brasileira, o que implica não se ater apenas à questão da saúde, observando também a repercussão na sociedade e na política. Com esse objetivo, analisa a pandemia à luz das agendas de pesquisa nas ciências sociais e humanas. A coletânea aborda o tema sob múltiplos prismas: no mundo do trabalho, em um cenário de instabilidade política, na exposição das vulnerabilidades e desigualdades sociais, nos desafios na adoção de políticas públicas, no âmbito do negacionismo do governo Bolsonaro e suas consequências para as políticas públicas e relações internacionais, e na articulação das Forças Armadas no combate ao Coronavírus como processo de legitimação política da presença militar na vida pública brasileira. Esses e outros aspectos estão presentes nesta obra, que resulta de estudos nas áreas de ciência política, ciência social, antropologia, sociologia e economia.', '["COVID-19 pandemic","research agenda","social sciences","Brazilian politics","Bolsonaro government","political legitimation","military intervention in politics","public policy","social inequality","labor market","political instability","international relations"]', '10.7476/9788575116067', '9788575116067', 'https://books.scielo.org/id/vpjzm', 'https://books.scielo.org/id/vpjzm/pdf/fontainha-9788575116067.pdf', NULL, 'https://books.scielo.org/id/vpjzm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vpwt2', 'vpwt2', 'Os animais peçonhentos na Saúde Pública', NULL, '["Cláudio Maurício Vieira de Souza","Rosany Bochner"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-08-03', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Pharmacology, Toxicology and Pharmaceutics', 'O livro discute os múltiplos fatores que envolvem os acidentes e problemas de saúde causados por animais peçonhentos, especialmente entre as populações mais vulneráveis. Os dois autores são pesquisadores pertencentes a uma geração formada em um dos tantos momentos especiais da trajetória da saúde pública no Brasil: a implantação do Programa Nacional de Ofidismo, em 1986. Dividido em quatro capítulos, o volume tem caráter introdutório e busca provocar a curiosidade do leitor para algumas das dimensões envolvidas nos acidentes por animais peçonhentos. Dessa forma, a obra se distancia das abordagens que se concentram apenas nos aspectos biológicos e médicos dessas questões, mostrando como o modelo de atenção aos acidentes por animais peçonhentos vem funcionando como um ecossistema de políticas públicas do Sistema Único de Saúde (SUS).', '["venomous animals","snakebite","envenomation","public health","vulnerable populations","Unified Health System (SUS)","health policy","health care models","Brazil"]', '10.7476/9786557081624', '9786557081280', 'https://books.scielo.org/id/vpwt2', NULL, NULL, 'https://books.scielo.org/id/vpwt2/cover/cover_thumbnail.jpeg', 188, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vqy9k', 'vqy9k', 'Introdução à lógica', NULL, '["Cézar A. Mortari"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Computer Science', 'Na obra é defendido que a lógica é uma ciência apaixonante e viva, fruto de história de evolução e transformação. Essa mesma história é refletida neste livro, onde o autor pretende construir uma introdução aos desenvolvimentos e ao conteúdo dessa ciência.', '["logic","history of logic","philosophy of logic","introduction to logic"]', '10.7476/9788539303199', '9788571393370', 'https://books.scielo.org/id/vqy9k', NULL, NULL, 'https://books.scielo.org/id/vqy9k/cover/cover_thumbnail.jpeg', 393, 48, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THE