INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vr2dr', 'vr2dr', 'Dos sons às palavras: nas trilhas da Língua Portuguesa', NULL, '["Silvana Soares Costa Ribeiro","Sônia Bastos Borba Costa","Suzana Alice Marcelino Cardoso"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é uma homenagem a Jacyra Andrade Mota, renomada ex-professora do Instituto de Letras da UFBA. Seu conteúdo traz depoimentos de colegas provenientes de diferentes universidades brasileiras sobre esta educadora. Integram o livro 15 capítulos, apresentados em ordem alfabética dos nomes de seus autores.', '["Portuguese language","Portuguese language teaching","language teaching","university faculty"]', '10.7476/9788523211851', '9788523211851', 'https://books.scielo.org/id/vr2dr', 'https://books.scielo.org/id/vr2dr/pdf/ribeiro-9788523211851.pdf', NULL, 'https://books.scielo.org/id/vr2dr/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vrdnv', 'vrdnv', 'Correndo o risco: uma introdução aos riscos em saúde', NULL, '["Luís David Castiel","Maria Cristina Rodrigues Guilam","Marcos Santos Ferreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mostra como o risco se tornou um tema popular nas últimas décadas e como esse processo afetou o campo da promoção da saúde, incluindo questões associadas ao estilo de vida, à genética e aos contextos socioculturais. Além de discutir aspectos técnicos, metodológicos e teóricos, chama a atenção para exageros associados à percepção de constantes ameaças e à aversão obsessiva a todos os riscos. Embora – é claro – não faça apologia à exposição desenfreada a reconhecidas ameaças à saúde e à vida, adota uma postura crítica em relação ao comportamento “riscofóbico”, gerador de ansiedade e insegurança.', '["health risks","risk perception","risk aversion","health promotion","lifestyle","genetics","sociocultural context","anxiety","risk communication"]', '10.7476/9788575413104', '9788585471170', 'https://books.scielo.org/id/vrdnv', NULL, NULL, 'https://books.scielo.org/id/vrdnv/cover/cover_thumbnail.jpeg', 134, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vrht8', 'vrht8', 'Métodos de grupos terapêuticos on-line: e-terapias psicossociais', 'e-terapias psicossociais', '["Souza, Rozemere Cardoso de","Santos, Vanessa Thamyris Carvalho dos","Rocha, Raquel Silva"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro apresenta métodos inovadores de e-Terapias psicossociais, que unem ciência, acolhimento e conexão digital para promover saúde mental de forma acessível e impactante. Baseadas em práticas colaborativas e no uso estratégico de tecnologias, essas abordagens transformam grupos terapêuticos on-line em espaços de acolhimento e aprendizado. Ideal para profissionais que buscam novas formas de cuidado no mundo digital.', '["e-therapy","psychosocial interventions","digital mental health","mental health services","collaborative practice","online support groups"]', '10.7476/9788574556154', '9788574555966', 'https://books.scielo.org/id/vrht8', NULL, NULL, 'https://books.scielo.org/id/vrht8/cover/cover_thumbnail.jpeg', 261, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vrtc2', 'vrtc2', 'Segurança pública, redes e governança', NULL, '["Arthur Trindade M. Costa"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2023, '2023-10-17', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Atualmente no Brasil todos parecem concordar que a segurança pública é um problema que afeta diversos aspectos da vida social, política e econômica do país. A despeito dos esforços em aumentar os gastos na área, os presidentes, governadores e prefeitos eleitos nos últimos 30 anos têm fracassado em prover segurança para a população. O livro analisa por que a capacidade de resposta do Estado brasileiro aos problemas de segurança é tão precária. Não há dúvida que a redemocratização teve efeitos significativos sobre as polícias. Além das mudanças políticas, há outras profundas transformações na estrutura da sociedade que também têm afetado as rotinas, estratégias e objetivos do aparato de segurança pública. Se o surgimento dos regimes democráticos, a partir da segunda metade do século XX, transformou as polícias, a emergência da sociedade de risco está afetando profundamente o campo da segurança pública no início do século XXI. O maior desafio da atualidade é formular e implementar políticas públicas de segurança abrangentes que envolvam, além das polícias, atores estatais e não-estatais. O conjunto desses atores compõe redes de políticas públicas que requerem grande capacidade de governança. A configuração do campo da segurança pública brasileiro, tanto no nível estadual quanto no federal, produziu uma estrutura com baixa capacidade de governança, sendo, portanto, incapaz de dar respostas aos problemas que afligem à população. Assim, problemas como o aumento significativo nas taxas de homicídios, o crescente medo do crime e a superlotação das prisões, persistem por décadas sem que o Estado consiga dar alguma resposta efetiva.', '["public security","governance","public policy networks","police","redemocratization","risk society","state capacity","public security policy","homicide rates","fear of crime","prison overcrowding","Brazilian public security"]', '10.7476/9786558461708', '9786558461708', 'https://books.scielo.org/id/vrtc2', 'https://books.scielo.org/id/vrtc2/pdf/costa-9786558461708.pdf', NULL, 'https://books.scielo.org/id/vrtc2/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vs3n4', 'vs3n4', 'Autor e autoria no cinema e na televisão', NULL, '["José Francisco Serafim"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro busca compreender o lugar do autor e da autoria tanto em obras cinematográficas quanto televisivas, visando uma compreensão e problematização do status desse realizador ou criador através do processo de criação e de produção no qual essas obras estão inseridas. A questão da autoria se encontra longe de ter perdido o fôlego no debate acadêmico, pois tem suscitado um grande número de reflexões em trabalhos acadêmicos.', '["authorship","film authorship","television authorship","filmmakers","creative process","film production","cinema","television"]', '10.7476/9788523211745', '9788523206420', 'https://books.scielo.org/id/vs3n4', NULL, NULL, 'https://books.scielo.org/id/vs3n4/cover/cover_thumbnail.jpeg', 201, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
