.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vt39w', 'vt39w', 'Protagonismo Indígena: arranjos e conflitos nas sesmarias dos jesuítas', NULL, '["Rafael dos Santos Barros"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Essa obra procura compreender a atuação de um grupo indígena na Capitania dos Ilhéus durante a primeira metade do século XVII. As áreas possíveis para alimentação e caça foram tomadas pelas ocupações dos não índios, reduzindo as possibilidades dos povos indígenas viverem de acordo com seus hábitos. Inseridos nesse ambiente, estavam os índios Guerens, os quais usando a tutela de um capitão-mor conseguiram livrarem-se da opressão e tornarem-se súditos do rei de Portugal, permitindo-lhes sobreviv', '["indigenous protagonism","Jesuit missions","colonial Brazil","17th century","indigenous resistance","indigenous subsistence","hunting and fishing","Indigenous sovereignty","Portuguese colonialism"]', '10.7476/9786586213195', '9788574555126', 'https://books.scielo.org/id/vt39w', NULL, NULL, 'https://books.scielo.org/id/vt39w/cover/cover_thumbnail.jpeg', 272, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vtct6', 'vtct6', 'A universidade reformanda: o golpe de 1964 e a modernização do ensino superior', NULL, '["Luiz Antônio Cuñha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Luis Antônio Cunha apresenta uma análise histórico-sociológica do ensino superior nos primeiros anos do regime autoritário (1964-1968), revelando aspectos inéditos das mudanças efetuadas na época - a face modernizante da implantação de modelos norte- americanos, ao lado, é claro, do retrocesso político e educacional trazido pelo novo regime.', '["1964 coup","authoritarian regimes","higher education","university reform","higher education modernization","education policy"]', '10.7476/9788539304561', '9788571397712', 'https://books.scielo.org/id/vtct6', NULL, NULL, 'https://books.scielo.org/id/vtct6/cover/cover_thumbnail.jpeg', 304, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vtq2b', 'vtq2b', 'Segurança do Paciente: criando organizações de saúde seguras', NULL, '["Paulo Jorge dos Santos Sousa","Walter Vieira Mendes Junior"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Promover, proteger e recuperar a saúde é o que se espera dos serviços de saúde. Por isso, provoca espanto quando se fala que o processo de cuidado em saúde pode causar incidentes com danos. Alguns perigos são inerentes a esse processo – por exemplo, os efeitos colaterais conhecidos de determinados medicamentos. Outros podem ser consequências de erros, que acontecem em qualquer ramo de atividade, inclusive na saúde. Para fazer frente à frequência e à magnitude desses problemas, deve-se disseminar a cultura da segurança nos serviços de saúde, com o objetivo de melhorar a qualidade e os resultados desses serviços. Importantes contribuições nesse sentido podem ser encontradas nestes dois volumes. Os livros são desdobramento de um curso internacional de especialização em qualidade em saúde e segurança do paciente, oferecido na modalidade a distância (EAD) no âmbito de uma parceria entre a Escola Nacional de Saúde Pública da Fundação Oswaldo Cruz e a Escola Nacional de Saúde Pública da Universidade Nova de Lisboa. Especialistas brasileiros e portugueses produziram materiais didáticos para o curso, pois se verificou uma escassez de publicações sobre essas temáticas, sobretudo em língua portuguesa. Contudo, os materiais ganharam vida própria, independente do curso. Estruturadas de modo a suprir as reais necessidades de formação de médicos, enfermeiros, farmacêuticos, profissionais das tecnologias da saúde e gestores, as coletâneas têm por base conhecimentos e evidências que refletem o atual estado da arte em segurança do paciente. Os leitores – não só do Brasil e de Portugal, mas de toda a Comunidade dos Países de Língua Portuguesa (CPLP) – encontrarão subsídios para que, no dia a dia, mudanças na prática dos cuidados resultem em serviços mais seguros em todos os pontos da atenção à saúde.', '["patient safety","health care organization","safety culture","medical errors","adverse events","quality of care","health professions education","health management","Portuguese-speaking countries"]', '10.7476/9788575415948', '9788575415948', 'https://books.scielo.org/id/vtq2b', 'https://books.scielo.org/id/vtq2b/pdf/sousa-9788575415948.pdf', NULL, 'https://books.scielo.org/id/vtq2b/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vtxgm', 'vtxgm', 'Design, empresa, sociedade', NULL, '["Paula da Cruz Landim"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'O objetivo desta pesquisa foi verificar até que ponto a formação acadêmica ministrada nos cursos de design responde aos anseios da sociedade e do setor produtivo e o de coletar subsídios para a discussão da situação do ensino de design no Brasil e elaboração de estratégias que permitam sua melhoria de maneira a ter profissionais adequados ao desenvolvimento de produtos que, embora com a marca da nossa realidade e cultura, sejam também universais.', '["design education","design curriculum","academic training","industry needs","societal needs","design professionals","product development","universal design","Brazil"]', '10.7476/9788579830938', '9788579830938', 'https://books.scielo.org/id/vtxgm', 'https://books.scielo.org/id/vtxgm/pdf/landim-9788579830938.pdf', NULL, 'https://books.scielo.org/id/vtxgm/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vtyrz', 'vtyrz', 'Gattai e Amado: retalhos de automemoriografias', NULL, '["Ana Carolina Cruz de Souza"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro apresenta o estudo empreendido na pesquisa de doutorado em letras da autora para se repensar o lugar de Gattai e Amado no cenário da crítica literária contemporânea, a partir da suas inserções no espaço acadêmico.', '["literary criticism","contemporary literature","academic reception","Brazilian literature"]', '10.7476/9786588211106', '9788578873479', 'https://books.scielo.org/id/vtyrz', 'https://books.scielo.org/id/vtyrz/pdf/souza-9786588211106.pdf', 'https://books.scielo.org/id/vtyrz/epub/souza-9786588211106.epub', 'https://books.scielo.org/id/vtyrz/cover/cover_thumbnail.jpeg', 365, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vtzmp', 'vtzmp', '(Im)pertinências da educação: o trabalho educativo em pesquisa', NULL, '["Maria Lúcia de Paula Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro reúne textos de pesquisadores de diferentes instituições brasileiras de ensino e pesquisa, sobre questões da educação e em particular da educação escolarizada, que, sob diferentes perspectivas, focalizam relações que têm sido estabelecidas entre os campos da psicologia, da Psicanálise e da educação.Os problemas educacionais abordados têm em comum as conexões entre a formação do educador e a do educando, no âmbito da educação escolarizada.Os assuntos tratados são o lúdico na educação infantil, o jogo, a cognição e o afeto no desempenho escolar; a profi ssionalização docente (na educação infantil e no ensino fundamental); aprendizagem, fantasia e desenvolvimento emocional; orientação sexual e Aids; e Psicanálise e pesquisa na pós-graduação (na educação superior).Os trabalhos apresentados problematizam os rumos da educação escolar no Brasil, e oferecem-se como fundamento a refl exões sobre a educação em geral e, como tal, podem ser úteis à valorização do conhecimento acumulado pela aproximação entre campos de pesquisa independentes (o da psicologia e o da educação) sem que com isso se repita o passado psicologizante.', '["psychoanalysis and education","school education","teacher professional development","early childhood education","play","academic performance","emotion and cognition","teacher professionalization","fantasy","emotional development","graduate education","psychologization"]', '10.7476/9788579830228', '9788579830228', 'https://books.scielo.org/id/vtzmp', 'https://books.scielo.org/id/vtzmp/pdf/oliveira-9788579830228.pdf', NULL, 'https://books.scielo.org/id/vtzmp/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vv8vd', 'vv8vd', 'Ferramenta didática e lúdica para intensificar o aprendizado da Língua Brasileira de Sinais', NULL, '["Melquisedeque Oliveira Silva Almeida"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '"Com uma linguagem fácil e lúdica, o livro busca tornar conhecida a Língua Brasileira de Sinais - Libras, por meio do conhecimento da sua história, da língua propriamente dita e da escrita. Tendo como base o sistema Sign Writing, contribui para o ensino prático de estudantes de diversas áreas do conhecimento e interessados, sendo eles surdos ou ouvintes."', '["Brazilian Sign Language (Libras)","sign language education","SignWriting","deaf education","game-based learning","history of sign language","sign language literacy","teaching aids"]', '10.7476/9788574554914', '9788574554051', 'https://books.scielo.org/id/vv8vd', NULL, NULL, 'https://books.scielo.org/id/vv8vd/cover/cover_thumbnail.jpeg', 128, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vvcgn', 'vvcgn', 'Humanidades e ciências naturais: ensaios e balanços críticos', NULL, '["Márcio Barreto"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Sociedade de controle, big data, data science, sociedade da informação, cidades inteligentes, internet das coisas, inteligência artificial, datificação, sociedade de risco, tecnologia social, engenharia genética pertencem a que área do conhecimento? A especialização e a fragmentação do saber em áreas e subáreas estão em xeque, pois a complexidade das grandes questões contemporâneas rompe as fronteiras que separam natureza e cultura, arte e técnica, ambiente e sociedade, entre outras dualidades estabelecidas pelo hábito disciplinar. Humanidades e ciências naturais: ensaios e balanços críticos destina-se principalmente a cursos de graduação de ciências exatas e biológicas que têm em sua grade curricular disciplinas de humanidades, mas também é indicado para cursos de ciências humanas que pretendem um diálogo com as outras áreas do conhecimento.', '["science and humanities","interdisciplinary dialogue","society of control","big data","data science","information society","smart cities","Internet of Things","artificial intelligence","datification","risk society","social technology"]', '10.7476/9788526815452', '9786586253689', 'https://books.scielo.org/id/vvcgn', NULL, NULL, 'https://books.scielo.org/id/vvcgn/cover/cover_thumbnail.jpeg', 237, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vvp5w', 'vvp5w', 'Anulabilidad de las cláusulas abusivas', NULL, '["Gustavo Andrés Correa Valenzuela"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra presenta el problema del desconocimiento de la naturaleza jurídica del fenómeno denominado “cláusulas abusivas”, partiendo de la existencia de la gran diversidad de planteamientos y tratamientos jurídicos dados a dicho fenómeno a nivel internacional, con principal énfasis en el ordenamiento jurídico colombiano, donde se encuentran distintas concepciones y consecuencias para el mismo fenómeno. Ante dicha situación se pretende determinar cuál es la naturaleza jurídica de las cláusulas abusivas, los elementos y requisitos para que se configure dicho fenómeno jurídico para poder determinar cuál es la consecuencia jurídica que debe aplicarse al mismo, procurando una simetría entre una y otra, así como un entendimiento a mayor profundidad del fenómeno que tanta importancia ha cobrado a nivel internacional en los últimos años debido a la masificación y estandarización de la contratación en los distintos sectores económicos y comerciales, proponiendo que la consecuencia adecuada para una cláusula que constituya un abuso debe ser la anulabilidad o nulidad relativa de la misma. El planteamiento que se propone, enfocado en el análisis del contrato de seguros y la posibilidad de abuso de posición dominante contractual en la predisposición de las cláusulas a regir en dicho contrato, no obsta para que pueda ser aplicado a los demás contratos civiles y mercantiles, toda vez que al ser el mismo fenómeno jurídico del que trata la obra, la consecuencia de este ha de ser igual tratándose del mismo contrato en el que una de las partes se encuentre en la capacidad de determinar unilateralmente las condiciones que regirán la ejecución del contrato.', '["unfair contract terms","nullity of contract clauses","insurance contracts","abuse of dominant position","Colombian contract law"]', '10.7476/9789587386301', NULL, 'https://books.scielo.org/id/vvp5w', 'https://books.scielo.org/id/vvp5w/pdf/correa-9789587386301.pdf', NULL, 'https://books.scielo.org/id/vvp5w/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vvp6n', 'vvp6n', 'Antropoentomofagia: insetos na alimentação humana', NULL, '["Costa Neto, Eraldo Medeiros"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Uma coletânea de textos de diversos pesquisadores que é um marco significativo na história da antropoentomofagia latino-americana. Das centenas de milhares de espécies de insetos já catalogadas, mais de 1.780 são utilizadas como alimento pelas populações de cerca de 120 países. Embora seja vasta a literatura existente sobre o assunto, a cozinha entomofágica ainda permanece desconhecida e mesmo desprezada pela maior parte da população mundial, sobretudo nos países desenvolvidos. Entretanto, poucos discordariam de que a entomofagia constitui uma alternativa para alimentar parte considerável dos seres humanos.', '["entomophagy","insect consumption","edible insects","alternative food sources","human diet"]', '10.7476/9786589524977', '9788599799215', 'https://books.scielo.org/id/vvp6n', NULL, NULL, 'https://books.scielo.org/id/vvp6n/cover/cover_thumbnail.jpeg', 256, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vvw5c', 'vvw5c', 'CUT: os militantes e a ideologia', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este trabalho tem como objetivo, precisamente, o estudo do III CONCUT. Interessou-nos traçar um perfil dos delegados e efetuar uma análise das teses apresentadas, o que significa dizer analisar as tendências políticas presentes no III CONCUT. Porém, considerando que dificilmente a luta de facções, as resoluções e as modificações nos estatutos aprovadas no III CONCUT poderiam ser entendidas sem referência ao passado, fomos levados a efetuar uma rápida avaliação dos congressos anteriores da CUT. Desse modo, este estudo assumiu, um pouco forçadamente, o caráter de uma história da CUT. Queremos advertir, no entanto, que se trata de uma reconstituição histórica superficial.[...][trecho retirado da Apresentação do livro]', '["trade union congress","union delegates","political ideology","factionalism","union statutes","labor movement"]', '10.7476/9788579820243', '9788579820243', 'https://books.scielo.org/id/vvw5c', 'https://books.scielo.org/id/vvw5c/pdf/rodrigues-9788579820243.pdf', NULL, 'https://books.scielo.org/id/vvw5c/cover/cover_thumbnail.jpeg', NULL, 54, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vvx3m', 'vvx3m', 'Representações do Senado Romano na Ab Urbe Condita Libri de Tito Lívio: livros 21-30', NULL, '["Marco Antonio Correa Collares"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O presente livro trata das representações de Tito Lívio, historiador romano de finais do século I a.C., sobre o senado de Roma. As representações enquanto referências simbólicas, valores, crenças e concepções de mundo de indivíduos historicamente posicionados são comumente projetadas em textos e artefatos culturais que pretendem auxiliar no estabelecimento de consensos e normas de conduta em dada sociedade. Nesse sentido, o livro enfoca às opiniões do autor romano, inscritas em sua Ab Urbe Condita Libri (Desde o Início da Cidade), sobre a mais influente instituição da República, aquela que mais precisou se adaptar à nova situação política do Principado, no momento em que o poder foi centralizado por Otávio Augusto, primeiro Princeps- Imperador romano, sobrinho-neto e filho adotivo de Júlio César. A partir da constituição de uma narrativa histórica sobre a sociedade romana e suas instituições tradicionais, Tito Lívio estabeleceu normas de condutas para o senado imperial de sua própria época, vinculando-se indiretamente às políticas e às representações do primeiro Princeps-Imperador romano em seu relacionamento direto com o conselho dos patres.', '["Livy","Ab Urbe Condita","Roman Senate","representation","Roman Republic","early Roman Empire","Augustus","Roman institutions","historical narratives","Roman political thought"]', '10.7476/9788579830969', '9788579830969', 'https://books.scielo.org/id/vvx3m', 'https://books.scielo.org/id/vvx3m/pdf/collares-9788579830969.pdf', NULL, 'https://books.scielo.org/id/vvx3m/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vw52f', 'vw52f', 'Imprensa e cidade', NULL, '["Tania Regina de Luca","Ana Luiza Martins"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, as autoras abordam a trajetória das publicações periódicas brasileiras: o surgimento dos primeiros jornais e revistas, as transformações no processo de produção dos impressos, as mudanças em relação à estrutura interna, distribuição e natureza das matérias e dos recursos imagéticos disponíveis, a profissionalização e especialização do jornalista, a crescente segmentação dos periódicos, que se destinam a públicos e setores sociais cada vez mais específicos, sua atuação política e social em momentos decisivos da história do país, os interesses de que se fez (e se faz) porta-voz, os desafios impostos pela mundialização e novas tecnologias, que vêem alterando profundamente não só o modo de operar das redações mas também o sentido e o lugar social atribuído à imprensa.', '["Brazilian press","newspaper history","periodicals","press and politics","new technologies in journalism"]', '10.7476/9788539303168', '9788571395879', 'https://books.scielo.org/id/vw52f', NULL, NULL, 'https://books.scielo.org/id/vw52f/cover/cover_thumbnail.jpeg', 136, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vw9v4', 'vw9v4', 'Violência e Saúde na Vida de Pessoas LGBTI', NULL, '["Mário Felipe de Lima Carvalho","Moisés Santos de Menezes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-10-26', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Buscando tratar do tema da violência contra LGBTI em sua relação com o processo saúde-doença, esta publicação objetiva auxiliar gestores, profissionais e estudantes da área da saúde em um assunto muito pouco abordado nas formações profissionais, mas que está presente cotidianamente na realidade do trabalho em saúde.', '["violence against LGBTI people","LGBTI health","health-disease process","health professions education","health management"]', '10.7476/9786557081204', '9786557080450', 'https://books.scielo.org/id/vw9v4', NULL, NULL, 'https://books.scielo.org/id/vw9v4/cover/cover_thumbnail.jpeg', 147, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vwc8g', 'vwc8g', 'A construção do perfil do assistente social no cenário educacional', NULL, '["Maria Cristina Plana"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O tema do livro é a presença do Serviço Social na política educacional, como propositor e elaborador de projetos, levando-se em consideração o trabalho profissional realizado na educação em diversos estados e municípios brasileiros, desde a origem da profissão. A investigação foi teve como suporte a pesquisa bibliográfica, documental e de campo, realizada na Secretaria de Educação do município de Barretos/SP. A autora salienta a importância do Serviço Social em diversas cidades brasileiras e os projetos de lei existentes como proposta de se efetivar legalmente a atuação dos assistentes sociais na Educação. Ressalta ainda a crescente participação dos profissionais da área nas esferas estaduais e municipais, onde atuam em equipes interdisciplinares na elaboração de diretrizes e planos para uma educação de acesso a todos os cidadãos', '["social work in education","education policy","social work legislation","draft legislation","interdisciplinary teams","municipal education","Barretos","access to education","history of social work"]', '10.7476/9788579830389', '9788579830389', 'https://books.scielo.org/id/vwc8g', 'https://books.scielo.org/id/vwc8g/pdf/piana-9788579830389.pdf', NULL, 'https://books.scielo.org/id/vwc8g/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vwkqq', 'vwkqq', 'A luz na gênese do espetáculo', NULL, '["Eduardo Augusto da Silva Tudella"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"O livro trata de aspectos específicos das relações entre a luz e a cena, acentuando a necessidade de sua discussão no Brasil. Na obra, o autor faz a ponte entre os estudos teóricos e a reprodução da história do espetáculo, estudando não só a iluminação teatral, como outros elementos que fazem parte do discurso visual de uma práxis cênica. Com um extenso trabalho historiográfico, Tudella transita pela história da arte, da civilização e dos gregos até a atualidade, compreendendo o espetáculo como obra composta, cuja efetivação congrega o trabalho de diversos artistas."', '["stage lighting","theatre history","Greek theatre","Brazilian theatre"]', '10.7476/9788523218584', '9788523218584', 'https://books.scielo.org/id/vwkqq', 'https://books.scielo.org/id/vwkqq/pdf/tudella-9788523218584.pdf', NULL, 'https://books.scielo.org/id/vwkqq/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vwp7s', 'vwp7s', 'Violência, Samurais e o Bushido no cinema de Akira Kurosawa', NULL, '["Antônio Marcus Lima Figueiredo"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro trata do uso da violência encenada no cinema como recurso narrativo, expressivo e discursivo. Tomando as cenas de luta como locais privilegiados para examinar a relação entre cultura e cinema, a obra examina como a violência encenada significa nas obras do diretor japonês e como esse processo faz dialogar tradições cinematográficas orientais e ocidentais, com a cultura marcial propagada pela figura do samurai e por seu código de honra, o bushido, importantes elementos do nacionalismo japonês.', '["Akira Kurosawa","violence in film","samurai","bushido","honor codes","martial arts","Japanese nationalism","Japanese cinema"]', '10.7476/9786586213690', '9786586213454', 'https://books.scielo.org/id/vwp7s', NULL, NULL, 'https://books.scielo.org/id/vwp7s/cover/cover_thumbnail.jpeg', 197, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vwqsn', 'vwqsn', 'Caleidoscópio político: as representações do cenário internacional nas páginas do jornal O estado de S. Paulo (1938-1945)', NULL, '["Alexandre Andrade da Costa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro pretende-se analisar, por meio dos comentários publicados pelo jornal O Estado de S. Paulo, os rastros deixados pelos colaboradores que, durante os anos de 1938 a 1945, interpretaram os acontecimentos do campo internacional como transformadores da realidade interna. Nesse sentido, não se trata de estudar os fatos que marcaram a Segunda Guerra Mundial, mas sim de demonstrar de que modo os articulistas construíram imagens que se firmaram ao longo do tempo e que destoavam, em grande medida, das diretrizes propugnadas pelo Estado Novo.', '["O Estado de S. Paulo","international news coverage","Estado Novo","Brazilian press","World War II","political representation"]', '10.7476/9788579831133', '9788579831133', 'https://books.scielo.org/id/vwqsn', 'https://books.scielo.org/id/vwqsn/pdf/costa-9788579831133.pdf', NULL, 'https://books.scielo.org/id/vwqsn/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vx775', 'vx775', 'Desenvolvimento sustentável e tecnologias da informação e comunicação', NULL, '["Antônio Dias Nascimento","Nádia Hage Fialho","Tânia Maria Hetkowski"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Coletânea de textos que tem como tema principal as dimensões da contemporaneidade, do desenvolvimento local sustentável e a questão do emprego das tecnologias informacionais e comunicacionais na educação. Neste livro, contemporaneidade é compreendida como o delineamento de um modo de ser e de estar no mundo baseado na ideia de autonomia, de diálogo, de convivência pacífica e de valorização da vida.', '["sustainable development","information and communication technologies","sustainable local development","ICT in education","contemporary society","autonomy","dialogue","peaceful coexistence","value of life"]', '10.7476/9788523211790', '9788523211790', 'https://books.scielo.org/id/vx775', 'https://books.scielo.org/id/vx775/pdf/nascimento-9788523211790.pdf', NULL, 'https://books.scielo.org/id/vx775/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vxks7', 'vxks7', 'Tabulae scriptae: a metalinguagem e as trajetórias de Henri Pousseur e Willy Corrêa de Oliveira', NULL, '["Maurício Funcia de Bonis"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em meio aos debates (tão profícuos e numerosos quanto beligerantes) sobre os rumos da composição musical em meados do século XX, o questionamento sobre a natureza da relação a ser estabelecida com o passado (com a história da música) foi um tema privilegiado. Desde então sua pertinência crescente, na atrofia de uma prática social (e de uma linguagem comumente compartilhada) na música erudita, faz com que esse debate transcenda o contexto inicial da música de vanguarda das décadas de 1950 e 1960 e possa ser visto como um problema de base para a criação musical em nosso tempo. No enfrentamento em larga escala dessas questões, destacam-se as trajetórias de dois compositores, tanto em seu pensamento como em sua obra musical: Henri Pousseur (1929- 2009) e Willy Corrêa de Oliveira (nascido em 1938). A premissa dessa discussão, a saber, a oposição à tabula rasa da arte do passado (simbolizada aqui pela imagem das \"tábuas\" que não foram privadas de suas inscrições, \"tabulae scriptae\"), é enfrentada inicialmente pela contextualização das discussões sobre a abordagem da música erudita como linguagem em meados do século XX (e em torno da música contemporânea), para em seguida expandirmos esse universo com apontamentos de uma interpretação semiótica dessa linguagem e de sua relação com o modo de produção capitalista. Pousseur e Willy chegam paralelamente a conclusões similares, na apreciação da situação crítica da música contemporânea na sociedade atual como decorrente de uma crise generalizada das relações humanas, o que conduz a uma situação metalingüística: na ausência de uma linguagem comum, funcional, universalizante, a atividade do compositor se volta para a reflexão sobre a própria linguagem, no questionamento das premissas do processo de criação. As obras de Willy e Pousseur, de maneiras distintas (e autônomas, desenrolando-se paralelamente), registram um reflexo desse pensamento no recurso constante às mais diversas formas de operação metalingüística direta, na recuperação de materiais e procedimentos do passado (sob novas roupagens) na composição musical. Em capítulos separados, sucessivos, propomos uma apreciação panorâmica de cada uma dessas trajetórias para apontar a pertinência da operação metalingüística em suas obras de maneira geral, detalhando-a eventualmente em análises de algumas obras-chave. Antes de refletir sobre os pontos em comum e as diferenças mais marcantes entre essas duas trajetórias, insere-se ainda um testemunho de uma adesão a suas propostas, com a análise de composições de minha própria autoria', '["Henri Pousseur","metalinguage","music and language","music as language","contemporary music","avant-garde music","music composition","Brazilian composers","French composers","20th-century music","music semiotics"]', '10.7476/9788568334379', '9788568334379', 'https://books.scielo.org/id/vxks7', 'https://books.scielo.org/id/vxks7/pdf/bonis-9788568334379.pdf', NULL, 'https://books.scielo.org/id/vxks7/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vy5sg', 'vy5sg', 'A constituição da Universidade de São Paulo e a Reforma Universitária da década de 1960', NULL, '["Macioniro Celeste Filho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, Macioniro Celeste Filho apresenta as conexões entre dois acontecimentos determinantes para a implementação da reforma universitária na principal instituição de ensino superior brasileira, a Universidade de São Paulo (USP). Para compreender essa reforma, o autor busca também entender a formação da USP, recuando à década de 1930, quando diversas escolas politécnicas brasileiras, capitaneadas pela Escola Politécnica de São Paulo, lutavam pela primazia dentro das universidades que então se formavam.', '["Universidade de São Paulo","university reform","1960s","university constitution","Brazilian higher education history","technical schools","institutional history"]', '10.7476/9788539304868', '9788539304868', 'https://books.scielo.org/id/vy5sg', 'https://books.scielo.org/id/vy5sg/pdf/celeste-9788539304868.pdf', NULL, 'https://books.scielo.org/id/vy5sg/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vzqvt', 'vzqvt', 'Entre palavras: memória, estilo, transmissão', NULL, '["Urania Tourinho-Peres"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Com este livro, o Colégio de Psicanálise da Bahia, no momento em que comemora 30 anos de fundação, dá testemunho da sua prática institucional, voltada para a clínica e a formação do analista. Sempre buscando um modelo de funcionamento mais fiel à psicanálise, criou o Atelier e Laboratório Clínico como dispositivo de transmissão no qual a comunicação inconsciente em curso e a valorização do testemunho encontram-se no eixo do processo de formação do psicanalista. A obra não é apenas uma edição comemorativa, mas o testemunho da experiência de transmissão, em que, em cada capítulo, cada um(a) dos(as) autores(as) deixa entrever o que herdou como marca e o que deixou como rastro, em seu avanço como grupo em direção à consolidação de um estilo institucional.', '["psychoanalytic training","transmission of psychoanalysis","clinical workshops","clinical laboratory","witness testimony","unconscious communication","institutional memory","psychoanalytic group"]', '10.7476/9786556303857', '9786556300504', 'https://books.scielo.org/id/vzqvt', NULL, NULL, 'https://books.scielo.org/id/vzqvt/cover/cover_thumbnail.jpeg', 317, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-vzvnf', 'vzvnf', 'Escravidão e suas sombras', NULL, '["João José Reis","Elciene Azevedo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra reúne ensaios escritos pelos membros do grupo de pesquisa Escravidão e invenção da liberdade, vinculado ao Programa de Pós-Graduação em História da Universidade Federal da Bahia. Constituído por nove capítulos, sendo um deles escrito por João José Reis, um dos organizadores do livro, Escravidão e suas sombras traz temas como violência do tráfico de escravos e rituais africanos, reunidos em histórias que permitem uma leitura plural, transigente e aberta sobre os personagens e as instituições que compuseram a paisagem da escravidão e da liberdade no Brasil.', '["slavery","slave trade","African ritual","historiography of slavery"]', '10.7476/9788523211882', '9788523208462', 'https://books.scielo.org/id/vzvnf', NULL, NULL, 'https://books.scielo.org/id/vzvnf/cover/cover_thumbnail.jpeg', 369, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w2', 'w2', 'Argamassas tradicionais de cal', NULL, '["Cybèle Celestino Santiago"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Earth and Planetary Sciences', 'O livro faz uma retrospectiva sobre o que se pensava das argamassas de cal e alguns de seus constituintes ao longo dos séculos. Revela informações úteis tanto do ponto de vista histórico quanto para subsidiar obras de restauração através da análise de textos italianos, franceses, portugueses, espanhóis e brasileiros. É uma viagem no tempo, mostrando aspectos ligados à composição, ao preparo e às propriedades das argamassas elaboradas com esse aglomerante comentados à luz da ciência contemporânea.', '["lime mortar","mortar composition","mortar preparation","mortar properties","building restoration","lime binder","historical building materials"]', '10.7476/9788523208875', '9788523208875', 'https://books.scielo.org/id/w2', 'https://books.scielo.org/id/w2/pdf/santiago-9788523208875.pdf', NULL, 'https://books.scielo.org/id/w2/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w2qbk', 'w2qbk', 'A crítica que fez história: as associações literárias no Oitocentos', NULL, '["Milena da Silveira Pereira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'pulsar das associações literárias 67 3 Dos frutos impressos nas associações 111 4 Dos conselhos aos escritores 149 Considerações finais 201 Referências 207 O sumário mostra a procura em acompanhar o que Pereira, tão adequadamente, denominou "espírito associativo", desde os "prelúdios das agremiações" até o "inventar o Brasil pelas letras".A feliz forma proposta por Manuel Duarte Moreira de Azevedo que, em 1885, afirmou serem as associações instituições que "derramam a civilização, a instrução, iluminam os povos, esclarecem os espíritos", parece adequada para enunciar a projeção de trajetórias que buscaram apreender os desafios enfrentados na produção de uma cultura letrada e de histórias que, vazadas pela escrita, literariamente, contribuiriam para aproximações ao que seria o Brasil.Participar de uma associação literária nos é apresentado como passo fundamental e primeiro na formação de homens que ocuparam lugar importante no cenário intelectual brasileiro no período.Entre os extremos guardados pelos "prelúdios" e pela "invenção" do Brasil pelas letras, encontravam-se as prescrições para a apreensão das coisas da terra e da essência de seu povo e formação: "poetar com as coisas da terra", "romancear em torno da paisagem", por exemplo, podem constituir medida do quanto as "prescrições e sugestões do discurso crítico literário oitocentista encaminharam-se no sentido de forjar uma nacionalidade" e "narrar a história da recém-fundada nação brasileira, num extraordinário movimento, próprio desse tempo, em que essa crítica se confundia com a história literária e esta com a história do Brasil".Como orientadora, tive a oportunidade de acompanhar a trajetória de pesquisas e leituras, que, por sua vez, originaram novos debates com a historiografia, entrelaçando ideias e crescimento intelectual.O texto convida o leitor a percorrer um caminho possível de interpretação de intenções e desejos com relação ao Brasil, à constituição, construção ou invenção de suas histórias e produções literárias que, no limite, possibilitam o reconhecimento de sensibilidades que dizem respeito ao seu delineamento e traçado físico e intelectual -construção de alicerces, no dizer da autora. Marcia NaxaraAPRESENTAÇÃO "Cada um só pode pensar como se pensa em seu tempo."(Michel Foucault) Em 1827, o influente político e jornalista Evaristo Ferreira da Veiga (p.2), na apresentação de seu jornal Aurora Fluminense, manifestava que somente pelo "amor da ordem" e pelo "culto" da Constituição é que a "Mocidade Brasileira" conseguiria "dar ao nosso governo uma existência durável, aos nossos contemporâneos um exemplo de caráter, que para o futuro nos assegurar[ia] um lugar distinto entre as Nações civilizadas do antigo e do novo continente".Décadas mais tarde, em 1854, aquele que ficou conhecido como o "pai da historiografia brasileira", Francisco Adolfo de Varnhagen (p.11), afirmava que, ao projetar a árdua e longa empreitada de coligir documentos e escrever a História geral do Brasil, estava "desejoso de prestar este serviço ao país em que nasce[u]", ou seja, estava ávido por dar a conhecer aos brasileiros a sua história, estabelecendo "patrioticamente os fatos mais importantes".Em 1868, o respeitado político e professor de História e Geografia Candido Mendes de Almeida (p.8), ao publicar o seu pioneiro Atlas do Império do Brasil, dedicado ao que define como "eminente cultor das letras", o imperador D. Pedro II, declarava que o fim desse ambicioso trabalho era 1 O DESPERTAR DE UM ESPÍRITO ASSOCIATIVO "A nossa Portuguesa América que na produção de engenhosos filhos pode competir com Itália, e Grécia, não se achava com as Academias, introduzidas em todas as Repúblicas bem ordenadas [...].Não permitiu o Vice-Rei, que faltasse no Brasil esta pedra de toque ao inestimável ouro dos seus talentos, de mais quilates, que os das Minas.Erigiu uma doutíssima Academia, que se faz em Palácio na sua presença."(Rocha Pita, 1730) Prelúdios das agremiações Em 2 de julho de 1832, Francisco Cordeiro da Silva Torres, presidente da Sociedade Auxiliadora da Indústria Nacional (Sain), em sessão solene pronuncia: "um homem só, para que serve?[...] Quão diferente porém é este mesmo homem associado com outros!Põe em movimento, [...] resolve dificílimos problemas [...]! Onde não há associação, o mundo é pobre, é pouco, é rude" (O Auxiliador da Indústria Nacional, 1833, p.12).Do mesmo modo, anos depois, em 1852, Manuel Antônio Duarte de Azevedo (p.34), orador da Sociedade Ensaio Filosófico Paulistano, ao discursar na sessão inaugural O florescer das associações Frei Francisco de Monte Alverne (1784-1858), considerado pelos coetâneos o maior orador sacro do período, sobre a chegada da Corte portuguesa ao Brasil, em 1808, descreve: A chegada do príncipe Regente ao Brasil foi saudada como presságio de sua grandeza, e sua futura independência.Os grilhões coloniais estalaram um a um entre as mãos do príncipe, que a posteridade reconhecerá por o verdadeiro Fundador do império do Brasil.As artes, a indústria e o comércio floresceram à sombra do gênio criador deste Monarca generoso, para quem o Brasil era o sonho mais agradável de sua vida.Tudo que o Brasil possui em estabelecimentos de pública utilidade, teve nele sua origem.(Monte Alverne, 1856) Desde os tempos coloniais, é sabido, o espaço ocupado pela cultura escrita fora sempre muito limitado.A carência ou mesmo a 5 É importante mencionar que existiram tentativas de publicação no período colonial, como foi o caso da Oficina de Antônio Isidoro da Fonseca, que conseguiu, por intermédio do governador do Rio de Janeiro, Gomes Freire de Andrada, em 1847, a autorização para a instalação de uma tipografia, contudo, a duração foi bem curta, menos de um ano, e publicou somente três obras (cf.Hallewell, 2005, p.92-4).', '["literary societies","19th-century Brazilian literature","literary criticism","literary nationalism","national identity","literary history","Brazilian nation-building","literary criticism and history","Brazilian intellectual history","landscape in poetry"]', '10.7476/9788568334508', '9788568334508', 'https://books.scielo.org/id/w2qbk', 'https://books.scielo.org/id/w2qbk/pdf/pereira-9788568334508.pdf', NULL, 'https://books.scielo.org/id/w2qbk/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w32qz', 'w32qz', 'Ler Althusser hoje', NULL, '["Lucília Maria Abrahão e Sousa","Dantielli Assumpção Garcia"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Pensando na relevância e na singularidade dos trabalhos de Louis Althusser – filósofo que apareceu no cenário intelectual em 1965, com a publicação de A favor de Marx, seguida de Ler O Capital –, o livro Ler Althusser hoje busca refletir sobre os conceitos e as teses althusserianos, que se converteram no Brasil em objetos de análises. Ademais, intenta analisar o impacto da “filosofia” althusseriana na vida intelectual, considerando especificamente as contribuições do pensamento de Althusser aos campos da Análise de Discurso, da Psicanálise e das Ciências Humanas.', '["Louis Althusser","discourse analysis","psychoanalysis","human sciences","Marxist theory"]', '10.7476/9786580216178', '9786580216178', 'https://books.scielo.org/id/w32qz', NULL, NULL, 'https://books.scielo.org/id/w32qz/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w476f', 'w476f', 'O corpo feminino em debate', NULL, '["María Izilda Santos de Matos","Raquel Soihet"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'São recentes as preocupações de diferentes disciplinas e áreas do conhecimento em relação a questões que envolvem o corpo. Esta coletânea de escritos de pesquisadores brasileiros e europeus escolhe o corpo feminino como objeto particular para uma análise aprofundada de suas diferentes representações no discurso médico, legal, religioso, midiático, cotidiano, artístico e literário. Rastreando as concepções acerca do corpo da mulher desde a Grécia antiga, passando pelo Renascimento, até a sensualidade feminina presente nas festas populares do Rio de Janeiro, os onze escritos abarcam séculos de uma história feita de repressão, silêncio e resistência.', '["female body","medical discourse","legal discourse","religious discourse","media discourse","femininity","sensuality","popular festivals","Rio de Janeiro","history of the body","ancient Greece","Renaissance"]', '10.7476/9788539303311', '9788571394582', 'https://books.scielo.org/id/w476f', NULL, NULL, 'https://books.scielo.org/id/w476f/cover/cover_thumbnail.jpeg', 222, 114, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w48pz', 'w48pz', 'Amazônia na era do desenvolvimento: saúde, políticas e destruição, 1930-1966', NULL, '["Rômulo de Paula Andrade"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-12-02', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Na obra, o autor demonstra como as decisões políticas voltadas para a região amazônica durante o século XX tornaram-na um lugar estratégico para as instituições e as agências que tinham a saúde e a exploração da natureza como seus objetivos principais. Rômulo de Paula Andrade revela o processo de profundas intervenções na floresta e na vida das populações locais, analisando, com criatividade e rigor acadêmico, o modo como a região foi interpretada e transformada pelo Estado brasileiro a partir de 1930.', '["Amazon basin","health policy","deforestation","forest exploitation","health institutions","Amazonian populations"]', '10.7476/9786557082270', '9786557081464', 'https://books.scielo.org/id/w48pz', NULL, NULL, 'https://books.scielo.org/id/w48pz/cover/cover_thumbnail.jpeg', 395, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w4d2h', 'w4d2h', 'Antropologia de um jovem disciplinado: Darcy Ribeiro no serviço de proteção aos índios, 1947-1956', NULL, '["Carolina Arouca Gomes de Brito"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-11-18', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora analisa a trajetória de Darcy Ribeiro entre o fim da década de 1940 e meados da década de 1950, quando, recém-formado pela Escola Livre de Sociologia e Política de São Paulo (ELSP), ele passou a fazer parte dos quadros especializados do Serviço de Proteção aos Índios (SPI). Para esta análise, ela recorre aos textos do antropólogo e a material arquivístico do período citado, com grande ênfase na correspondência trocada entre ele e alguns intelectuais da época.', '["Darcy Ribeiro","indigenous protection","anthropology of indigenous peoples","intellectual correspondence","1940s-1950s"]', '10.7476/9786557081952', '9786557081914', 'https://books.scielo.org/id/w4d2h', NULL, NULL, 'https://books.scielo.org/id/w4d2h/cover/cover_thumbnail.jpeg', 202, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w4phd', 'w4phd', 'Memórias do cuidar: setenta anos da escola paulista de enfermagem', NULL, '["Márcia Barbieri","Jaime Rodrigues"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', '[RETIRADO/WITHDRAWN] Memórias do cuidar é a história de um centro de formação profissional que completa setenta anos: o curso de Enfermagem da atual Universidade Federal de São Paulo, criado em 1939. Desde a fundação do curso, valoriza-se a formação com ênfase no “cuidar” como objetivo precípuo das(os) enfermeiras(os). O ato de cuidar preconiza a ideia de que o bem-estar de quem precisa de cuidados deve ser alcançado.Os meios para isso se alteraram ao longo do tempo: do primado dos preceitos religiosos nas origens da Escola Paulista de Enfermagem, chegamos aos procedimentos científicos da atualidade. Assim, vocação e profissão complementam-se na memória preservada pelos arquivos e resgatada em depoimentos orais e fotografias, que embasam a elaboração dos textos aqui publicados. Os autores, em sua maioria, participaram ativamente desse processo histórico, o que faz do livro não apenas documento, mas testemunho de uma época.', '["history of nursing education","nursing care","professionalization of nursing","UNIFESP","oral testimony","institutional archives","history of nursing in Brazil"]', '10.7476/9788561673567', '9788561673567', 'https://books.scielo.org/id/w4phd', NULL, NULL, 'https://books.scielo.org/id/w4phd/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w4sy5', 'w4sy5', 'Climatologia escolar: saberes e práticas', NULL, '["Diego Corrêa Maia"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra aborda a Geografia Escolar, que tem como eixo norteador os conteúdos físico-naturais, no qual o tema clima e a previsão do tempo são abordados em sua plenitude no Ensino fundamental II. Este livro apresenta uma pesquisa voltada para a transmissão e apropriação de noções básicas do tema clima e a previsão do tempo, tendo como universo de pesquisa, a escola. O foco é sobre a formação de professores de geografia do ensino fundamental II, com intuito de desenvolver, avaliar e aplicar atividades didáticas, utilizando diferentes dispositivos didáticos, tais como, o “galinho do tempo” e uma estação meteorológica. A intervenção terá como meta principal promover a relação dialógica entre a sociedade e a natureza, empregando a pesquisa-ação como norteador metodológico.', '["climate change education","weather forecasting","geography education","geography teacher education","lower secondary education","teaching activities","meteorological station"]', '10.7476/9788595462830', '9788595462830', 'https://books.scielo.org/id/w4sy5', 'https://books.scielo.org/id/w4sy5/pdf/maia-9788595462830.pdf', NULL, 'https://books.scielo.org/id/w4sy5/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w57z2', 'w57z2', 'Aprendizagem baseada em problemas (PBL): uma experiência no ensino superior', NULL, '["Luis Roberto de Camargo Ribeiro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] A Aprendizagem Baseada em Problemas (ABP) ou PBL (Problem-based Learning) é uma metodologia de ensino e aprendizagem com larga utilização em escolas superiores (notadamente de medicina) e em outros níveis educacionais. Concebido no final dos anos 1960, o PBL, grosso modo, emprega problemas da vida real (reais ou simulados) para iniciar, motivar e focar a aprendizagem de conhecimentos conceituais, procedimentais e atitudinais. Além de apresentar uma introdução geral ao PBL, enfocando alguns aspectos principais (e.g., fundamentos, características, formatos e problemas), este texto descreve e discute uma experiência parcial da metodologia (em uma disciplina isolada em currículos convencionais) a partir da visão dos atores e de resultados de pesquisas, mostrando seus limites intrínsecos e contextuais e indicando os ganhos com relação ao desenvolvimento tanto discente quanto docente.', '["problem-based learning","university teaching","undergraduate curriculum","student-centered learning","medical education","real-world problems"]', '10.7476/9788576002970', '9788576002970', 'https://books.scielo.org/id/w57z2', NULL, NULL, 'https://books.scielo.org/id/w57z2/cover/cover_thumbnail.jpeg', NULL, 62, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w58cn', 'w58cn', 'Processo de enfermagem: história e teoria', NULL, '["Carla Argenta","Édlamar Kátia Adamy","Júlia Valéria de Oliveira Vargas Bitencourt"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Processo de Enfermagem: história e teoria apresenta um recorte histórico acerca da Sistematização da Assistência de Enfermagem (SAE) e Processo de Enfermagem (PE), considerando uma abrangência nacional, regional e local. O livro reúne subsídios para oferecer à comunidade a partir das atividades e ações ininterruptas de professores e estudantes da Universidade Federal da Fronteira Sul (UFFS), Universidade do Estado de Santa Catarina (UDESC), Universidade Comunitária da Região de Chapecó (UNOCHAPECÓ) e de enfermeiros da Associação Hospitalar Lenoir Vargas Ferreira (ALVF). Oportuniza ao leitor adentrar em aspectos teóricos relativos à metodologia do PE, destacando os Sistemas de Linguagens Padronizadas (SLP) que possuem interface com suas etapas. Além disso, possibilita alinhar o uso do PE a concepções e conceitos contemporâneos, como as melhores práticas e segurança do paciente, mostrando as interlocuções presentes na qualificação e no aprimoramento da assistência como princípios fundamentais das práticas em saúde. A expectativa é de que os leitores possam usufruir da produção desenvolvida para reprodução deste modelo de aplicação do PE devidamente ajustados as suas realidades. E, em última instância, que se cumpram de fato as resoluções legais e éticas da Enfermagem quanto ao PE, assim como se atinjam patamares de satisfação tanto profissional quanto dos usuários dos serviços em relação aos resultados da atenção à saúde oferecida.', '["nursing process","history of nursing","nursing care systematization","nursing theory","best practices","patient safety","nursing ethics","nursing legislation","nursing care quality","user satisfaction"]', '10.7476/9786586545234', '9786586545234', 'https://books.scielo.org/id/w58cn', 'https://books.scielo.org/id/w58cn/pdf/argenta-9786586545234.pdf', NULL, 'https://books.scielo.org/id/w58cn/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w5p4j', 'w5p4j', 'Críticas e Atuantes: ciências sociais e humanas em saúde na América Latina', NULL, '["Maria Cecília de Souza Minayo","Carlos Ε. A. Coimbra"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra apresenta debates sobre temas que são prioridade do pensamento social e da prática em saúde do continente. Aborda, do ponto de vista da antropologia, práticas de saúde e estudos de significados do corpo. No campo da história, traz trabalhos importantes sobre a historiografia das enfermidades na América Latina.', '["social sciences and health","Latin America","medical anthropology","health practices","body and meaning"]', '10.7476/9788575413920', '9788575413920', 'https://books.scielo.org/id/w5p4j', 'https://books.scielo.org/id/w5p4j/pdf/minayo-9788575413920.pdf', NULL, 'https://books.scielo.org/id/w5p4j/cover/cover_thumbnail.jpeg', NULL, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w5p77', 'w5p77', 'A cavalaria do mar: a guerra da expansão imperial portuguesa – séculos XV e XVI', NULL, '["Wellington José Gomes Freire"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A questão central, aquela que move o andamento do livro que ora o leitor tem em mãos é: qual a doutrina militar adotada pela arma militar terrestre portuguesa ao longo do processo expansionismo e conquista territorial que se estendeu pelos séculos XV e XVI? Dito de outra forma: como lutaram as tropas lusitanas durante as operações empreendidas em três continentes durante o período de conquista do seu império marítimo? A hipótese formulada é a de que ao longo da expansão imperial portuguesa, que se desdobrou por operações militales em três continentes, as tropas lusitanas lutaram animadas por um anacrônico espírito de cavalaria. Pleiteia-se que o princiapal componente tático-estratégico das ações ofensivas e defensivas da força militar terrestre e naval portuguesa foi o da persitência de um imaginário cavaleiresco. De um ponto de vista estritamente militar, a expansão imperial foi uma espécie de incursão da cavalaria do mar.', '["cavalry","Portuguese Army","Portuguese Navy","territorial conquest","15th century","16th century","military history"]', '10.7476/9786589524892', '9786589524175', 'https://books.scielo.org/id/w5p77', NULL, NULL, 'https://books.scielo.org/id/w5p77/cover/cover_thumbnail.jpeg', 520, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w5rx4', 'w5rx4', 'Biologia, manejo e medicina de primatas não humanos na pesquisa biomédica', NULL, '["Antenor Andrade","Márcia Cristina Ribeiro Andrade","Antonio M Marinho","Josane Ferreira Filho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Veterinary', 'O livro compila conceitos modernos e fundamentais sobre a criação em cativeiro de primatas não humanos de laboratório. Abarca matérias relacionadas ao bem-estar e à biossegurança na criação, experimentação, taxonomia, genética, biologia da reprodução, patologia, manejo, medicina e controle da qualidade das numerosas espécies de macacos existentes no Brasil, que têm contribuído largamente para o desenvolvimento de novas vacinas e pesquisas sobre o tratamento de doenças. Aborda também as novas normas e procedimentos que surgiram, nos últimos anos, para demonstrar a necessidade de sintetizar e unificar as boas práticas de instituições de pesquisa que utilizam animais de laboratório em suas investigações. A publicação contribui, assim, para promover a ciência e seu efetivo compromisso social. 53º Prêmio Jabuti 2011 - 3º lugar na categoria Ciências Naturais', '["non-human primates","laboratory animal husbandry","primate welfare","biosafety","primate medicine","primate reproduction","primate pathology","primate genetics","primate taxonomy","biomedical research","animal experimentation","good laboratory practice"]', '10.7476/9788575413050', '9788575411919', 'https://books.scielo.org/id/w5rx4', NULL, NULL, 'https://books.scielo.org/id/w5rx4/cover/cover_thumbnail.jpeg', 471, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w5w7c', 'w5w7c', 'Supersimetria aplicada a mecânica quântica: estudo da equação de Schrödinger', NULL, '["Elso Drigo Filho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Physics and Astronomy', 'Esta pesquisa sobre a sociedade paulista da primeira metade do oitocentos é tributária e também faz parte de um esforço para ampliar os estudos, investigações e interpretações deste amplo e diversificado painel historiográfico, literário e memorialístico. Retomando uma gama diversificada de documentos - jornais, como o Farol Paulistano, ofícios escritos por autoridades policiais, autos-cíveis, autos-crimes, atas, papéis avulsos e registros da Câmara, aquarelas, relatos de viajantes - e problematizando-os através da experiência da micro-análise, a autora procura infiltrar- se no tecido social urbano da cidade de São Paulo, entre os anos 1808-1850 e compreender outros contextos simultâneos ao da transmigração da família real para o Brasil, da implantação da Corte joanina, do processo de independência, das lutas regenciais e da implantação do Estado.', '["supersymmetry","Schrödinger equation","quantum mechanics","history of physics","São Paulo","19th century","police records","urban social history","Brazilian independence"]', '10.7476/9788539304523', '9788571399587', 'https://books.scielo.org/id/w5w7c', NULL, NULL, 'https://books.scielo.org/id/w5w7c/cover/cover_thumbnail.jpeg', 328, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w64j9', 'w64j9', 'Feminismo no cinema brasileiro: a representação das mulheres nordestinas nas telas', NULL, '["Carla Conceição da Silva Paiva"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O trabalho é uma reflexão sobre as representações das mulheres nordestinas presentes no cinema brasileiro da década de 1980 e a relação dessas encenações com o movimento feminista da época. Considerando que um filme apresenta muito da sua realidade social, partimos das relações existentes entre cinema e História e a Análise do discurso para decompor as imagens de Gabriela (1983); Parahyba, mulher-macho (1983); A Hora da estrela (1985) e Luzia-Homem (1987).', '["representation of women","feminist movements","film and history","discourse analysis","Northeast Brazil"]', '10.7476/9786588211281', '9788578873653', 'https://books.scielo.org/id/w64j9', 'https://books.scielo.org/id/w64j9/pdf/paiva-9786588211281.pdf', 'https://books.scielo.org/id/w64j9/epub/paiva-9786588211281.epub', 'https://books.scielo.org/id/w64j9/cover/cover_thumbnail.jpeg', 363, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w6k9d', 'w6k9d', 'Assistência Farmacêutica: gestão e prática para profissionais da saúde', NULL, '["Cláudia Garcia Serpa Osorio-de-Castro","Vera Lúcia Luiza","Selma Rodrigues de Castilho","Maria Auxiliadora Oliveira","Nelly Marin"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Se, no início dos anos 2000, a falta de acesso a medicamentos constituía um grande obstáculo à promoção da saúde, hoje, essa realidade já apresenta importantes sinais de mudança. Um exemplo é o expressivo aumento do número de pessoas com HIV/Aids que têm acesso aos medicamentos de que necessitam, resultado de iniciativas nacionais e internacionais. E, na construção desta nova realidade, o Brasil teve papel diferenciado e decisivo. É o que defendem os autores desta coletânea. Segundo eles, “ao lutar diuturnamente pela implementação de políticas de garantia do acesso universal a medicamentos no território nacional, o Brasil pôde demonstrar, com suas experiências exitosas, que países em desenvolvimento eram capazes de promover esse acesso”. Este livro - que vem preencher uma lacuna na área do ensino - busca não só compreender a consolidação da assistência farmacêutica, mas também fornecer referências para que ela continue avançando no Brasil. Afinal, apesar das conquistas, ainda existem vários desafios a serem enfrentados. Como os autores combinam o discurso científico com a experiência em serviço, os capítulos oferecem um embasamento acadêmico para responder às necessidades vivenciadas por gestores e profissionais, na prática. São, ao todo, 35 capítulos que abordam os mais variados tópicos: uso racional de medicamentos, recursos humanos, pesquisa, desenvolvimento tecnológico, produção, regulação sanitária, epidemiologia e assistência farmacêutica em desastres, entre outros. As experiências do Programa Farmácia Popular e de alguns estados e municípios também são analisadas no livro.', '["pharmaceutical care","access to medicines","universal access to medicines","rational drug use","health human resources","pharmaceutical R&D","pharmaceutical manufacturing","health regulation","epidemiology","Popular Pharmacy Program","HIV/AIDS treatment","Brazil"]', '10.7476/9788575415450', '9788575414422', 'https://books.scielo.org/id/w6k9d', NULL, NULL, 'https://books.scielo.org/id/w6k9d/cover/cover_thumbnail.jpeg', 461, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w7bd8', 'w7bd8', 'Agricultura Urbana: agroecologia, alimentação, saúde e bem-estar', NULL, '["Angélica Campos Nakamura","Guilherme Reis Ranieri"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-10-19', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro da coleção Temas em Saúde apresenta uma série de abordagens de diferentes áreas para apresentar as potencialidades da agricultura urbana e como ela se relaciona com a saúde e o bem-estar. O título busca mostrar, de forma didática, como assuntos diversos se relacionam com a agricultura urbana e quais são seus usos e práticas. Em quatro capítulos, os autores englobam temas como orgânicos e agroecologia, os principais impactos da agricultura convencional, as plantas alimentícias não convencionais e a relação entre hortas e políticas de promoção da saúde. A economia solidária e os diversos tipos de agricultura e sua importância na promoção da qualidade de vida também são assuntos levantados. A obra reúne ainda debates sobre as relações entre agricultura urbana, educação alimentar e educação ambiental, além de dicas para os leitores que querem começar e manter uma horta.', '["urban agriculture","agroecology","organic farming","non-conventional food plants","community gardens","health promotion policy","solidarity economy","quality of life","food education","environmental education","home gardening"]', '10.7476/9786557081198', '9786557080443', 'https://books.scielo.org/id/w7bd8', NULL, NULL, 'https://books.scielo.org/id/w7bd8/cover/cover_thumbnail.jpeg', 138, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w7mhx', 'w7mhx', 'Supervisão clínico-institucional: história, usos e sentidos na Reforma Psiquiátrica', 'história, usos e sentidos na Reforma Psiquiátrica', '["Disete Devera"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro tem como intuito registrar e difundir as histórias, usos e sentidos da Supervisão Clínico-Institucional (SCI) na Reforma Psiquiátrica brasileira. Algumas questões foram delimitadas a partir do percurso de pesquisa e atuação profissional da autora, tais quais: como as instâncias de formulação de políticas públicas tratam do tema da SCI? Quais os instrumentos normativos que possibilitaram a institucionalização da SCI no SUS? Quais referenciais teórico-metodológicos embasam a prática da SCI na saúde mental brasileira? Cenas, memórias e histórias trazidas por oito protagonistas da Supervisão Clínico-Institucional no Brasil estão presentes aqui, através de biografemas e entrevistas não estruturadas.', '["psychiatric reform","public policy","life stories","mental health professionals","history of psychiatry"]', '10.7476/9786559544448', '9786559544448', 'https://books.scielo.org/id/w7mhx', 'https://books.scielo.org/id/w7mhx/pdf/devera-9786559544448.pdf', NULL, 'https://books.scielo.org/id/w7mhx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w7q9z', 'w7q9z', 'Avaliação de políticas e programas de saúde', NULL, '["Lígia Maria Vieira-da-Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro se destina a profissionais, estudantes e pesquisadores que desejam realizar uma avaliação de políticas, programas ou práticas de saúde. O livro apresenta conceitos, abordagens e estratégias que resultam, em sua maioria, de métodos e técnicas testados pela autora e colaboradores ao longo dos últimos 20 anos em investigações avaliativas. Como o estudo da metodologia das avaliações não pode estar dissociado de investigações concretas, o livro traz variados exemplos, inclusive de articulação entre diferentes métodos: inquéritos populacionais, estudos ecológicos, estudos de caso, estimativas rápidas etc., além de técnicas de coleta de dados, como entrevistas estruturadas, entrevistas em profundidade, observação, análise documental etc. É feita a diferenciação entre pesquisa avaliativa e avaliação para a gestão. A primeira parte de uma pergunta não respondida pela literatura especializada e resulta em novos conhecimentos científicos. A segunda parte de uma pergunta estratégica para o gestor e resulta em conhecimentos relevantes para a tomada de decisões, como ampliar um programa, contratar pessoal, introduzir uma nova tecnologia etc. “Toda avaliação produz resistências, sobretudo por revelar problemas e insuficiências dos serviços e programas avaliados. Contudo, como todo conhecimento relevante, em algum momento, em algum lugar, poderá ser apropriado por gestores envolvidos com o aperfeiçoamento das políticas e práticas de saúde”, lembra a autora.', '["health policy evaluation","health program evaluation","evaluation methodology","evaluation research","health services","decision-making","mixed methods","data collection methods","resistance to evaluation"]', '10.7476/9788575415467', '9788575414439', 'https://books.scielo.org/id/w7q9z', NULL, NULL, 'https://books.scielo.org/id/w7q9z/cover/cover_thumbnail.jpeg', 110, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w84jx', 'w84jx', 'Behaviorismo radical: crítica e metacrítica', NULL, '["Kester Carrara"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '', '["radical behaviorism","B. F. Skinner","metacriticism","behaviorism"]', '10.7476/9788539302857', '9788571395848', 'https://books.scielo.org/id/w84jx', NULL, NULL, 'https://books.scielo.org/id/w84jx/cover/cover_thumbnail.jpeg', 438, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w8k6j', 'w8k6j', 'Desafios do planejamento na construção do SUS', NULL, '["Washington Luiz Abreu de Jesus","Marluce Maria Araújo Assis"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No contexto contemporâneo, é cada vez mais necessário abordar as políticas públicas de saúde, sobretudo o planejamento. Com um olhar crítico, os artigos presentes neste livro analisam os entraves e desafios do sistema e da gestão pública de saúde no Brasil em suas inúmeras perspectivas, provendo um debate sobre a necessidade e as possibilidades de uso de instrumentos de planejamento, principalmente na construção do SUS.', '["health planning","public health policy","public health administration","health system construction","planning instruments","Brazil"]', '10.7476/9788523211769', '9788523211769', 'https://books.scielo.org/id/w8k6j', 'https://books.scielo.org/id/w8k6j/pdf/jesus-9788523211769.pdf', NULL, 'https://books.scielo.org/id/w8k6j/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w9324', 'w9324', 'Participação e responsabilidade no jornalismo público', NULL, '["Daniele Ferreira Seridório","Danilo Rothberg"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro delineia o cenário de atuação de emissoras de televisão e examina o desenvolvimento da radiodifusão no Brasil e Reino Unido, construindo um quadro elucidativo sobre os relacionamentos estabelecidos entre emissoras de televisão e seus públicos, que exibe similaridades e contrastes entre práticas nacionais. Os resultados de tal esforço empírico indicam que o sistema britânico altamente regulado favorece o desempenho da porosidade, alavancada por processos, produtos e iniciativas organizacionais inovadores. Em contraste, no sistema brasileiro de radiodifusão desregulada, revelou-se fundamental o papel de instâncias de autorregulação: quando a regulação é insuficiente para fornecer as bases da responsabilização da mídia, há organizações que são compelidas, por vários motivos, a criar mecanismos autorregulatórios para remediar a escassez de dispositivos legais.', '["public journalism","television broadcasting","media accountability","media self-regulation","media regulation","television audiences","porosity","comparative media systems","media responsibility"]', '10.7476/9786559542468', '9786559542468', 'https://books.scielo.org/id/w9324', 'https://books.scielo.org/id/w9324/pdf/seridorio-9786559542468.pdf', NULL, 'https://books.scielo.org/id/w9324/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w9k2y', 'w9k2y', 'Periodismo universitario en el siglo XXI. Experiencias que transforman. Volumen II', NULL, '["Olga Behar Leiser"]', 'Editorial Universidad Santiago de Cali', 'Colombia', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Las experiencias didácticas e investigativas de docentes y estudiantes de comunicación social y periodismo se han transformado en Colombia cada vez más, en la medida en que avanza el Siglo XXI. En buena parte, se debe a que el ejercicio profesional ha sufrido impactos fuertes debido a la crisis de los medios tradicionales, la emergencia de nuevas generaciones mucho más digitales y a temas circunstanciales, como la pandemia del COVIDF-19. Indudablemente, el gran reto para la comunidad académica es transformar estas experiencias en habilidades y competencias que ofrezcan nuevos modelos de ejercicio profesional, ajustados a los nuevos tiempos pero también a las bondades de un ejercicio ético y de gran calidad. Aquí se diserta, como lo plantea Xiomara Montañez, coordinadora de la Red Colombiana de Periodismo Universitario –organización a la que pertenecen todos los autores- sobre técnicas de investigación, periodismo narrativo, semilleros de investigación enfocados en la literatura, la reportería y el periodismo; escenarios posibles para la prensa alternativa y popular; dilemas éticos y retos que se enfrentan en el trabajo colaborativo con universidades locales e internacionales; periodismo de fact checking; posverdad; medios universitarios y agenda periodística; y, en general, sobre cómo los medios universitarios pueden hacer aportes en divulgación y proyección en las comunidades que necesitan estar informadas.', '["college journalism","journalism education","social communication","digital journalism","COVID-19 pandemic","research seedbeds","literary journalism","alternative press","popular press","journalism ethics","post-truth","university media"]', '10.7476/9786287501751', '9789585147980', 'https://books.scielo.org/id/w9k2y', 'https://books.scielo.org/id/w9k2y/pdf/behar-9786287501751.pdf', NULL, 'https://books.scielo.org/id/w9k2y/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
