cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w9t2t', 'w9t2t', 'Autoria e leitura: uma revisão dos lugares de produção e interpretação', NULL, '["Baktalaia de Lis Andrade Leal"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este trabalho pretende estudar a interpretação, seus agentes e suas formas de percorrer os caminhos do sentido, até que se chegue a pensar no binômio leitor-texto. Então, lança-se um olhar sobre como o leitor se relaciona com o texto sempre em busca de uma significação mais econômica ou mais pessoal. Apresenta aos leitores uma revisão bibliográfica que abrange autores do campo das teorias de autor, texto, leitor e seus conflitos.', '["authorship","reading","reader-text relationship","interpretation","authorship theory","text theory","reader response","meaning-making","literary theory"]', '10.7476/9786588211366', '9786588211366', 'https://books.scielo.org/id/w9t2t', 'https://books.scielo.org/id/w9t2t/pdf/leal-9786588211366.pdf', NULL, 'https://books.scielo.org/id/w9t2t/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-w9yvd', 'w9yvd', 'Formação e evolução da grande empresa brasileira: estudos de caso embasados nas teorias da firma', NULL, '["Meirelles, Dimária Silva e"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', '[RETIRADO/WITHDRAWN] A trajetória da grande empresa tem sido abordada por vários autores do mundo econômico desenvolvido. A despeito da significativa presença de grandes empresas brasileiras, inclusive de atuação internacional, seu processo de formação e evolução tem sido pouco explorado, resultando na ausência de uma literatura acadêmica voltada especificamente para a discussão dos limites e dos dilemas envolvidos no crescimento empresarial brasileiro. Este livro é uma tentativa de registrar a história da formação e da evolução de importantes grupos nacionais e, ao mesmo tempo, apresentar para a comunidade acadêmica e para o público em geral o pensamento de alguns estudiosos de gestão empresarial acerca das teorias da firma.', '["large corporations","firm formation","business growth","theory of the firm","corporate groups","business evolution","management thought"]', '10.7476/9788582930496', '9788582930496', 'https://books.scielo.org/id/w9yvd', NULL, NULL, 'https://books.scielo.org/id/w9yvd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
