 publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wbpk6', 'wbpk6', 'Economia urbana e regional: território, cidade e desenvolvimento', NULL, '["Mônica de Moura Pires","Fernando Rubiera Morollón","Andréa da Silva Gomes","Mario Polèse"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O livro é composto por três partes. A primeira trata dos fundamentos da Economia Urbana e Regional, referindo-se às suas bases conceituais e analíticas e os fundamentos da Economia de Aglomeração. A segunda parte aborda a Economia Urbana, tratando das principais teorias da localização e do impacto da distância e do espaço sobre a atividade econômica. A última parte foca na Economia Regional para compreender a forma e a estrutura das cidades e a localização das atividades econômicas, ampliando o conjunto do território e introduzindo as possíveis políticas econômicas para enfrentar as desigualdades entre territórios.', '["urban economics","regional economics","location theory","spatial economics","urban structure","regional disparities","economic policy","territory"]', '10.7476/9788574554884', '9788574554884', 'https://books.scielo.org/id/wbpk6', 'https://books.scielo.org/id/wbpk6/pdf/pires-9788574554884.pdf', NULL, 'https://books.scielo.org/id/wbpk6/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wbzch', 'wbzch', 'Em torno de Hilda Hilst', NULL, '["Nilze Maria de Azeredo Reguera","Susanna Busato"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O dado de provocação desta pergunta ainda se faz presente, passados dez anos de sua morte .A escritora, poeta e teatróloga, nascida em Jaú, São Paulo, ganha nestes últimos tempos uma nova leitura e um interesse', '["Hilda Hilst","Brazilian women writers","Brazilian poetry","theatre","literary reception","Jaú"]', '10.7476/9788568334690', '9788568334690', 'https://books.scielo.org/id/wbzch', 'https://books.scielo.org/id/wbzch/pdf/reguera-9788568334690.pdf', NULL, 'https://books.scielo.org/id/wbzch/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wcdsj', 'wcdsj', 'Recursos humanos em saúde no Mercosul', NULL, '["Organização Panamericana de Saúde","Organização Mundial da Saúde"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Primeiro esforço coletivo de especialistas, tratando em profundidade da questão dos recursos humanos em saúde na Argentina, Brasil, Paraguai e Uruguai. O livro aborda o processo de integração e reflete sobre a situação do campo dos recursos humanos desses países, com enfoque para a formação, o exercício profissional e o mercado de trabalho - cruzando e analisando dados, comparando-os -, na busca do estabelecimento de um panorama real. Traz, ainda, o Tratado para a Constituição de um Mercado Comum (o Tratado de Assunção) e o Regulamento da Comissão Parlamentar Conjunta do Mercosul.', '["health human resources","healthcare workers","Mercosur","Argentina","Brazil","health professions education","professional practice","Treaty of Asunción","regional integration","comparative analysis"]', '10.7476/9788575413982', '9788575413982', 'https://books.scielo.org/id/wcdsj', 'https://books.scielo.org/id/wcdsj/pdf/organizacao-9788575413982.pdf', NULL, 'https://books.scielo.org/id/wcdsj/cover/cover_thumbnail.jpeg', NULL, 68, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wcgvd', 'wcgvd', 'O Recém-nascido de Alto Risco: teoria e prática do cuidar', NULL, '["Maria Elisabeth Lopes Moreira","José Maria de Andrade Lopes","Manoel de Carvalho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Seleção de textos abrangentes e atuais cobrindo tanto as principais patologias e intervenções relativas aos recém-nascidos gravemente enfermos quanto as áreas profissionais ao tema relacionadas. Registra mais de 20 anos de experiência de uma das mais competentes equipes de neonatologia do País - a do Instituto Fernandes Figueira/Fiocruz -, com sua inegável contribuição no campo da saúde da mulher e da criança. Referência fundamental para neonatologistas e para todos os envolvidos na assistência a recém-nascidos de alto risco.', '["high-risk infants","neonatal care","neonatal pathology","neonatal interventions","neonatology","newborn health","child health","maternal health"]', '10.7476/9788575412374', '9788575412374', 'https://books.scielo.org/id/wcgvd', 'https://books.scielo.org/id/wcgvd/pdf/moreira-9788575412374.pdf', NULL, 'https://books.scielo.org/id/wcgvd/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wcvbc', 'wcvbc', 'A indexação de livros: a percepção de catalogadores e usuários de bibliotecas universitárias. Um estudo de observação do contexto sociocognitivo com protocolos verbais', NULL, '["Mariângela Spotti Lopes Fujita","Vera Regina Casari Boccato","Milena Polsinelli Rubi","María Carolina Gonçalves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Computer Science', 'para observação do contexto sociocognitivo da indexação para catalogação de livros em bibliotecas universitárias: aplicação e análise', '["book indexing","library cataloging","academic libraries","librarian perceptions","library users'' perceptions","verbal protocols"]', '10.7476/9788579830150', '9788579830150', 'https://books.scielo.org/id/wcvbc', 'https://books.scielo.org/id/wcvbc/pdf/boccato-9788579830150.pdf', NULL, 'https://books.scielo.org/id/wcvbc/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wd', 'wd', 'Avaliação educacional: desatando e reatando nós', NULL, '["José Albertino Carvalho Lordêlo","Maria Virgínia Machado Dazzani"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A avaliação do contexto da instituição educacional pode ser vista de vários ângulos, desde o ponto de vista estritamente didático e das estratégias de avaliação da aprendizagem escolar até questões epistemológicas, sociais e políticas que estão implicadas na instituição educacional e em outras instituições que envolvem relações de saber-poder. Esse livro expressa um explícito compromisso com a qualidade e democratização da educação e praticando um diálogo que envolve muitas vozes. Esse compromisso será compartilhado com o leitor, especialista ou não.', '["educational assessment","learning assessment strategies","epistemology of assessment","power in education","democratization of education","educational quality","institutional evaluation"]', '10.7476/9788523209315', '9788523209315', 'https://books.scielo.org/id/wd', 'https://books.scielo.org/id/wd/pdf/lordelo-9788523209315.pdf', NULL, 'https://books.scielo.org/id/wd/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wdhwp', 'wdhwp', 'A formação das famílias livres: Campinas, 1774-1850', NULL, '["Paulo Eduardo Teixeira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em São Paulo, o aumento demográfico no século XVIII provocou a ocupação de novas porções do território, ampliando o espaço agrícola e empurrando progressivamente as fronteiras mais para o Oeste e para o Sul. Por trás desse aumento populacional, estava uma política colonial de povoamento, iniciada com a Restauração administrativa da Capitania de São Paulo, em 1765. Neste livro, Paulo Eduardo Teixeira elegeu a região de Campinas como lócus para seu estudo sobre a dinâmica demográfica em São Paulo, apontando as variáveis que interferiram e definiram a sociedade paulista no passado. A escolha desse município não foi aleatória. Ao longo de sua trajetória acadêmica, o autor dedicou parte de seus estudos a esse pequeno bairro da vila de Jundiaí que, no despontar do século XIX, tornou-se uma vila que atraiu os olhares de inúmeros migrantes. Tal conhecimento o aproximou das questões demográficas e, assim, Teixeira vislumbrou a oportunidade de estabelecer um diálogo profícuo sobre os sistemas demográficos no Brasil, principalmente porque para áreas de plantations isso ainda não foi realizado.', '["family formation","demographic history","colonial Brazil","Campinas","Jundiaí","population growth","plantation society","18th century","19th century"]', '10.7476/9786557145159', '9786557145159', 'https://books.scielo.org/id/wdhwp', 'https://books.scielo.org/id/wdhwp/pdf/teixeira-9786557145159.pdf', NULL, 'https://books.scielo.org/id/wdhwp/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wf547', 'wf547', '“Pressão Alta” no cotidiano: representações e experiências', NULL, '["Ana Maria Canesqui"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Este livro é o resultado de uma ampla pesquisa socioantropológica sobre as representações populares e as experiências com a hipertensão arterial sistêmica. A autora entrevistou homens e mulheres hipertensos diagnosticados há mais de um ano, com idades entre 50 e 65 anos, clientela de uma unidade de Saúde da Família na cidade de Amparo, no estado de São Paulo. A análise foi sensível às especificidades do modo de vida, das diferenças de gênero, idade e religião, atentando sempre para a maneira como os entrevistados cotidianamente refletem, lidam e atuam diante do adoecimento. O estudo foi realizado por meio de entrevistas conduzidas mediante roteiro, complementadas com observações e extensa investigação de documentos e bibliografia. Análises de conteúdo, das narrativas e estudos de caso foram utilizados. A autora também ouviu os agentes comunitários de saúde, pertencentes à equipe de Saúde da Família do local estudado. Ela descreve as características socioeconômicas, demográficas e educacionais da clientela e desses profissionais, conferindo especial atenção à forma como atendem e se relacionam com os pacientes.', '["systemic arterial hypertension","hypertension","illness experience","Family Health Strategy","community health workers","patient-provider relationship","gender differences","religion","lifestyle","middle-aged adults","Amparo, São Paulo"]', '10.7476/9788575415702', '9788575414699', 'https://books.scielo.org/id/wf547', NULL, NULL, 'https://books.scielo.org/id/wf547/cover/cover_thumbnail.jpeg', 306, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wg6hp', 'wg6hp', 'Política em São Paulo: uma análise da dinâmica político-partidária no estado', NULL, '["Rachel Meneguello","María Teresa Miceli Kerbauy"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro enfrenta dois grandes desafios. Em primeiro lugar, pretende demonstrar que partidos políticos continuam sendo instituições com capacidade representativa, possuem organização interna, formam quadros e têm importância junto ao eleitorado. Em segundo, busca descrever as características da política paulista, contemplando a organização dos partidos no estado bem como os efeitos da dinâmica eleitoral na definição de posicionamentos e de padrões de votação. O estado de São Paulo é um denso território político, com enorme complexidade estrutural, demográfica e socioeconômica. Conta com a presença de todos os partidos registrados no país, além de ser o principal ponto de origem e de formação dos dois partidos que conduziram a política democrática nacional durante mais de 20 anos, o PT e o PSDB. Nele, uma dinâmica partidária altamente fragmentada no âmbito dos municípios convive com a hegemonia de um só partido no governo estadual.', '["political parties","party dynamics","São Paulo state politics","electoral dynamics","party fragmentation","party dominance","Partido dos Trabalhadores (PT)","party organization","voting patterns","party representation"]', '10.7476/9786586253764', '9786586253412', 'https://books.scielo.org/id/wg6hp', NULL, NULL, 'https://books.scielo.org/id/wg6hp/cover/cover_thumbnail.jpeg', 384, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wg6rs', 'wg6rs', 'Baixada Santista: uma contribuição à análise geoambiental', NULL, '["Cenira Maria Lupinacci","Regina Célia de Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Os ambientes litorâneos foram os primeiros ocupados pelo homem europeu no Brasil e apresentam, nos dias atuais, elevados índices de urbanização.Aliado a esse fato, considera-se que tais ambientes apresentam elevado grau de suscetibilidade ambiental devido a suas características intrínsecas, tais como propriedades litológicas, hidrológicas, geomorfológicas, climáticas e biogeográficas.É neste contexto que se insere a região litorânea do estado de São Paulo, na qual a intensa atividade turística, os portos, as indústrias e o desenvolvimento urbano, associados a sua fragilidade, geram um alto grau de alteração.Na Baixada Santista, localizada no setor central do litoral do estado, a problemática principal relaciona-se à urbanização sobre os terrenos planos e inconsistentes da planície quaternária e sobre as vertentes íngremes dos Morros Isolados.Assim, têm-se problemas relacionados a enchentes, movimentos de massa nas encostas e instabilidade das fundações das construções.Já os riscos referem-se principalmente com uma possível expansão urbana sobre as vertentes íngremes da região serrana e o avanço da erosão das linhas de praia devido ao uso da terra e ao sistema de drenagem urbana, que direciona o escoamento pluvial para o setor da planície marinha.', '["Baixada Santista","coastal urbanization","flood risk","mass movements","foundation instability","coastal erosion","urban drainage","environmental sensitivity","land use change"]', '10.7476/9788568334553', '9788568334553', 'https://books.scielo.org/id/wg6rs', 'https://books.scielo.org/id/wg6rs/pdf/cunha-9788568334553.pdf', NULL, 'https://books.scielo.org/id/wg6rs/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wg88m', 'wg88m', 'Paisagens do consumo: São Paulo, Lisboa, Dubai e Seul', NULL, '["Sílvia Aparecida Guarnieri Ortigoza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '1. Regiões metropolitanas -Aspectos econômicos.2. Consumo (Economia).3. Consumidores -Atitudes.4.', '["consumer behavior","consumer attitudes","metropolitan areas","São Paulo","Lisbon","Dubai","Seoul"]', '10.7476/9788579831287', '9788579831287', 'https://books.scielo.org/id/wg88m', 'https://books.scielo.org/id/wg88m/pdf/ortigoza-9788579831287.pdf', NULL, 'https://books.scielo.org/id/wg88m/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wgg9f', 'wgg9f', 'Desenvolvimento regional: um problema político', NULL, '["José Otamar de Carvalho"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'de Otamar, e de sua enorme experiência na burocracia estatal, bem articular desenvolvimento rural, os processos migratórios, a dimensão ambiental e o planejamento regional, dentre aquelas múltiplas facetas do processo de desenvolvimento.Capacidade de abordagem necessária, mas cada vez mais escassa entre pesquisadores, consultores e "gente do Estado".Pontuaria aqui a sua lembrança em várias passagens das implicações sociais e econômicas de não se ter avançado na implementação de programas mais ousados de reestruturação e fortalecimento da agricultura e pecuária da região.Já Rômulo lembra de início, e Otamar trabalhará em todo o livro, as marcantes heterogeneidades estruturais presentes nas áreas subdesenvolvidas da Itália e do Brasil, demonstrando que as formas e dimensões da desigualdade são variadas e se entrelaçam.Chamo aqui atenção para a importante afirmação do primeiro de como "a concentração da renda determina uma estrutura produtiva espacialmente concentrada".Portanto, com dificuldade de gerar estruturas ocupacionais e urbanas mais descentralizadas, sólidas, dinâmicas e de qualidade.Rômulo lembra que quando a Sudene de Celso Furtado foi criada, "os governadores não eram interventores" da ditatura.Me espanta a atualidade de suas críticas às estratégias de combate às disparidades regionais em que "o voluntarismo de algumas políticas ou programas se choca com a dura realidade das estruturas de dominação e concentração".Por falar em atualidade de palavras ditas há exatos 35 anos, Otamar começa lembrando "o divórcio gradativo entre os centros de decisão e os elementos catalisadores das necessidades e expectativas das comunidades locais, em suas diferentes dimensões espaciais".Otamar nos informa que Celso Furtado defendeu, em seminário de discussão do GTDN, com a presença do Presidente Juscelino Kubitschek, que os dois grandes eixos de ação deveriam ser "criar uma economia resistente às secas e reestruturar a economia agrária, o bem-estar das áreas urbanas acomodadas, uma reversão do processo de concentração da renda e de concentração espacial, conforme expressam os seus interpretes mais lúcidos, entre os quais se destaca o Eng.Figueiredo Ferraz.Mas infelizmente a dinâmica da concentração, os interesses imediatistas a ela ligados, a própria capacidade de isolamento e evasão das elites relativamente ao assédio da marginalidade urbana retardam tal reversão.Estamos, sem dúvida, numa quadra em que é preciso cuidar do Nordeste nos dois planos.Nesse quadro, os debates sobre os problemas da Região e a experiência de desenvolvimento regional são de grande oportunidade.Uma contribuição valiosa vem dar o livro de Otamar de Carvalho, Desenvolvimento Regional, um Problema Político, no qual aborda problemas de política e administração do desenvolvimento regional e confronta as experiências da e da SUDENE.Esse trabalho prestará um grande serviço neste momento de retificação de rumos, graças à revisão histórica que realiza, às informações abundantes e criteriosas que fornece sobre os dois problemas regionais nos contextos dos planejamentos nacionais e, finalmente, às ideias que nos oferece o autor, com sua rica vivência no Brasil, partindo do Ceará para a SUDENE, e daí para cursos sobre desenvolvimento no exterior e o estudo comparativo de outras experiências regionais no mundo todo.Entre estas, a da Cassa per il Mezzogiorno foi a que mais influência exerceu no Brasil.Pouco ou mal conhecida entre nós, o serviço que Otamar de Carvalho presta à cultura brasileira ao expô-la e analisá-la em confronto com a da SUDENE merece o maior encômio.', '["regional development","political economy of development","Celso Furtado","SUDENE","regional disparities","income concentration","rural development","agricultural restructuring","regional planning","migration","environmental dimension of development","decentralization"]', '10.7476/9788578792770', '9788578792770', 'https://books.scielo.org/id/wgg9f', 'https://books.scielo.org/id/wgg9f/pdf/carvalho-9788578792770.pdf', NULL, 'https://books.scielo.org/id/wgg9f/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wgs9p', 'wgs9p', 'Capítulos de história dos comunistas no Brasil', NULL, '["Carlos Zacarias de Sena Júnior"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'aliança nacional libertadora (anl)Observações sobre ideias socialistas, anarquistas e comunistas', '["history of communism","socialist ideas","anarchism","communist ideology"]', '10.7476/9788523218737', '9788523218737', 'https://books.scielo.org/id/wgs9p', 'https://books.scielo.org/id/wgs9p/pdf/sena-9788523218737.pdf', NULL, 'https://books.scielo.org/id/wgs9p/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wgsq8', 'wgsq8', 'A revolução chinesa', NULL, '["Wladimir Pomar"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A Revolução Chinesa, em 1949, ampliou o bloco socialista e forneceu novos modelos para revolucionários em várias partes do mundo. Com a participação da China em instituições até recentemente controladas pelos países capitalistas, talvez seja possível dar início a uma reavaliação mais serena dos acontecimentos. Essa Revolução que intriga o Ocidente e as reformas promovidas pelo regime a partir de fins do século XX impõem a tarefa sempre renovada de esclarecer o perfil e os rumos dessa epopéia ainda não terminada.', '["Chinese Communist Party","socialist countries","revolutionary models","Western perceptions of China"]', '10.7476/9788539302710', '9788571394810', 'https://books.scielo.org/id/wgsq8', NULL, NULL, 'https://books.scielo.org/id/wgsq8/cover/cover_thumbnail.jpeg', 179, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wh35j', 'wh35j', 'Pesquisa na área biomédica: do planejamento à publicação', NULL, '["José Roberto Mineo","Deise Aparecida de Oliveira Silva","Mônica Camargo Sopelete","Geraldo Sadoyama Leal","Luiz Henrique Guerreiro Vidigal","Luis Ernesto Rodriguez Tapia","Maria Inês Bacchin"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Este trabalho se deu após verificar-se que a falta de uma discussão de forma sistemática das etapas que compreendem o método científico representam um obstáculo para aqueles que se propõem a trabalhar com a pesquisa na área biomédica. A intenção é que os leitores deste livro possam estar em contato com as etapas necessárias para a aplicação do método científico na área biomédica, contribuindo para que estas sejam amplamente discutidas e colocadas em prática.', '["biomedical research","scientific method","research planning","scientific publications","research stages"]', '10.7476/9788570785237', '9788570780850', 'https://books.scielo.org/id/wh35j', 'https://books.scielo.org/id/wh35j/pdf/mineo-9788570785237.pdf', 'https://books.scielo.org/id/wh35j/epub/mineo-9788570785237.epub', 'https://books.scielo.org/id/wh35j/cover/cover_thumbnail.jpeg', 273, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wh77w', 'wh77w', 'Geografia e filosofia: contribuição para o ensino do pensamento geográfico', NULL, '["Eliseu Savério Spósito"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Livro que aborda, como tema central, a construção do conhecimento geográfico, centrada no método científico, e resgata a teoria do conhecimento na sua relação com a realidade objetiva. O autor explica a estruturação de três métodos: hipotético-dedutivo, dialético e fenomenológico-hermenêutico e encaminha a discussão de conceitos, teorias e temas geográficos. Com linguagem clara e fluidez do texto, é possível uma leitura esclarecedora das reflexões relativas ao conhecimento científico e sobre fazer ciência.', '["geography and philosophy","geographical thought","scientific method","epistemology","objective reality","hypothetico-deductive method","dialectical method","phenomenological-hermeneutic method","doing science","philosophy of science"]', '10.7476/9788539302741', '9788571395145', 'https://books.scielo.org/id/wh77w', NULL, NULL, 'https://books.scielo.org/id/wh77w/cover/cover_thumbnail.jpeg', 220, 90, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-whjk2', 'whjk2', 'A cidade nas artes: da Colônia ao Império', 'da Colônia ao Império', '["Solange de Aragão"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A cidade brasileira do período colonial aparece em tratados descritivos, relatos de viagem, pinturas, aquarelas e em poemas do Barroco e do Arcadismo. É no século XIX, entretanto, que passa a ser representada com frequência em textos literários e em pinturas de viajantes e artistas brasileiros. Com o advento da fotografia, a partir da descoberta de Daguèrre em 1839, multiplicam-se as representações de paisagens urbanas do Brasil nas imagens produzidas por fotógrafos como Revert Klumb, Augusto Stahl, Marc Ferrez e Militão Augusto de Azevedo. A literatura, a pintura e a fotografia são fontes documentais relevantes para a construção da história da cidade brasileira. É preciso, contudo, lembrar que a cidade na arte é sempre uma representação – expressão dos vários olhares que convergem para a mesma paisagem. Esta obra procura investigar e demonstrar o modo como a cidade brasileira está presente na literatura, na pintura e na fotografia durante o período colonial e nas décadas que precederam o advento da República, assim como destacar a importância da arte como registro histórico da cidade.', '["urban representation","colonial Brazil","Brazilian Empire","urban landscape","photography","painting","literature","Baroque","daguerreotype","art as historical source","urban history"]', '10.7476/9786557145548', '9786557145548', 'https://books.scielo.org/id/whjk2', 'https://books.scielo.org/id/whjk2/pdf/aragao-9786557145548.pdf', NULL, 'https://books.scielo.org/id/whjk2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wj8zm', 'wj8zm', 'Paleoparasitologia', NULL, '["Luiz Fernando Ferreira","Karl Jan Reinhard","Adauto José Gonçalves de Araújo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'No que pode interessar à saúde das pessoas um livro sobre fezes, ainda mais sobre fezes fósseis? O tema — estranho a muitos possíveis leitores — torna-se fascinante ao revelar como surgiram as doenças e como determinados parasitos evoluíram com o hospedeiro humano em sua longa história evolutiva, tanto biológica como social. Ao surgir como espécie, o ser humano herdou diversos parasitos de seus ancestrais e outros foram adquiridos durante a ocupação dos continentes. Assim, seus vestígios orgânicos deixados nos sítios arqueológicos possibilitam traçar rotas da Pré-História, bem como revelar interessantes aspectos da vida no passado. O arcaico e o conhecimento de ponta juntam-se perfeitamente nos estudos de paleoparasitologia, ao identificar, nos vestígios de vida humana, fauna e flora de épocas remotas, uso de plantas e convívio com animais domésticos, e até mesmo períodos de abundância e escassez alimentar refletidos na saúde das populações.', '["paleoparasitology","coprolites","human parasitic infection","parasite evolution","human evolution","ancient human health","domestic animals","plant uses","prehistoric diet","archaeological site"]', '10.7476/9788575413456', '9788575411490', 'https://books.scielo.org/id/wj8zm', 'https://books.scielo.org/id/wj8zm/pdf/ferreira-9788575413456.pdf', NULL, 'https://books.scielo.org/id/wj8zm/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wjcqp', 'wjcqp', 'Frágeis e Invisíveis: saúde e condições de vida de pessoas idosas privadas de liberdade', NULL, '["Maria Cecília de Souza Minayo","Patrícia Constantino"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-05-10', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'São incontestes as relevantes contribuições que a presente obra traz, sobretudo para o campo da saúde coletiva, tanto do ponto de vista metodológico quanto do ponto de vista teórico-analítico, tornando-se leitura indispensável a quem utiliza as políticas públicas como objeto de estudo. É prodigioso como a autora nos revela seus estranhamentos e busca ampliar as conexões e os agentes numa ampla e ativa teia de significados e produção de sentidos. Seu texto é um convite à reflexão sobre as aparências, as normas instituídas, as possibilidades de subversão dos consensos, a produção de outras realidades e o acolhimento das diferenças. Também é um convite à elaboração de outros horizontes possíveis.', '["older prisoners","health of prisoners","living conditions","collective health","public policy","institutional norms","meaning production"]', '10.7476/9786557082249', '9786557081907', 'https://books.scielo.org/id/wjcqp', NULL, NULL, 'https://books.scielo.org/id/wjcqp/cover/cover_thumbnail.jpeg', 263, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wjkcx', 'wjkcx', 'Saúde e Espaço: Estudos Metodológicos e Técnicas de Análise', NULL, '["Alberto Lopes Najar","Eduardo Cesar Leão Marques"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Se até poucos anos a saúde pública centrava sua atenção mais em variáveis de natureza não-espacial, hoje necessita incorporar as ditas espaciais para compreender o complexo processo saúde-enfermidade-cuidado. Daí surgem novos métodos e técnicas que se agregam ao acervo funcional da área. Ao apresentar questões conceituais e metodológicas e suas aplicações na análise e interpretação de problemas específicos da saúde, este livro torna-se uma pioneira e valiosa contribuição em português a um novo campo que se abre: o do geoprocessamento aplicado à saúde.', '["health-environment relationship","health care access","spatial epidemiology"]', '10.7476/9788575412954', '9788575412954', 'https://books.scielo.org/id/wjkcx', 'https://books.scielo.org/id/wjkcx/pdf/najar-9788575412954.pdf', NULL, 'https://books.scielo.org/id/wjkcx/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wjwyx', 'wjwyx', 'História da idade média', NULL, '["María Guadalupe Pedrero-Sánchez"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '', '["Middle Ages","medieval history"]', '10.7476/9788539303113', '9788571392960', 'https://books.scielo.org/id/wjwyx', NULL, NULL, 'https://books.scielo.org/id/wjwyx/cover/cover_thumbnail.jpeg', 347, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wk5mr', 'wk5mr', 'Brasil, ano zero: estado, gênero, violência', NULL, '["Berenice Bento"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra transforma a perplexidade da realidade contemporânea em instigantes análises. A partir de questões que conectam o impeachment da ex-presidenta Dilma Rousseff, os reiterados ataques às questões dos gêneros e das sexualidades, o aumento da miséria e a eleição de Bolsonaro, os capítulos oferecem interpretações históricas à conjuntura sócio-política atual e seus personagens. O livro reúne a trajetória acadêmica e militante da autora, tal como suas percepções. Por fim, busca oferecer análises que negam dois tipos de determinismo: o que atribui à natureza biológica a explicação da produção das identidades; e o de caráter epistemológico que se caracteriza por atribuir valores absolutos a uma categoria analítica.', '["Dilma Rousseff impeachment","gender","sexuality","state","violence","poverty","identity construction","biological determinism","Brazilian politics"]', '10.7476/9786556303680', '9786556301839', 'https://books.scielo.org/id/wk5mr', NULL, NULL, 'https://books.scielo.org/id/wk5mr/cover/cover_thumbnail.jpeg', 257, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
