INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wmw76', 'wmw76', 'Vacinas, soros e imunizações no Brasil', NULL, '["Paulo Marchiori Buss","José Gomes Temporäo","José da Rocha Carvalheiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'O livro traz um perfil completo da área de vacinas no país. Subdivido em seis partes, aborda temas como a magnitude das doenças transmissíveis, política e regulação de vacinas e soros, pesquisa, desenvolvimento e inovação em vacinas, complexo produtivo da saúde, a experiência no Brasil, vacinas e imunizações e a experiência internacionais. Apresenta os resultados do projeto Inovação em Saúde, criado pela Fiocruz em 2001 para o desenvolvimento tecnológico e científico do país.', '["vaccines","immunoglobulins","immunization","vaccination policy","vaccine regulation","vaccine development","vaccine innovation","infectious diseases","Fiocruz"]', '10.7476/9788575416068', '9788575416068', 'https://books.scielo.org/id/wmw76', 'https://books.scielo.org/id/wmw76/pdf/buss-9788575416068.pdf', NULL, 'https://books.scielo.org/id/wmw76/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wn2t3', 'wn2t3', 'Memória impressa: brasileiros homenageados no Novo Almanaque de Lembranças', 'brasileiros homenageados no Novo Almanaque de Lembranças', '["Chaves, Vania Pinheiro","Luca, Tania Regina de"]', 'Editora UNESP', 'Portugal', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este volume da Coleção Brasil reúne dezenove artigos dedicados a figuras ilustres do Brasil com os respectivos retratos, que foram publicados na "seção inicial" do Novo Almanaque de Lembranças Luso-Brasileiro. A transcrição atualizada desses "elogios" é acompanhada por notas explicativas e por um breve comentário de cada um deles. Redigidas por especialistas, tais análises não abarcam por completo a personalidade distinguida na seção, centrando a atenção no texto que lhe foi consagrado.', '["commemorative portraits"]', '10.7476/9786557146637', '9789898577580', 'https://books.scielo.org/id/wn2t3', 'https://books.scielo.org/id/wn2t3/pdf/chaves-9786557146637.pdf', NULL, 'https://books.scielo.org/id/wn2t3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wnm5w', 'wnm5w', 'A larga barra da baía: essa província no contexto do mundo', NULL, '["Milton Araújo Moura"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Retomando a admiração que os cronistas do século XVI sentiam pela largura da Baía de Todos os Santos, esta obra consiste em uma coletânea de textos de diferentes autores contemporâneos, que, apesar de tratarem de assuntos distintos, possuem algo em comum: a Baía de Todos os Santos como metáfora e metonímia da Bahia, mais precisamente do Recôncavo e de Salvador. São seis capítulos, que fazem desde uma análise das crônicas dos estrangeiros sobre a capital baiana, até o axé music e a representação da Bahia no mercado musical.', '["Baía de Todos os Santos","Bahia","Recôncavo Baiano","Salvador, Bahia","16th-century chronicles","metaphor","metonymy","regional identity"]', '10.7476/9788523212094', '9788523212094', 'https://books.scielo.org/id/wnm5w', 'https://books.scielo.org/id/wnm5w/pdf/moura-9788523212094.pdf', NULL, 'https://books.scielo.org/id/wnm5w/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wnpbh', 'wnpbh', 'Pasolini: poesia, paixão e política', NULL, '["Alexandre Simões Pilati"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2023, '2023-08-18', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Pasolini: poesia, paixão e política apresenta dois núcleos de interesse: 1) a figuração poética dos impasses sociais do pós-guerra em As cinzas de Gramsci e, a partir daí; 2) a reflexão aguda e original sobre o fascismo, que acompanha toda a produção intelectual pasoliniana. Até segunda ordem, nenhum desses dois aspectos centrais têm a sua validade vencida. Ao contrário, parece que os paradigmas políticos, sociais, econômicos e culturais de hoje nos convocam, com ainda mais força, a voltar a pensar em Gramsci – e sua investigação funda dos elementos humanos capazes de nos levar a uma condição histórica nova – e em Pasolini – com sua abordagem herética do marxismo, que resulta em uma poesia civil autocrítica, impregnada com os problemas sociais, e em um pensamento corsário que denuncia incansavelmente os esquemas da permanência do fascismo no processo de “transição sem transformação” do capitalismo contemporâneo. Nesta obra, destaca-se a aproximação de Pasolini ao pensamento marxista. Como poucos, esse “pensador corsário” problematiza os limites da linguagem através de uma perfeita articulação entre as dimensões da poesia, da paixão e da política. Sua obra é uma rosa de beleza resistente, nascida num tempo entristecido pelo fascismo, que ainda é o nosso tempo. Mas a inteligência de Pasolini continua a vigiar, por trás das sombras, as possibilidades de um mundo novo.', '["Pier Paolo Pasolini","Antonio Gramsci","poetics","passion","politics","Marxism","critique of fascism","limits of language","contemporary capitalism","self-criticism"]', '10.7476/9786558461715', '9786558460954', 'https://books.scielo.org/id/wnpbh', NULL, NULL, 'https://books.scielo.org/id/wnpbh/cover/cover_thumbnail.jpeg', 184, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wnqq4', 'wnqq4', 'Desafíos educativos contemporáneos: educación salesiana para la innovación y participación en contextos de crisis', NULL, '["Villagómez Rodríguez, María Sol","Rivera, Celina","Iduriaga, Rubén","Marques, Luis","Lozano, Oscar"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este libro es el producto y la propuesta del quehacer intelectual, de la discusión y la investigación académica, de la preocupación pastoral y educativa de quienes conforman la red académica IUS Education Group de las Instituciones Universitarias Salesianas (IUS EG). Recoge las memorias del VI Seminario del IUS EG, que se llevó a cabo en la Universidad Politécnica Salesiana, sede Quito, del 26 al 28 de abril de 2022. El Seminario —así como su memoria— responde a tres ejes temáticos: “Desafíos educativo-pastorales de la educación superior salesiana en contextos de crisis”, “Formas y espacios para la participación juvenil” e “Innovaciones educativas para la educación superior en contextos de frontera”. Conferencias magistrales, trabajos de investigación y relatos de experiencia que se presentaron en los paneles y mesas temáticas, conforman esta memoria. Los enfoques innovadores, enmarcados en el modelo educativo y el carisma salesiano, constituyen una respuesta a los desafíos de la educación superior salesiana en contextos de crisis y abren la discusión para futuras investigaciones del colectivo académico.', '["educational innovation","youth participation","crisis situations","border context","pastoral education","university education"]', '10.7476/9789978108192', '9789978108192', 'https://books.scielo.org/id/wnqq4', 'https://books.scielo.org/id/wnqq4/pdf/villagomez-9789978108192.pdf', NULL, 'https://books.scielo.org/id/wnqq4/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wnvqt', 'wnvqt', 'Campo, floresta e águas: práticas e saberes em saúde', NULL, '["Fernando Ferreira Carneiro","Vanira Matos Pessoa","Ana Cláudia de Araújo Teixeira"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é uma reunião de processos territoriais distintos, inovadores, abertos, que se expõem à crítica, ao conhecimento de leitores, de estudiosos, de pesquisadores, de profissionais de saúde, demarcando que há um Brasil, dito remoto para muitos, o qual ainda não tem suas necessidades de saúde atendidas pelas políticas públicas. Mas são populações que têm sua história, sua identidade e seu modo de partilhar experiências, conhecimentos, vivências e continuar na luta por saúde e qualidade de vida sem negar o seu lugar, mas em sintonia e harmonia com o ambiente em que vivem.', '["health practices","traditional knowledge","health policy","quality of life","environmental health","indigenous and traditional communities"]', '10.7476/9786558460510', '9788523012045', 'https://books.scielo.org/id/wnvqt', 'https://books.scielo.org/id/wnvqt/pdf/carneiro-9786558460510.pdf', 'https://books.scielo.org/id/wnvqt/epub/carneiro-9786558460510.epub', 'https://books.scielo.org/id/wnvqt/cover/cover_thumbnail.jpeg', 464, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wny6k', 'wny6k', 'Organização do cuidado e práticas em saúde: abordagens, pesquisas e experiências de ensino', NULL, '["Marilene de Castilho Sá","Maria de Fátima Lobato Tavares","Marismary Horsth De Seta"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'O cuidado e seus desafios para a formação profissional, na melhoria da qualidade nos serviços de saúde e na experiência relacional. Esses aspectos estão presentes nos 16 artigos da coletânea Organização do Cuidado e Práticas em Saúde: abordagens, pesquisas e experiências de ensino, da Editora Fiocruz, organizado por Marilene de Castilho Sá, Maria de Fátima Lobato Tavares e Marismary Horsth De Seta. Os textos apresentados trazem interessantes análises que deslocam o olhar organizativo clássico, disciplinador de corpos e racionalizador de recursos, para expor processos sociais que revelam sofrimentos e desigualdades dos indivíduos, das populações e também dos profissionais. Ao mesmo tempo, abrem a possibilidade de construções criativas que apostam em novos fazeres, privilegiando os diálogos, as elaborações coletivas e a ressignificação de conceitos, como processo de trabalho, resultados, eficácia e eficiência na gestão da saúde. A necessidade de se debruçar sobre a temática do cuidado e das práticas em saúde surgiu do trabalho realizado nos últimos 12 anos pelo Departamento de Administração e Planejamento em Saúde da Escola Nacional de Saúde Sergio Arouca (Daps/Ens/Fiocruz), que vem desenvolvendo um conjunto de iniciativas voltadas para a avaliação e reordenamento de sua oferta de ensino lato e stricto sensu. O tema está entre as lacunas e os desafios da formação dos profissionais da área.', '["care organization","health practices","health management","health professions education","health services quality","relational experience","health disparities","collective work","health management education"]', '10.7476/9786557080573', '9788575416242', 'https://books.scielo.org/id/wny6k', NULL, NULL, 'https://books.scielo.org/id/wny6k/cover/cover_thumbnail.jpeg', 406, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wnz6g', 'wnz6g', 'Bioética e saúde: novos tempos para mulheres e crianças?', NULL, '["Fermín Roland Schramm","Marlène Braz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra busca responder a algumas questões de ordem ética e prática que surgem dentro de uma instituição voltada para a atenção sanitária terciária, onde é comum surgirem conflitos dos mais variados tipos e origens. Desse modo, procura traduzir as experiências de profissionais que pesquisam e trabalham no campo da bioética. Os artigos reunidos na coletânea tratam de questões que dizem respeito ao início da vida humana, passando pela discussão de outros temas também relacionados com a bioética, como saúde pública, deontologia, assistência materno-infantil, reprodução humana, ética na pesquisa com seres humanos e animais, genética e era pós-genômica, cuidados em saúde da mulher e da criança, entre outros.', '["bioethics","women''s health","child health","public health","medical deontology","maternal and child health services","human reproduction","research ethics","animal research ethics","genetics","post-genomic era","tertiary care"]', '10.7476/9788575415405', '9788575415405', 'https://books.scielo.org/id/wnz6g', 'https://books.scielo.org/id/wnz6g/pdf/schramm-9788575415405.pdf', NULL, 'https://books.scielo.org/id/wnz6g/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wp4sh', 'wp4sh', 'Adolfo Caminha: um polígrafo na literatura brasileira do Século XIX (1885-1897)', NULL, '["Carlos Eduardo Bezerra"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Trata-se, neste livro, do conjunto da obra de Adolfo Caminha - um polígrafo na literatura brasileira do século XIX - durante o período de 1885 a 1897. O estudo abrange não somente os seus textos ficcionais, mas também os seus escritos críticos e jornalísticos. Considera-se, portanto, a atuação do escritor como político, editor, leitor e crítico literário. Salienta-se que a escrita de Caminha se caracteriza por dois movimentos: um horizontal, que estende a sua obra, e outro vertical, que produz uma estética do aproveitamento, constituída a partir dos diálogos existentes entre um e outro dos seus fazeres. A obra apresenta uma contribuição original aos estudos sobre a literatura brasileira', '["Adolfo Caminha","Brazilian literature","19th-century literature","literary criticism","journalism","political participation","literary aesthetics"]', '10.7476/9788579830334', '9788579830334', 'https://books.scielo.org/id/wp4sh', 'https://books.scielo.org/id/wp4sh/pdf/bezerra-9788579830334.pdf', NULL, 'https://books.scielo.org/id/wp4sh/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wphz3', 'wphz3', 'Água e bacias hidrográficas: planejamento, gestão e manejo para enfrentamento das crises hídricas', NULL, '["Edson Luís Piroli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Ao longo da evolução do planeta, a água foi a principal responsável pela formação das bacias hidrográficas. Nas últimas décadas, a ocupação dessas bacias sem planejamento, gestão e manejo adequados provocou mudanças no ciclo e nos caminhos das águas, rompendo o equilíbrio dessas áreas. Solos ressecados e menos produtivos, erosões, assoreamentos, inundações, ilhas de calor, mudanças climáticas, doenças de origem hídrica, incêndios em áreas naturais e de produção agropecuária e crises hídricas são algumas das consequências da ocupação desordenada das bacias hidrográficas. Este livro aborda as temáticas da crise e da segurança hídrica, demostrando suas causas, consequências e alternativas para a reversão desses processos ou, pelo menos, para o enfrentamento dessas problemáticas, com redução de danos e melhor convivência das pessoas com a realidade atual, de profundas transformações nas bacias hidrográficas e na disponibilidade hídrica.', '["water crisis","water security","hydrological basins","watershed planning","watershed management","land use change","soil erosion","sedimentation","floods","urban heat island","climate change","waterborne diseases"]', '10.7476/9786557142981', '9786557142981', 'https://books.scielo.org/id/wphz3', 'https://books.scielo.org/id/wphz3/pdf/piroli-9786557142981.pdf', NULL, 'https://books.scielo.org/id/wphz3/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-wpvxt', 'wpvxt', 'Regionalismo na América do Sul: um novo esquema de análise e a experiência do Mercosul', NULL, '["Karina Lilia Pasquariello Mariano"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'máximo ou mínimo?55 3 Parlasul: o difícil equilíbrio entre discurso e prática 129 Regionalismo na América do Sul: reflexões finais 165 Referências 193 Apêndice: globalização regionalismo e as teorias de integração regional 205 APRESENTAÇÃOEste trabalho é uma reflexão sobre as experiências de integração regional, que enfatiza a importância das teorias para a explicação desses fenômenos e seus limites quando aplicados aos processos integracionistas fora da Europa.Partindo da constatação de que a teorização sobre essa questão é eurocêntrica, esta análise propõe um novo esquema analítico voltado principalmente para os países da América do Sul, num esforço de estabelecer parâmetros e indicadores capazes de apontar avanços e retrocessos nesses blocos.As análises dos processos de integração regional na América do Sul tendem a trabalhar sob duas perspectivas principais: avaliar os processos a partir dos resultados econômicos e das trocas comerciais, ou então a partir da sua similitude com o caso europeu.No primeiro caso, há uma tendência a desconsiderar a questão da institucionalidade e das interações entre os atores, ressaltando-se a questão dos conflitos e dos fluxos de comércio.A segunda perspectiva adota como parâmetro a experiência da União Europeia e preocupa-se em identificar em que medida esses regionalismos ocorridos fora do continente europeu aproximam-se de seu patamar de desenvolvimento institucional.Há nessa abordagem um certo otimismo em relação à integração porque entende-se que esta representa um novo comportamento nas relações entre os', '["regionalism","regional integration","Mercosur","South America","Eurocentrism","institutionalism","actor interaction","trade flows","European Union comparison","integration theory","analytical framework"]', '10.7476/9788579837043', '9788579837043', 'https://books.scielo.org/id/wpvxt', 'https://books.scielo.org/id/wpvxt/pdf/mariano-9788579837043.pdf', NULL, 'https://books.scielo.org/id/wpvxt/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
